// Act V, lot V1: the Descent under the Fenne. The gate of the Seal, Anselme's last parcels, the eve, then five floors
// that recall each act (the well, the forge, the chapel, the fort, the glacier), each with its crossroads, its returns
// of old faces, its fights and its side quest; the last passage (VE_glacier_fin) leads to VF_seuil (lot V2).
var ROUTE = "@route";
var RET = "@ret";
var A_PIP = { with: "pip", v: 10 };
var A_COL = { with: "coliane", v: 10 };
var A_GLO = { with: "gloup", v: 10 };
var A_CHA = { with: "charline", v: 10 };
var A_AUB = { with: "aubin", v: 10 };
var A_THA = { with: "thavary", v: 10 };
var A_MARQUE = { if: { mark: { min: 2 } }, v: 10 };
var A_EAU = { if: { item: "eau_claire" }, v: 10 };
// What it takes to bring the master back from the water (BIBLE 1.3: a loyal priest, clear water, or three clues on the Voice).
var SAUVER_MAITRE = { any: [{ item: "eau_claire" }, { all: [{ present: "aubin" }, { loyal: "aubin" }] }, { clues: "V", min: 3 }] };
// Thavary at the chapel (BIBLE 3): she betrays if she kept her secret and does not trust the hero; she wavers then stays if loyal.
var TRAHIT = { all: [{ present: "thavary" }, { has: "thavary:secret" }, { conf: "thavary", max: 49 }] };
var HESITE = { all: [{ present: "thavary" }, { has: "thavary:secret" }, { conf: "thavary", min: 50 }] };
var FIDELE = { all: [{ present: "thavary" }, { has: "thavary:aveu" }] };
// Veyra changes sides only with the whole truth and its proof (BIBLE 7).
var VEYRA_PREUVE = { all: [{ has: "R:revele" }, { has: "voix:nommee" }] };
var P = {};

Object.assign(P, {
  // ================================================================== the gate of the Seal
  V_route: { act: "V", title: "La porte sous la glace", place: "sceau", hub: true, backName: "la porte du Sceau",
    fx: { flag: "acte:V", ep: ["seance", 2000] },
    text: [
      { first: true, text: "Au pied du puits, la glace s'ouvre devant toi comme une gorge. Un couloir bleu, si bleu qu'il en devient noir dans les profondeurs, et qui descend en pente douce sous le ventre du glacier. Il fait un froid qui n'est plus celui du dehors : un froid immobile, sans vent, le froid d'une cave où l'on garde quelque chose depuis très longtemps. Tes pas sonnent. L'eau de fonte goutte du plafond, une goutte toutes les dix respirations, et chaque goutte fait le même bruit en tombant." },
      { first: true, text: "Au bout du couloir, la glace cesse et la pierre commence. Une paroi noire, lisse, taillée de main d'homme, et dans la paroi une porte haute de trois hommes, de bronze verdi, sans poignée, sans serrure visible. Au-dessus, un linteau. Sur le linteau, des mains. Tu les comptes sans le vouloir, comme on compte les marches d'un escalier qu'on connaît mal." },
      { first: true, text: "Tu as marché tout un automne pour arriver ici. Les Trois-Bornes, Brumefeuille, la commanderie, l'Isarde, la tour, la glace. Tu as dans ta besace ce que tu as gardé, et dans ta tête ce que tu as donné. Derrière cette porte, dit-on, il y a la Descente, et au bout de la Descente, ce que personne ne nomme." },
      { first: true, if: { is: { dragon: "purifie" } }, text: "Loin derrière toi, au bord du puits, une ombre immense se couche sur la glace, les ailes repliées, et attend. Ardhal ne peut pas te suivre par là : il te l'a dit. Il connaît un autre chemin, par la glace, et il dit qu'il te retrouvera en bas." },
      { first: true, if: { is: { dragon: "lie" } }, text: "Tu sens, là-haut, au bord du puits, la présence du dragon comme on sent une corde tendue au bout de son bras. Ardhal attend, couché sur la glace, parce que tu le lui as ordonné. La tache sur ta paume est tiède. Elle le tient." },
      { first: true, with: "pip", text: "Pip se tait. Il s'est posé sur ton épaule dès l'entrée du couloir, et il ne la quitte plus. Sa lumière tremble, toute petite, comme une flamme de chandelle dans un courant d'air qu'il n'y a pas." },
      { again: true, text: "La porte de bronze, les mains sur le linteau, la goutte qui tombe du plafond toutes les dix respirations. Le couloir de glace remonte derrière toi vers un jour que tu ne vois plus." },
      { again: true, if: { seen: "VE_anselme" }, text: "Près de l'entrée, la mule d'Anselme mâchonne du foin gelé, et le colporteur souffle dans ses doigts en recomptant sa marchandise." },
    ],
    choices: [
      { label: "Examiner la porte et ses mains", hide: { seen: "VE_porte" }, to: "VE_porte" },
      { label: "Le colporteur, à l'entrée du couloir", to: "VE_anselme" },
      { label: "Passer une dernière nuit devant la porte", hide: { seen: "VE_veillee" }, to: "VE_veillee" },
      { label: "Ouvrir la porte et commencer la Descente", big: true, if: { seen: "VE_porte" }, why: "Tu ne sais pas encore comment s'ouvre une porte sans poignée.", to: "VE_seuil" },
    ] },
  VE_porte: { act: "V", title: "Les six mains", place: "sceau",
    fx: { ep: ["perso", 800] },
    text: [
      "Il y a six mains sur le linteau. Pas cinq, pas cinq et un creux martelé comme sur les bornes de la Sorbe : six, sculptées dans le bronze, paumes ouvertes, côte à côte. Personne n'est descendu jusqu'ici pour effacer la sixième. Elle est plus petite que les autres, et plus fine, une main de jeune homme. Sous chacune, un nom. Aldar. Orine. Thavar. Hildre. Ivo. Sous la sixième, le bronze est lisse, poli, comme si quelqu'un y avait passé le pouce chaque jour pendant quatre cents ans.",
      "Au milieu de la porte, à hauteur de poitrine, trois creux. Un trou carré, de la taille d'un clou de charpente. Une cuvette ronde, qui pourrait recevoir le bord d'une cloche. Un anneau de bronze en relief, à la taille d'un doigt. Les trois creux sont froids. Autour, le métal est rayé de traces de lames, d'ongles, de pics : on a essayé d'ouvrir cette porte de force, il y a longtemps, et on n'y est pas arrivé.",
      { if: { relic: "clou" }, text: "Dans ta besace, le Clou de Hildre s'alourdit. Tu le sens tirer vers le trou carré comme un aimant tire la limaille." },
      { if: { relic: "cloche" }, text: "La Cloche d'Ivo, enveloppée dans son linge, se met à vibrer contre ta hanche, très bas, une note que tu sens dans tes dents plus que tu ne l'entends." },
      { if: { relic: "anneau" }, text: "L'Anneau de Thavar se resserre sur ton doigt, juste assez pour que tu le remarques." },
      { if: { relics: { max: 0 } }, text: "Tu n'as aucune des trois clés sur toi. Tu les as données, ou tu les as perdues, et la porte ne te connaît pas. Mais elle ne te repousse pas non plus." },
      "Tu poses la main à plat sur le bronze. Il n'est pas froid. Il est tiède, de la tiédeur d'une main qu'on serre, et il cède sous ta paume, d'un rien, comme une porte qu'on aurait seulement poussée, sans jamais la fermer à clé. Elle n'a jamais été fermée de ce côté-ci. Tout ce qui la tient, la tient de l'autre côté.",
      { if: { item: "VE_fausse_cle" }, text: "Par acquit de conscience, tu sors la clé qu'Anselme t'a vendue. Elle n'entre dans aucun des trois creux. Elle n'entre nulle part. Tu la ranges en te promettant de dire deux mots au colporteur." },
      { with: "pip", text: "Pip quitte ton épaule et va se poser sur la sixième main, au creux de la paume de bronze. Il y tient tout entier. Il reste là un long moment, immobile, à briller. « C'est chaud, dit-il. C'est la bonne taille. » Puis il revient sur ton épaule sans rien ajouter, et tu ne poses pas la question." },
    ],
    choices: [
      { label: "Poser ta main dans la sixième main", hide: { seen: "VE_porte_main" }, to: "VE_porte_main" },
      { back: "V_route" },
    ] },
  VE_porte_main: { act: "V", title: "La main de bronze", place: "sceau",
    fx: { flag: "V:main_posee" },
    text: [
      "Tu lèves le bras. La sixième main est un peu plus haute que les autres, et tu dois te mettre sur la pointe des pieds pour y poser ta paume. Ta main est plus grande que la sienne. Tu ne sais pas pourquoi tu t'attendais au contraire.",
      { if: { mark: { min: 1 } }, text: "La tache noire de ta paume touche le bronze, et le bronze frémit. Une fraction de souffle, quelque chose d'en dessous te reconnaît, et ce n'est pas de la joie. C'est de la faim, polie, patiente. Tu retires ta main. La tache est plus tiède qu'avant." },
      { if: { mark: { max: 0 } }, text: "Rien ne se passe, d'abord. Puis tu sens, très loin, très bas, sous des centaines de toises de roche, quelque chose comme un pouls. Lent. Fatigué. Un seul battement, puis un autre, longtemps après. Comme un vieillard qui dort mal." },
      "Quand tu redescends sur tes talons, il y a sur le bronze, à l'endroit de ta main, une buée qui s'efface lentement. Elle a la forme de tes doigts. Elle met longtemps à partir.",
    ],
    choices: [{ back: "VE_porte" }] },

  // ------------------------------------------------------------------ Anselme and the parcels from the first acts
  VE_anselme: { act: "V", title: "Le colporteur", place: "sceau", shop: "VE_anselme", backName: "la mule d'Anselme",
    fx: { meet: "anselme" },
    text: [
      { first: true, text: "Tu l'entends avant de le voir : les grelots de sa mule, absurdes, gais, dans ce couloir de glace où rien ne devrait faire de bruit. Anselme le colporteur a monté sa charrette jusqu'au bord du glacier par un chemin que tu ne connais pas, et il a laissé la charrette en bas pour monter la suite à dos de mule. Il a un bonnet de laine enfoncé jusqu'aux yeux, la moustache blanche de givre, et le même sourire qu'aux Trois-Bornes." },
      { first: true, text: "« Ah ! dit-il. Je savais bien que je vous rattraperais. On m'a confié des choses pour vous, figurez-vous, tout le long de la vallée. Des gens qui ne savaient pas où vous étiez, mais qui savaient qu'Anselme passe partout. » Il tapote les sacoches de la mule. « Et j'ai aussi ce qu'il faut pour descendre. Le dernier comptoir avant le fond du monde. Les prix sont en conséquence. »" },
      { again: true, text: "Anselme bat la semelle à côté de sa mule. « Vous avez oublié quelque chose ? On oublie toujours quelque chose. »" },
      { with: "coliane", first: true, text: "Coliane le regarde comme on regarde un chat qui s'est assis sur votre chaise. « Comment est-ce qu'il est arrivé avant nous ? » demande-t-elle, à personne en particulier. Personne ne lui répond." },
    ],
    choices: [
      { label: "Le paquet de Durn, le forgeron des Trois-Bornes", hide: { any: [{ not: { has: "durn:marteau" } }, { seen: "VE_colis_durn" }] }, to: "VE_colis_durn" },
      { label: "Le panier d'Aglaé", hide: { any: [{ not: { is: { aglae: ["libre", "ramenee"] } } }, { seen: "VE_colis_aglae" }] }, to: "VE_colis_aglae" },
      { label: "Les fioles de Lune, l'herboriste de Brumefeuille", hide: { any: [{ not: { has: "lune:remede" } }, { seen: "VE_colis_lune" }] }, to: "VE_colis_lune" },
      { label: "Le colis d'Isaure la bergère", hide: { any: [{ not: { has: "bergere:chien" } }, { seen: "VE_colis_isaure" }] }, to: "VE_colis_isaure" },
      { label: "« Personne d'autre ne m'a rien envoyé ? »", hide: { any: [{ seen: "VE_anselme_rien" }, { has: "durn:marteau" }, { has: "lune:remede" }, { has: "bergere:chien" }, { is: { aglae: ["libre", "ramenee"] } }] }, to: "VE_anselme_rien" },
      { label: "« Cette clé que vous m'avez vendue n'ouvre rien. »", hide: { any: [{ not: { item: "VE_fausse_cle" } }, { not: { seen: "VE_porte" } }, { seen: "VE_anselme_cle" }] }, to: "VE_anselme_cle" },
      { back: "V_route" },
    ] },
  VE_anselme_rien: { act: "V", title: "Les mains vides", place: "sceau",
    text: [
      "Anselme fouille ses sacoches pour la forme, puis il secoue la tête. « Rien à votre nom, non. Les gens donnent à ceux qui leur ont donné, voyez-vous. C'est un commerce comme un autre. » Il dit cela sans méchanceté, en commerçant, comme on constate qu'un marché a été mauvais cette année.",
      "Puis il sort de sa manche un petit gâteau de miel, un peu écrasé, enveloppé dans une feuille de chou. « Celui-là, c'est de moi. Il n'est pas sur la note. Ne le répétez pas, ça me ferait une réputation. »",
    ],
    fx: { food: 1 },
    choices: [{ back: "VE_anselme" }] },
  VE_anselme_cle: { act: "V", title: "La clé du Sceau", place: "sceau",
    text: [
      "Anselme prend la clé que tu lui tends, la retourne, la regarde avec un intérêt sincère, comme s'il la voyait pour la première fois. « Elle n'ouvre rien ? Ah. » Il réfléchit. « Elle ferme peut-être quelque chose, alors. On ne sait jamais avec les clés anciennes. »",
      "Tu attends. Il soupire, et te rend cinq sous, en pièces de cuivre, une à une, comme on s'arrache des dents. « Je ne rembourse jamais, dit-il. Que ça reste entre nous. Mais gardez la clé. Un jour, quelqu'un vous en offrira le double. »",
    ],
    fx: { gold: 5 },
    choices: [{ back: "VE_anselme" }] },
  VE_colis_durn: { act: "V", title: "Le paquet de Durn", place: "sceau",
    fx: { item: "VE_lame_durn", ep: ["perso", 600] },
    text: [
      "Un long paquet roulé dans une toile huilée, ficelé de chanvre, et sur la ficelle un bout de bois gravé au couteau d'une borne, une seule, grossière. Dedans, une lame. Une épée bâtarde, sans ornement, la garde en acier noirci, la poignée tressée de cuir de bœuf. Sur le talon de la lame, au poinçon, trois petites pierres levées.",
      "Un mot accompagne l'épée, écrit par quelqu'un qui n'écrit pas souvent, en lettres capitales qui penchent : *Avec le marteau que tu m'as rendu. Il frappe plus juste depuis. Rapporte-la, elle est à toi, mais rapporte-la. Durn.*",
      "Tu la soupèses. Elle tombe dans la main comme si on l'avait forgée en te regardant marcher.",
    ],
    choices: [{ back: "VE_anselme" }] },
  VE_colis_aglae: { act: "V", title: "Le panier d'Aglaé", place: "sceau",
    fx: { food: 3, conf: { gloup: 5 } },
    text: [
      "Un panier d'osier, recouvert d'un linge à carreaux, et sous le linge l'odeur qui te saute au visage avant même que tu l'aies soulevé : du pain de seigle, des saucisses sèches, un fromage dur comme une pierre, des pommes ridées, et une galette épaisse, au lard et aux oignons, telle qu'on la fait dans les cuisines où l'on a appris à nourrir des trolls.",
      { if: { is: { aglae: "ramenee" } }, text: "Un mot, dicté à quelqu'un qui sait écrire : *Je suis à la Lanterne, chez Mère Ternes, aux fourneaux. On mange mieux aux Trois-Bornes qu'on n'y a jamais mangé. Mange, toi. Aglaé.*" },
      { if: { is: { aglae: "libre" } }, text: "Un mot, dicté à quelqu'un qui sait écrire : *Je suis repartie chez ma sœur, à Sorbe. Elle dit que je cuisine comme une ogresse. Je prends ça pour un compliment. Mange chaud quand tu peux. Aglaé.*" },
      { with: "gloup", text: "Gloup s'est approché du panier en rampant, sans bruit, ce qui chez lui est un exploit. Il ne prend rien. Il regarde. Tu lui donnes le quignon du pain, et il l'engloutit avec un bruit si heureux que la mule d'Anselme recule d'un pas." },
    ],
    choices: [{ back: "VE_anselme" }] },
  VE_colis_lune: { act: "V", title: "Les fioles de Lune", place: "sceau",
    fx: { item: ["onguent", "onguent", "VE_tisane_lune"], ep: ["perso", 400] },
    text: [
      "Une petite caisse de bois, garnie de paille, et dans la paille trois fioles bouchées à la cire. Deux pots d'onguent qui sentent la sauge et le miel. Et une fiole plus grande, d'un vert sombre, avec une étiquette à l'écriture serrée de l'herboriste.",
      "*Contre la fièvre grise, la vraie, celle qui vient de l'eau. Jeannot Guérin court partout depuis la Toussaint, il a cassé deux carreaux chez Charron, sa mère dit que c'est votre faute. Une gorgée seulement, et pas à jeun. Lune.*",
      { if: { has: "jeannot:gueri" }, text: "Tu revois le petit, brûlant de fièvre dans son lit, la peau grise. Tu essaies de l'imaginer en train de casser des carreaux. Tu y arrives très bien." },
    ],
    choices: [{ back: "VE_anselme" }] },
  VE_colis_isaure: { act: "V", title: "Le colis d'Isaure", place: "sceau",
    fx: { item: "VE_echarpe_isaure", conf: { pip: 3 } },
    text: [
      "Un paquet mou, enveloppé de papier brun. Dedans, une écharpe de laine brute, grise et blanche, tricotée serré, longue à faire trois fois le tour du cou. Elle sent la bergerie, le suint, la fumée de tourbe. Il y a des poils de chien dedans. Beaucoup.",
      "*Poivre ne me quitte plus. Il dort sur mes pieds. La laine est de mes brebis, le tricot est de moi, les poils sont de lui. Il fait froid là où tu vas, à ce qu'on dit. Isaure.*",
      { with: "pip", text: "Pip plonge dans les plis de l'écharpe et n'en ressort qu'avec réticence, couvert de poils de chien, qui flottent autour de sa lumière comme des aigrettes de pissenlit." },
    ],
    choices: [{ back: "VE_anselme" }] },

  // ------------------------------------------------------------------ the eve before the gate
  VE_veillee: { act: "V", title: "La dernière veillée", place: "sceau", takes: "night", backName: "le feu devant la porte",
    fx: { rest: true, ep: ["perso", 1000] },
    text: [
      "Tu allumes un feu devant la porte, avec le bois que tu as monté du refuge des chasseurs, et le feu prend mal, comme s'il n'aimait pas l'endroit. La fumée monte droit, puis s'étale sous la voûte de glace. Tu manges sans faim. Derrière toi, le bronze garde la chaleur de ta main longtemps après que la nuit est venue au-dehors.",
      { with: "coliane", text: "Coliane affûte ses deux couteaux, l'un après l'autre, avec la pierre qu'elle tient de son frère. Elle le fait chaque soir. Ce soir, elle le fait plus longtemps. « Quand j'étais petite, à Hautgrès, dit-elle sans lever les yeux, on racontait que sous la Fenne il y avait un roi endormi avec une barbe qui faisait le tour de la montagne. Je n'aurais jamais cru que j'irais lui tirer la barbe. »" },
      { with: "gloup", text: "Gloup s'est mis le plus loin possible du feu, mais tourné vers lui, comme une bête qui a froid et qui a peur. De temps en temps, il glisse de quelques pouces vers les flammes, puis il recule. Il recommence toute la nuit." },
      { with: "charline", text: "Charline a ôté ses gants. Elle tend les mains vers le feu, et le feu se penche vers elle, docile, comme un chien qui reconnaît son maître. Elle le laisse faire. « Avant, dit-elle, je lui disais de se tenir tranquille. Maintenant, je le laisse venir. C'est plus reposant. »" },
      { with: "aubin", text: "Frère Aubin dit les complies à voix basse, le dos à la porte, la tête inclinée. Il s'arrête au milieu d'un psaume et reprend, plus bas encore. Tu ne sais pas s'il a oublié la suite ou s'il ne veut plus la dire." },
      { with: "thavary", text: "Thavary ne dort pas. Elle est assise, l'épée en travers des genoux, à regarder la porte, et quand tu te réveilles au milieu de la nuit, elle est toujours dans la même position. Tu ne sais pas ce qu'elle surveille : ce qui pourrait sortir, ou ce qui pourrait entrer." },
      { without: "any", text: "Tu es seul{e} devant le feu. Tu parles un peu, à voix haute, pour entendre une voix. La glace te la renvoie, plus grave, avec un temps de retard. Tu te tais." },
    ],
    choices: [
      { label: "Parler avec Pip de la main de bronze", with: "pip", hide: { seen: "VE_veillee_pip" }, to: "VE_veillee_pip" },
      { label: "Demander à chacun ce qu'il emporte en bas", hide: { seen: "VE_veillee_dons" }, with: "any", to: "VE_veillee_dons" },
      { label: "Dormir jusqu'au matin", back: "V_route" },
    ] },
  VE_veillee_pip: { act: "V", title: "La bonne taille", place: "sceau", with: "pip",
    fx: { conf: { pip: 8 } },
    text: [
      "Pip se pose sur ton genou, ce qu'il ne fait jamais, et il regarde le feu. « Tu te souviens, demande-t-il, quand tu m'as trouvé ? Dans la grande main, sous les trolls ? » Tu t'en souviens. La pierre fendue, la paume ouverte, cette lueur au creux qui tremblait. « Je ne me souviens pas d'avant, dit-il. J'ai essayé. Toute la route, j'ai essayé. Il y a un trou. »",
      "« Mais la main de la porte, tout à l'heure, elle avait la bonne taille. » Il réfléchit, de toute sa petite lumière. « Je crois que quelqu'un m'a tenu, avant. Quelqu'un avec des mains comme ça. Pas grandes. Chaudes. Je crois qu'il ne voulait pas me lâcher, et qu'il a fallu. »",
      "Il se tait. Le feu craque. « Est-ce qu'on va le voir, en bas ? » Tu ne sais pas quoi répondre. Pip n'attend pas de réponse. Il remonte sur ton épaule et s'y endort, si c'est le mot, sa lumière baissée jusqu'à n'être plus qu'une braise.",
    ],
    choices: [{ back: "VE_veillee" }] },
  VE_veillee_dons: { act: "V", title: "Ce qu'on emporte", place: "sceau", with: "any",
    fx: { conf: { coliane: 3, gloup: 3, charline: 3, aubin: 3, thavary: 3 } },
    text: [
      "Tu poses la question au feu plus qu'à eux : qu'est-ce qu'on emporte, quand on descend là où personne n'est remonté ? Un moment, personne ne répond.",
      { with: "coliane", text: "Coliane sort de sa chemise un lacet de cuir, et au bout un petit galet percé, gris, ordinaire. « Hautgrès, dit-elle. Le gué devant chez nous. Mon frère me l'a donné l'été de mes dix ans. Je le jetterai dans l'eau d'en bas. Je ne sais pas pourquoi. Pour qu'il y ait quelque chose de propre dedans. »" },
      { with: "coliane", if: { is: { coliane_arc: "vengeance" } }, text: "Elle range le galet. Ses mains, tu le remarques, ne tremblent plus depuis le camp des réfugiés. Tu ne sais pas si c'est une bonne chose." },
      { with: "charline", text: "Charline montre ses mains, la gauche surtout, celle de la brûlure. « J'emporte ça. Le feu que j'ai fait à sept ans. Il est encore là, tu sais. Il ne s'éteint pas. Je me disais qu'en bas, il servirait peut-être enfin à quelque chose d'utile. »" },
      { with: "charline", if: { is: { charline_arc: "pardon" } }, text: "« Mon père m'a dit de revenir, ajoute-t-elle plus bas. Il me l'a dit avec ses mains, enfin, avec ce qu'il en reste. Il les a posées sur ma tête. C'est la première fois depuis l'incendie. Alors je compte revenir. »" },
      { with: "aubin", text: "Frère Aubin ne montre rien. « J'emporte mes frères, dit-il. Tous. Je les porte depuis un an. Ils ne pèsent pas plus en bas qu'en haut. »" },
      { with: "aubin", if: { is: { aubin_arc: "offrande" } }, text: "Il te regarde, et il y a dans ses yeux une paix que tu ne lui connaissais pas, et qui te fait plus peur que tout le reste. Il a décidé quelque chose à la tour d'Hildre. Il ne te dira pas quoi ce soir." },
      { with: "thavary", text: "Thavary pose la main sur la garde de son épée. « L'épée de Thavar. Elle a quatre cents ans, comme le mensonge. Je compte la rendre propre. » Elle ne dit pas à qui." },
      { with: "gloup", text: "Gloup, lui, ne dit rien, puisqu'il ne dit jamais rien. Mais il roule jusqu'à toi, et il dépose à tes pieds un caillou qu'il a dû garder Dieu sait où depuis le Rouvre, un caillou couvert de bave, rond et lisse. Puis il le reprend, très vite, comme s'il avait changé d'avis, et le garde." },
    ],
    choices: [{ back: "VE_veillee" }] },

  // ------------------------------------------------------------------ the threshold: the descent begins
  VE_seuil: { act: "V", title: "Le premier pas", place: "sceau",
    fx: { ep: ["seance", 3000], reveal: "VE_l_puits" },
    text: [
      "Tu pousses la porte. Elle s'ouvre en silence, d'un seul mouvement, sur ses gonds de bronze que personne n'a graissés depuis quatre siècles, et se referme derrière toi de la même façon, lentement, pendant que tu regardes. Tu ne cherches pas à la retenir. Tu sais déjà qu'elle se rouvrira pour toi, plus tard, si tu remontes.",
      "De l'autre côté, un escalier. Il tourne à gauche et descend, taillé à même le roc, chaque marche creusée au milieu par des pieds qui n'existent plus. Sur la paroi de droite, à hauteur d'épaule, une rampe de fer, rongée, froide, et des anneaux scellés tous les dix pas, où l'on accrochait autrefois des lampes. Il n'y a plus de lampes. Il y a, très loin en bas, une lueur grise qui n'est ni le feu ni le jour.",
      "Et il y a l'odeur. Tu la reconnais aussitôt, comme on reconnaît la maison de son enfance les yeux fermés. Le bief de Brumefeuille. La vase, la farine mouillée, l'eau qui dort sous une roue. Elle monte d'en bas, de très loin, et elle t'attendait.",
      "Puis une voix, que tu connais aussi, qui ne vient de nulle part, qui vient de l'eau qui suinte sur les marches : « {hero}. Tu as mis si longtemps. Descends. Je t'ai préparé la maison. Tu y reconnaîtras tout le monde. »",
      { with: "pip", text: "Pip s'enfonce dans ton col. « Elle a rangé, chuchote-t-il. Elle a rangé comme pour des invités. Je n'aime pas ça du tout. »" },
    ],
    choices: [
      { label: "Descendre l'escalier vers la lueur grise", big: true, travel: "VE_r_puits" },
    ] },

  // ------------------------------------------------------------------ legs of the Descent
  VE_leg_escalier: { act: "V", title: "L'escalier des mains", place: null,
    text: [
      "L'escalier n'en finit pas. Tu comptes les marches, puis tu cesses de compter, puis tu recommences pour ne pas penser. Au bout de quelques centaines, les mains apparaissent sur la paroi. Des empreintes, d'abord, comme sous le château des trolls : des paumes posées à plat, en noir de fumée, toutes tournées vers le bas. Puis des mains sculptées, en relief, de plus en plus nombreuses, de plus en plus serrées, jusqu'à couvrir la paroi entière comme les écailles d'un poisson.",
      "Ce ne sont pas les mains des Six. Il y en a des milliers. Des grandes, des petites, des mains d'enfants, des mains auxquelles il manque un doigt. Ceux qui ont creusé cet escalier ont posé la leur dans la pierre fraîche avant de remonter, chacun, pour dire qu'ils étaient passés et qu'ils avaient poussé, eux aussi, dans le même sens.",
      { if: { has: "passe:ordre" }, text: "Le geste te revient sans que tu le décides. Celui qu'on t'a appris à la commanderie, le premier jour : le gant gris posé à plat sur la pierre de la chapelle, pour dire qu'on prend la garde. Tu ne savais pas, alors, d'où il venait." },
      { with: "charline", text: "Charline s'arrête devant une main plus petite que les autres, avec une brûlure en étoile au creux de la paume, et elle pose la sienne dessus. Elles ont exactement la même taille. Elle se tait. Elle reprend la descente un peu plus vite." },
    ],
    choices: [
      { label: "Poser ta main à côté des leurs", fx: { flag: "V:main_escalier", ep: ["perso", 500] }, back: ROUTE },
      { label: "Reprendre la route", back: ROUTE },
    ] },
  VE_leg_chaine: { act: "V", title: "Le pont de la chaîne", place: null,
    text: [
      "Le couloir débouche sur un vide. Un gouffre rond, si large que ta lumière n'en touche pas l'autre bord, et si profond qu'une pierre que tu lâches ne fait aucun bruit. Un pont de pierre le traverse, sans parapet, à peine plus large qu'une charrette. Et au milieu du gouffre, à dix toises du pont, une chaîne pend.",
      "Elle descend du haut, de la voûte que tu ne vois pas, et elle plonge dans le noir d'en bas. Chaque maillon est gros comme un tonneau. Le fer en est noir, piqué, couvert d'une mousse blanche qui pousse à l'envers. Elle reste immobile. Puis, au moment où tu es au milieu du pont, elle bouge : un tressaillement qui court de haut en bas, un frisson de fer, avec un grondement qui te remonte par les pieds. Comme un homme qui tire, de très loin, sur ce qui le retient.",
      "Puis elle se tait, et pend de nouveau, immobile.",
      { with: "aubin", text: "Frère Aubin s'est arrêté au milieu du pont, lui aussi, les yeux sur la chaîne. « Quatre cents ans, dit-il. À tirer une fois de temps en temps. Pour voir si elle tient toujours. » Il se signe. Ce n'est pas la chaîne qu'il bénit." },
      { with: "gloup", text: "Gloup s'est aplati sur le pont à s'y fondre, et il ne bouge plus jusqu'à ce que tu le prennes dans tes bras pour le porter de l'autre côté. Il est glacé et il tremble." },
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },
  VE_leg_source: { act: "V", title: "La source sous la roche", place: null,
    text: [
      "Au détour d'une galerie, un bruit que tu n'as pas entendu depuis la porte : de l'eau qui coule. Pas qui suinte, pas qui goutte : qui coule, vive, claire, en chantant. Une source sort de la paroi par une fente large comme un doigt et tombe dans une vasque taillée, débordante, puis se perd dans une rigole qui descend avec toi.",
      "Elle est claire. Tu la regardes longtemps avant d'y croire. Pas une trace noire, pas une odeur. Quelqu'un a gravé au-dessus de la vasque, d'une main sûre, en lettres anciennes : *Ici je me suis lavé les mains pour la dernière fois.* Il n'y a pas de nom.",
      { if: { mark: { min: 1 } }, text: "Ta paume te brûle, à quelques pas de l'eau. La tache n'aime pas cette source. Elle se rétracte, se tord, tire vers l'arrière comme un chien qu'on emmène au bain." },
      { with: "aubin", text: "Frère Aubin s'agenouille au bord de la vasque, y trempe les doigts, les porte à son front. « Il était guérisseur, dit-il doucement. Les guérisseurs se lavent les mains. »" },
    ],
    choices: [
      { label: "Plonger ta main marquée dans l'eau claire", tag: "Marque −1", hide: { mark: { max: 0 } }, fx: { mark: -1, pv: -8, flag: "V:source_lavee", ep: ["seance", 1500] }, to: "VE_leg_source_lavee" },
      { label: "Remplir une fiole à la source", hide: { has: "V:source_fiole" }, fx: { item: "eau_claire", flag: "V:source_fiole" }, back: ROUTE },
      { label: "Boire, et reprendre la route", fx: { pv: 6 }, back: ROUTE },
    ] },
  VE_leg_source_lavee: { act: "V", title: "L'eau claire", place: null,
    text: [
      "Tu plonges la main jusqu'au poignet. L'eau est si froide qu'elle te coupe le souffle, puis elle n'est plus froide du tout : elle brûle. La tache se défend. Elle s'accroche à ta peau, s'enfonce, cherche à remonter le long des veines, et c'est comme arracher une sangsue grosse comme un œuf. Tu cries. Tu ne retires pas ta main.",
      "Quand tu la retires enfin, la paume est rouge, à vif, et la tache est plus petite. Pas partie : plus petite, ses bords rentrés, pâlie comme une encre qu'on a lavée. Dans la vasque, l'eau a noirci un instant, à l'endroit de ta main. Puis la source l'a emportée, et elle est redevenue claire.",
      "Tu restes assis{e} sur le bord, la main contre la poitrine, à attendre que ça cesse de battre. Ça met longtemps.",
      { with: "coliane", text: "Coliane s'accroupit à côté de toi et te tend un chiffon propre, en silence. Elle regarde ta paume. Puis elle te regarde toi, et pour la première fois depuis longtemps, elle ne compte pas tes mains." },
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },
  VE_leg_ossuaire: { act: "V", title: "Les gants gris", place: null,
    text: [
      "Une salle basse, aux voûtes de pierre, avec des niches tout autour, du sol au plafond. Dans chaque niche, des os. Bien rangés : le crâne devant, les longs os derrière, et sur le crâne, posé, un gant de cuir gris que le temps a rendu noir et dur comme du bois. Des centaines de niches. Des centaines de gants.",
      "Les frères de l'Ordre de la Main. Ceux qui descendaient vérifier, autrefois, que la porte tenait, et qui ne remontaient pas, parce qu'il fallait quelqu'un pour la surveiller de près. Les plus anciennes niches ont des noms gravés. Les plus récentes n'en ont plus. Les toutes dernières, près de l'entrée, sont vides. L'Ordre a cessé de descendre il y a deux cents ans, à en juger par la poussière.",
      { if: { has: "passe:ordre" }, text: "Tu as porté ce gant. On ne t'a jamais parlé de cette salle. Tu te demandes combien de frères, là-haut, savent qu'elle existe. Tu te demandes si Brann le sait." },
      { with: "thavary", text: "Thavary passe la main sur une inscription, déchiffre le nom. « Thavar, dit-elle. Un cadet de ma maison. L'an cent douze. » Elle reste un moment devant la niche. « Ils descendaient, avant. Nous descendions. »" },
    ],
    choices: [
      { label: "Prendre un gant, pour le rapporter là-haut", hide: { has: "V:gant_gris" }, fx: { flag: "V:gant_gris", item: "VE_gant_ancien", fac: { ordre: 5 } }, back: ROUTE },
      { label: "Reprendre la route", back: ROUTE },
    ] },
  VE_leg_givre: { act: "V", title: "Le givre qui monte", place: null,
    text: [
      "Il fait de plus en plus froid à mesure que tu descends, ce qui n'a aucun sens : sous terre, on a toujours dit que la chaleur montait. Ici, c'est le froid qui monte. Le givre couvre les marches, puis la paroi, puis le plafond, des fleurs de glace grandes comme la main, et ta respiration gèle sur ton col.",
      "Et sous le givre, partout, de la vase. Prise dans la glace, figée en plein mouvement, des coulées noires qui grimpaient le long des murs et que le froid a arrêtées net, comme des mains qu'on aurait clouées. Le froid d'en bas ne vient pas de la souillure. Il se bat contre elle.",
      { if: { item: "VE_echarpe_isaure" }, text: "Tu enroules l'écharpe d'Isaure trois fois autour de ton cou. Elle sent la bergerie et le chien. Tu n'as jamais été aussi content{e} de sentir le chien." },
      { with: "gloup", text: "Gloup se raidit de froid. Il devient terne, épais, et il avance de plus en plus lentement, jusqu'à ce que tu le glisses sous ta cape, contre toi. Il fait un petit bruit de remerciement, mouillé." },
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },

  // ------------------------------------------------------------------ random events of the Descent
  VE_ev_eboulis: { act: "V", title: "La voûte qui cède", place: null,
    text: [
      "Un craquement au-dessus de toi, sec, comme une branche qui casse en hiver. Puis une pluie de gravier, puis le bruit, énorme, d'une voûte qui se décide à tomber. La galerie tout entière s'emplit de poussière. Tu ne vois plus rien.",
    ],
    choices: [
      { label: "Te jeter en avant, sous la voûte encore debout", test: { dom: "nature", diff: -10, label: "Fuir l'éboulement", help: [A_COL, A_THA] }, win: { fx: { ep: ["perso", 800] }, to: "VE_ev_eboulis_fin" }, lose: { fx: { pv: -10 }, to: "VE_ev_eboulis_fin" } },
      { label: "« Les pierres, je m'en occupe », dit Charline", who: "charline", test: { dom: "magie", diff: -10, label: "Retenir la voûte", help: [A_CHA] }, win: { fx: { conf: { charline: 5 }, ep: ["perso", 800] }, to: "VE_ev_eboulis_fin" }, lose: { fx: { pv: -6 }, to: "VE_ev_eboulis_fin" } },
    ] },
  VE_ev_eboulis_fin: { act: "V", title: "La poussière retombe", place: null,
    text: [
      { outcome: "win", text: "Quand la poussière retombe, tu es de l'autre côté, couvert{e} de gris des pieds à la tête, vivant{e}. Derrière toi, la galerie est bouchée jusqu'au plafond. Le chemin du retour, s'il y en avait un, passe désormais ailleurs." },
      { outcome: "lose", text: "Une pierre t'a touché{e} à l'épaule, une autre à la hanche. Tu te relèves en toussant, en tâtant tes côtes. Rien de cassé, peut-être. Derrière toi, la galerie est bouchée jusqu'au plafond." },
      { with: "charline", text: "Charline baisse les mains. Les dernières pierres, qui flottaient encore une seconde au-dessus de vous, tombent d'un coup, à côté. Elle a les doigts qui fument. « Ça, dit-elle, essoufflée, je ne savais pas que je savais le faire. »" },
      "Dans le silence qui suit, tu entends l'eau couler quelque part, très bas. Et tu as l'impression, absurde, que quelqu'un a soupiré de déception.",
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },
  VE_ev_flaque: { act: "V", title: "La flaque", place: null,
    text: [
      "Une flaque, au milieu de la galerie, que tu ne peux pas contourner. Large, noire, parfaitement immobile. Tu baisses les yeux en l'enjambant, et tu te vois. Plus jeune. Sept ans plus jeune. Debout dans une rue que tu connais, la grand-rue de Saint-Gilles-des-Prés, devant le temple.",
      { if: { has: "passe:aide" }, text: "Dans la flaque, tu portes un enfant gris de fièvre dans tes bras, et tu le poses sur les dalles du temple, et tu repars en chercher un autre. Il y en a déjà tant, sur les dalles. « Tu n'en as sauvé aucun, dit l'eau, avec ta propre voix. Tu le sais. Tu les as seulement portés pour mourir à l'abri. »" },
      { if: { has: "passe:fui" }, text: "Dans la flaque, tu tournes le dos à la rue, ton baluchon sur l'épaule, et tu pars par le chemin des saules. Derrière toi, quelqu'un t'appelle. Tu ne te retournes pas. « Tu ne t'es pas retourné{e}, dit l'eau, avec ta propre voix. Tu ne sais même pas qui c'était. Moi, je le sais. »" },
      { if: { has: "passe:profite" }, text: "Dans la flaque, tu comptes des pièces sur une table, et devant toi une femme signe un acte de vente, les yeux rouges, un enfant contre sa jambe. « Elles valent de l'or, maintenant, ces terres, dit l'eau, avec ta propre voix. Tu n'y es jamais retourné{e}. Moi, si. J'y suis encore. »" },
    ],
    choices: [
      { label: "Marcher dans la flaque, et passer", fx: { pv: -4 }, to: "VE_ev_flaque_fin" },
      { label: "Répondre à l'eau", test: { dom: "social", diff: -10, label: "Tenir tête à ta propre voix", help: [A_PIP, A_AUB] }, win: { fx: { ep: ["perso", 1000], flag: "V:flaque_repondue" }, to: "VE_ev_flaque_fin" }, lose: { fx: { pv: -6 }, to: "VE_ev_flaque_fin" } },
    ] },
  VE_ev_flaque_fin: { act: "V", title: "L'eau se tait", place: null,
    text: [
      { if: { has: "V:flaque_repondue" }, text: "Tu dis à l'eau que tu le sais. Que ce n'est pas une découverte. Que tu portes ce jour-là depuis sept ans, et que tu le porteras jusqu'en bas, et que ce n'est pas elle qui te l'apprendra. L'eau se trouble, et ton visage jeune se défait comme un dessin dans le sable." },
      { if: { not: { has: "V:flaque_repondue" } }, text: "Tu passes. L'eau est glacée et elle te mord les chevilles à travers le cuir des bottes. Derrière toi, quand tu te retournes, la flaque a repris sa surface lisse, et tu n'y vois plus que le plafond." },
      { with: "pip", text: "Pip vient se coller contre ta joue. « Elle sait des choses, dit-il. Mais elle ne sait pas ce que tu en fais. C'est ça qu'elle ne comprend pas. »" },
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },
  VE_ev_rats: { act: "V", title: "Les rats gris", place: null,
    text: [
      "Ils arrivent d'un boyau latéral, en flot, avec un bruit de pluie sur un toit. Des rats, gros comme des chats, le poil gris et collé de vase, les yeux blancs. Ils ne fuient pas ta lumière. Ils viennent droit sur elle.",
      { with: "pip", text: "Pip monte vers la voûte en lâchant un éclat qui fait reculer les premiers. Pas tous." },
    ],
    choices: [
      { label: "Les recevoir", fight: { title: "Les rats gris", enemies: [{ id: "VE_rat_gris", n: 4 }], terrain: "galerie",
        win: { fx: { ep: ["seance", 1200] }, to: "VE_ev_rats_fin" }, lose: { fx: { pv: -5 }, to: "VE_ev_rats_fin" },
        flee: { label: "Courir jusqu'à la galerie suivante", dom: "discretion", diff: -10, to: "VE_ev_rats_fin" } } },
      { label: "Gloup se tortille vers le boyau, l'air d'avoir une idée", who: "gloup", test: { dom: "nature", diff: 0, label: "Détourner la meute", help: [A_GLO] }, win: { fx: { conf: { gloup: 5 } }, to: "VE_ev_rats_fin" }, lose: { fx: { pv: -4 }, to: "VE_ev_rats_fin" } },
    ] },
  VE_ev_rats_fin: { act: "V", title: "Le boyau", place: null,
    text: [
      { outcome: "win", text: "Le dernier rat s'enfuit en couinant dans le boyau, et le silence revient. Les corps, sur les marches, fondent lentement en une flaque noire, comme de la neige sale au soleil. Il ne reste rien d'eux qu'une odeur." },
      { outcome: "lose", text: "Tu t'adosses à la paroi, mordu{e} aux mollets et aux mains, et les rats passent sur toi, autour de toi, puis s'en vont d'eux-mêmes, comme ils sont venus, vers le haut. Ils ne te cherchaient pas. Ils fuyaient quelque chose." },
      { outcome: "flee", text: "Tu cours sans te retourner. Le flot gris passe derrière toi, dans le boyau, et continue vers le haut sans s'arrêter. Ils ne te cherchaient pas. Ils fuyaient quelque chose." },
      { with: "gloup", text: "Gloup revient longtemps après, très content de lui, en laissant derrière lui une traînée de bave qui sent le fromage. Tu ne demandes pas comment il s'y est pris." },
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },
  VE_ev_pelerin: { act: "V", title: "Le pèlerin", place: null,
    text: [
      "Assis contre la paroi, les jambes allongées, un homme dort. Il porte la cape brune et le bourdon des pèlerins de la Main, et une besace sur les genoux. Il ne dort pas. Il est mort depuis longtemps, et le froid l'a gardé tel quel, les joues creuses, les yeux à demi ouverts sur le bas de l'escalier.",
      "Dans sa besace, une croûte de pain dure comme une pierre, un chapelet de buis, une fiole d'onguent encore bonne, et une feuille pliée en quatre où il a écrit, au crayon de charbon : *Arrivé jusqu'ici. Les autres sont remontés. Je n'ai pas le courage de remonter ni de descendre. Je reste un peu. Que celui qui me trouve aille plus loin que moi.*",
    ],
    choices: [
      { label: "Lui fermer les yeux, et prendre l'onguent", fx: { item: "onguent", ep: ["perso", 500] }, back: ROUTE },
      { label: "Le laisser à sa garde, sans rien toucher", fx: { conf: { pip: 3, aubin: 3 } }, back: ROUTE },
    ] },
  VE_ev_echo: { act: "V", title: "Une leçon", place: null,
    text: [
      "La galerie fait un coude, et dans le coude il y a un écho. Ce que tu dis te revient, puis ce que tu n'as pas dit. Une voix, que tu connais mieux que la tienne, qui te parle comme on parle à quelqu'un de plus jeune.",
      { if: { has: "maitre:hauberte" }, text: "« Les pieds, d'abord, dit la voix de Hauberte. Toujours les pieds. Une lame ne vaut rien si tu ne sais pas où tu te tiens. » Tu rectifies ta position sans y penser, comme à quinze ans, dans la cour boueuse de Sarn." },
      { if: { has: "maitre:ortie" }, text: "« Regarde l'eau avant de la boire, dit la voix d'Ortie. Regarde-la, et si elle te regarde aussi, ne bois pas. » Tu entends son rire, ce rire de vieille qui faisait peur aux enfants du marais." },
      { if: { has: "maitre:maelle" }, text: "« Une carte ne dit jamais où tu es, dit la voix de Maëlle. Elle dit où d'autres sont passés. À toi de savoir si tu veux passer au même endroit. » Tu entends le frottement de ses lunettes sur sa manche." },
      { if: { is: { maitre: "mort" } }, text: "L'écho se tait. Tu attends qu'il reprenne. Il ne reprend pas. Tu savais qu'il ne reprendrait pas." },
      { if: { is: { maitre: "sauve" } }, text: "Ta maîtresse est là-haut, dans la vallée, à guérir lentement. Ce n'est pas elle. C'est ce que tu as gardé d'elle, et c'est déjà beaucoup." },
      { if: { is: { maitre: "perdu" } }, text: "Puis la voix change, très légèrement, sur la dernière syllabe. Elle vient d'en bas. Elle vient de l'eau. Tu presses le pas." },
    ],
    choices: [{ label: "Reprendre la route", fx: { ep: ["perso", 600] }, back: ROUTE }] },
});

Object.assign(P, {
  // ================================================================== floor 1: the well (act I)
  VE_puits_arrivee: { act: "V", title: "Le puits sous la montagne", place: "VE_l_puits",
    fx: { ep: ["seance", 2500] },
    text: [
      "L'escalier débouche sur une margelle. Une margelle de pierre blanche, ronde, avec un treuil de bois et une chaîne, exactement celle du puits de Brumefeuille, la même usure du côté où l'on pose le seau, la même fente dans la troisième pierre. Sauf qu'elle est large de cent pas, et que le treuil est gros comme un moulin, et que le puits qu'elle borde descend dans le noir sans qu'on en voie le fond.",
      "Tout autour, accrochés à la paroi du puits, il y a des maisons. Des façades de Brumefeuille, collées au roc comme des nids d'hirondelles : l'auberge du Chaudron, la halle, le sanctuaire de la Main, la maison de Berthe au bord de son eau. Des façades seulement. Derrière les fenêtres, il n'y a que de la roche. Un escalier de bois descend en spirale le long de la paroi, de maison en maison, vers l'eau qui brille tout en bas, très loin, comme une pièce au fond d'un seau.",
      "Il y a de la farine sur les marches. Il y a de la farine partout. Et il y a quelqu'un, en bas, qui chante une chanson de moulin, une chanson pour faire tourner la meule, avec une voix d'homme lourde et lente.",
      { if: { has: "puits:clair" }, text: "Là-haut, dans la vallée, le vrai puits de Brumefeuille est redevenu clair. Ici, l'eau d'en bas est noire. Elle se souvient de ce qu'il était." },
      { with: "pip", text: "« C'est le village, dit Pip, tout bas. Mais à l'envers. Comme dans une flaque. »" },
    ],
    choices: [{ label: "Descendre l'escalier de bois", big: true, to: "VE_puits" }] },
  VE_puits: { act: "V", title: "L'escalier du puits", place: "VE_l_puits", hub: true, backName: "l'escalier du puits", ambiance: "eau",
    text: [
      { first: true, text: "L'escalier de bois craque sous tes pas, et la farine monte en petits nuages à chaque marche. Les fausses maisons défilent : une porte peinte en vert, une enseigne de fer forgé, un volet entrouvert sur la pierre nue. De palier en palier, l'eau d'en bas se rapproche. Elle ne fait aucun bruit. Elle attend." },
      { first: true, text: "À mi-hauteur, un large palier de planches, comme une place de village, d'où partent des passerelles. C'est là que l'escalier s'arrête, et que tout commence." },
      { again: true, text: "Le palier de planches, à mi-hauteur du puits. La farine, les façades, l'eau noire en bas qui ne bouge pas." },
      { again: true, if: { has: "V:grauk_puits" }, text: "Les trolls de Grauk se sont installés sur les passerelles comme sur des branches. Ils mangent, ils ronflent, ils jettent des cailloux dans l'eau pour voir ce qui remonte." },
      { if: { all: [{ is: { meunier: ["livre", "protege", "marche"] } }, { not: { has: "V:bart_fait" } }] }, text: "En bas, la chanson de moulin continue. L'homme qui chante ne se fatigue pas." },
    ],
    choices: [
      { label: "La margelle et ses noms", hide: { seen: "VE_puits_margelle" }, to: "VE_puits_margelle" },
      { label: "Descendre vers l'homme qui chante", hide: { any: [{ has: "V:bart_fait" }, { not: { is: { meunier: ["livre", "protege", "marche"] } } }] }, to: "VE_puits_bart" },
      { label: "La petite fille au bord de l'eau", hide: { has: "V:margot_fait" }, to: "VE_puits_margot" },
      { label: "La maison de Berthe, et la voix à la fenêtre", hide: { seen: "VE_puits_berthe" }, to: "VE_puits_berthe" },
      { label: "La silhouette assise dans l'eau, en bas", hide: { any: [{ not: { is: { maitre: "perdu" } } }, { has: "V:maitre_fait" }] }, to: "VE_puits_maitre" },
      { label: "Le grondement dans la paroi", hide: { any: [{ not: { has: "grauk:allie" } }, { seen: "VE_puits_grauk" }] }, to: "VE_puits_grauk" },
      { label: "Les noyés qui attendent sur les marches", hide: { has: "V:noyes_fait" }, to: "VE_puits_noyes" },
      { label: "Descendre jusqu'à l'eau, au fond du puits", big: true, to: "VE_puits_fond" },
    ] },
  VE_puits_margelle: { act: "V", title: "Les noms de la margelle", place: "VE_l_puits",
    fx: { flag: "V:noms_lus", ep: ["perso", 800] },
    text: [
      "Sur la margelle, tout autour, des noms sont gravés. Des centaines, serrés, à la pointe d'un couteau ou d'un clou, comme on grave des noms sur les bancs d'église. Certains sont si vieux que la pierre les a presque effacés. D'autres sont frais, les arêtes encore blanches.",
      "Tu lis. *Margot, neuf ans, au bief.* *Jehan Loriot, au gué de Sorbe.* *La mère Gertrude, au lavoir.* *Les trois petits Fournier, à la mare.* Ce sont les noyés. Tous les noyés de la Sorbe, depuis quatre cents ans, ceux que l'eau a pris, et dont on a pleuré le nom au bord de l'eau. L'eau les a gardés. Elle les a écrits ici, comme on tient un registre.",
      { if: { has: "passe:aide" }, text: "Plus loin, sur une pierre à part, une liste plus courte et plus récente. Saint-Gilles-des-Prés. Tu connais ces noms. Tu as porté certains d'entre eux jusqu'au temple, dans tes bras. Ils sont morts quand même." },
      { if: { has: "passe:fui" }, text: "Plus loin, sur une pierre à part, une liste plus courte et plus récente. Saint-Gilles-des-Prés. Tu connais ces noms. Tu étais déjà sur la route quand ils sont morts. Tu lis la liste jusqu'au bout. Tu te forces." },
      { if: { has: "passe:profite" }, text: "Plus loin, sur une pierre à part, une liste plus courte et plus récente. Saint-Gilles-des-Prés. Tu connais ces noms. Tu as signé des actes de vente avec certains d'entre eux, la semaine où ils sont partis. Ils ne sont pas allés loin." },
      { if: { is: { ninon: "noyee" } }, text: "Et tout en bas, si frais que la poussière de pierre y est encore : *Ninon, au ponton de Morteau.*" },
    ],
    choices: [{ back: "VE_puits" }] },

  // ------------------------------------------------------------------ Barthélemy
  VE_puits_bart: { act: "V", title: "Le meunier", place: "VE_l_puits", ambiance: "eau",
    fx: { meet: "barthelemy" },
    text: [
      "Il est assis sur la dernière marche de bois, juste au-dessus de l'eau, les pieds nus dans la farine, et il chante. Barthélemy, le meunier de Brumefeuille. Plus maigre, la barbe longue, la chemise en lambeaux, mais lui, avec ses grosses mains blanches posées sur les genoux.",
      { if: { is: { meunier: "protege" } }, text: "Il se retourne en t'entendant, et son visage s'éclaire d'un soulagement si brutal que tu as presque honte d'en être l'objet. « Vous voilà, dit-il. Je savais que vous passeriez par ici. Je l'ai entendue vous appeler, de là-haut, depuis le bief. Alors je suis descendu avant vous. » Il se lève, en s'appuyant sur la rampe. « Je l'entends toujours, vous savez. Mais maintenant, je sais ce qu'elle dit. »" },
      { if: { is: { meunier: "livre" } }, text: "Il se retourne en t'entendant, et il ne se lève pas. « Tiens, dit-il. C'est vous qui m'avez livré. » Il n'y a pas de colère dans sa voix, pas encore. Seulement une fatigue immense, qui a fait tout le chemin du bannissement à pied. « Ils m'ont chassé de la vallée. J'ai marché vers le sud, comme ils voulaient. Et chaque flaque de la route me disait de revenir. Alors je suis revenu. Par en dessous. » Il te regarde. « Elle m'a dit que vous viendriez. Elle ne ment jamais, vous le savez, ça ? »" },
      { if: { is: { meunier: "marche" } }, text: "Il se retourne en t'entendant, et il rit, de bon cœur, en écartant les bras. « Tiens donc ! Nous sommes en affaires, vous et moi ! » Il se lève, vient vers toi, et ses yeux sont clairs et gais, et au creux de son cou il y a une tache noire, grande comme une main, qui remue quand il parle. « On a dit oui tous les deux, pas vrai ? Au bord du bief. Elle s'en souvient. Elle se souvient de tout ce qu'on lui donne. »" },
      { if: { has: "ruban=pere" }, text: "À son poignet, noué maladroitement, un ruban de soie rouge, délavé. Il n'a pas quitté son poignet depuis le jour où tu le lui as rendu." },
      { with: "coliane", if: { is: { meunier: "marche" } }, text: "Coliane se place entre lui et toi sans le regarder, sans te regarder, la main sur un couteau. Elle se tait. Elle n'a jamais rien dit de cette nuit-là au bord du bief. Elle ne l'a pas oubliée non plus." },
    ],
    choices: [
      { label: "« Que faites-vous ici, Barthélemy ? »", hide: { not: { is: { meunier: "protege" } } }, to: "VE_puits_bart_ami" },
      { label: "Lui parler de Margot, et de ce que tu as fait", hide: { not: { is: { meunier: "livre" } } }, test: { dom: "social", diff: -20, label: "Atteindre un homme banni", help: [{ if: { has: "ruban=pere" }, v: 15 }, { if: { has: "IB:ruban_su" }, v: 5 }, A_AUB, A_PIP] }, win: { fx: { ep: ["seance", 2000] }, to: "VE_puits_bart_parole" }, lose: { to: "VE_puits_bart_combat" } },
      { label: "Lui demander ce qu'il attend de toi", hide: { not: { is: { meunier: "marche" } } }, to: "VE_puits_bart_chante" },
      { label: "Dégainer avant qu'il ne se lève", hide: { not: { is: { meunier: ["livre", "marche"] } } }, to: "VE_puits_bart_combat" },
      { label: "Le laisser à sa chanson", hide: { is: { meunier: "protege" } }, fx: { flag: "V:bart_fait", set: { barthelemy_v: "laisse" } }, back: "VE_puits" },
    ] },
  VE_puits_bart_ami: { act: "V", title: "Ce que dit l'eau", place: "VE_l_puits",
    fx: { flag: ["V:bart_fait", "V:bart_aide"], set: { barthelemy_v: "ami" }, conf: { pip: 5 }, ep: ["seance", 2000], regard: { barthelemy: "allie" } },
    text: [
      "« Je suis venu lui dire non, dit-il. À elle. Pas à Margot : à elle. » Il montre l'eau d'en bas, du menton. « Elle me parle avec la voix de ma fille depuis le printemps d'avant. Au début, je croyais. Après, je savais, et je faisais semblant de croire, parce que c'était mieux que rien. Et puis vous, vous m'avez laissé au moulin, en silence à personne, avec tout ça sur le dos. J'ai eu le temps de réfléchir, à moudre. »",
      "Il s'essuie les mains sur sa chemise, longtemps, le geste qu'il a toujours. « Elle ne sait que ce que je lui ai dit, ma Margot. Tout ce qu'elle me raconte, c'est moi qui le lui ai appris, au bord du bief, en pleurant. Alors je suis descendu pour qu'elle me le rende. » Il a presque un sourire. « Et il y a une vanne, en bas. Comme au moulin. Je l'ai sentie dans mes pieds en descendant. Je sais comment on ouvre une vanne. »",
      { if: { has: "ruban=pere" }, text: "Il touche le ruban à son poignet. « Elle porte un ruban, en bas. Comme celui-là. Elle croit que je ne vois pas la différence. »" },
      { with: "pip", text: "Pip vole jusqu'au meunier et se pose sur sa grosse main. Barthélemy le regarde, très étonné, puis il referme doucement les doigts autour de lui, sans le serrer, comme on tient un oisillon. Ils restent comme ça un moment." },
    ],
    choices: [{ back: "VE_puits" }] },
  VE_puits_bart_parole: { act: "V", title: "Le meunier pleure", place: "VE_l_puits",
    fx: { flag: ["V:bart_fait", "V:bart_aide"], set: { barthelemy_v: "reconcilie" }, conf: { aubin: 5, pip: 5 }, regard: { barthelemy: "redevable" } },
    text: [
      { if: { is: { meunier: "livre" } }, text: "Tu ne lui dis pas que tu as eu raison. Tu lui dis que tu l'as livré parce qu'il fallait que l'eau s'arrête, et qu'il le savait, et que tu le referais. Puis tu lui dis que tu as vu la chambre de Margot. Les bateaux de bois sur l'étagère. Le clou vide à côté de la porte. Il t'écoute sans bouger." },
      { if: { is: { meunier: "marche" } }, text: "Tu ne lui parles pas de la Voix. Tu lui parles de Margot. De ce que Berthe t'a raconté, la nuit de février où elle est née, les bateaux qu'il lui taillait, le ruban de la foire de Ferrance. Tu lui demandes si la Margot d'en bas se souvient des bateaux. Il ouvre la bouche pour répondre, et il ne trouve pas la réponse. La tache de son cou s'arrête de remuer." },
      "Puis ses épaules se mettent à trembler, et ce n'est pas de froid. Il pleure comme pleurent les hommes qui ne l'ont pas fait depuis longtemps, sans bruit, avec tout le corps, les mains ouvertes sur les genoux. Tu t'assieds à côté de lui sur la marche. Tu attends.",
      "« Il y a une vanne, en bas, dit-il enfin, d'une voix enrouée. Comme au moulin. Je la sens depuis que je suis là. Je sais comment on ouvre une vanne. Je vais vous l'ouvrir. Et après, je remonterai. Je ne sais pas où j'irai. Mais je remonterai. »",
      { with: "aubin", text: "Frère Aubin pose la main sur la tête du meunier, sans un mot de prière. Barthélemy ne la repousse pas." },
    ],
    choices: [{ back: "VE_puits" }] },
  VE_puits_bart_chante: { act: "V", title: "L'associé", place: "VE_l_puits",
    text: [
      "« Ce que j'attends ? » Barthélemy rit encore. « Rien, voyons. Rien du tout. C'est elle qui attend. Elle a été très patiente avec vous, vous savez. Plus qu'avec moi. » Il s'approche, et il sent la farine et la vase, et ses yeux sont si clairs qu'on y voit le fond. « En bas, il y a une vanne. Elle ferme le chemin. Je peux l'ouvrir. Je sais comment on ouvre une vanne. Il suffit que vous redisiez oui. Une toute petite fois. Comme au bief. »",
      "Il tend la main. Sa paume est noire jusqu'au poignet.",
      { if: { mark: { min: 2 } }, text: "Ta propre paume répond. Elle se réchauffe, elle palpite, elle a envie de cette main tendue comme on a envie de boire après une longue marche. Ce serait si simple." },
      { with: "pip", text: "Pip ne dit rien, cette fois. Il se cache dans tes cheveux, et tu sens sa lumière trembler contre ta nuque." },
    ],
    choices: [
      { label: "Serrer sa main", tag: "Marque +1", stain: true, fx: { mark: 1, flag: ["V:bart_fait", "V:bart_aide"], set: { barthelemy_v: "marche" }, conf: { pip: -10, coliane: -10, aubin: -10 }, fear: { pip: 10 } }, back: "VE_puits" },
      { label: "« Margot n'a jamais eu de chien, Barthélemy. »", hide: { not: { clue: "v_margot" } }, to: "VE_puits_bart_parole" },
      { label: "Lui parler de sa fille, la vraie", test: { dom: "social", diff: -20, label: "Ramener le meunier à lui", help: [{ if: { has: "IB:ruban_su" }, v: 10 }, A_AUB, A_PIP] }, win: { fx: { ep: ["seance", 2000] }, to: "VE_puits_bart_parole" }, lose: { to: "VE_puits_bart_combat" } },
      { label: "Refuser, et lever ton arme", to: "VE_puits_bart_combat" },
    ] },
  VE_puits_bart_combat: { act: "V", title: "La meule", place: "VE_l_puits", ambiance: "eau",
    combat: { title: "Le meunier de Brumefeuille", enemies: ["VE_meunier"], terrain: "bati", spare: true,
      win: { fx: { ep: ["seance", 3000] }, to: "VE_puits_bart_vaincu" }, lose: { to: "VE_puits_bart_vaincu" },
      calm: { fx: { ep: ["seance", 3000] }, to: "VE_puits_bart_vaincu" },
      flee: { label: "Remonter l'escalier", dom: "discretion", diff: -10, to: "VE_puits_bart_vaincu" } },
    text: [
      "Barthélemy se lève. Il est plus grand que dans ton souvenir, ou c'est l'eau qui le grandit : elle monte le long de ses jambes, lui fait des bottes noires, des gants noirs, une ceinture de vase. Il ramasse sur la marche une pelle à grain, une pelle de bois, et il la tient comme on tient une hache.",
      "« Je ne veux pas vous faire de mal, dit-il. Elle non plus. Elle veut juste que vous vous arrêtiez. »",
    ] },
  VE_puits_bart_vaincu: { act: "V", title: "Le meunier à genoux", place: "VE_l_puits",
    fx: { flag: "V:bart_fait" },
    text: [
      { outcome: "win", text: "La pelle se brise sur la rampe. Barthélemy tombe à genoux dans la farine, et l'eau qui le gantait se retire de lui d'un coup, lâche, comme une marée qui abandonne une épave. Il reste là, essoufflé, vieux, les mains vides. Il ne te regarde pas." },
      { outcome: "calm", text: "Ta voix, ta chanson ou ton sort : quelque chose l'atteint. Le bras de Barthélemy retombe. La pelle glisse de ses doigts. Il s'assied sur la marche, lourdement, et il fixe ses mains noires comme s'il les voyait pour la première fois." },
      { outcome: "lose", text: "La pelle te cueille au flanc et t'envoie contre la rampe. Le temps de te relever, il est déjà en bas, dans l'eau jusqu'à la taille. Il ne te poursuit pas. Il s'arrête, se retourne. « Pardon », dit-il, et l'eau noire le recouvre. Tu ne le revois plus." },
      { outcome: "flee", text: "Tu remontes trois paliers en courant. Il ne te suit pas. Quand tu regardes en bas, il est assis de nouveau sur sa marche, et il chante. Plus bas qu'avant." },
      { if: { has: "ruban=pere" }, text: "Le ruban rouge, à son poignet, s'est dénoué dans la lutte. Il flotte sur l'eau noire, un instant, puis il s'enfonce." },
    ],
    choices: [
      { label: "L'aider à se relever, et lui montrer l'escalier qui remonte", fx: { set: { barthelemy_v: "epargne" }, conf: { pip: 5, aubin: 5 } }, back: "VE_puits" },
      { label: "Le laisser là où il est", fx: { set: { barthelemy_v: "vaincu" } }, back: "VE_puits" },
    ] },

  // ------------------------------------------------------------------ Margot, Berthe
  VE_puits_margot: { act: "V", title: "La petite fille", place: "VE_l_puits", ambiance: "eau",
    fx: { meet: "margot" },
    text: [
      "Tout en bas de l'escalier, sur une marche qui affleure l'eau, une petite fille est assise, les jambes dans le noir jusqu'aux genoux. Neuf ans. Une robe de toile bleue trempée, des cheveux bruns collés aux joues. Elle joue avec un bateau de bois, une coquille de noix avec une voile de papier, qu'elle pousse du doigt sur l'eau immobile.",
      { if: { has: "ruban=eau" }, text: "Dans ses cheveux, noué en boucle, un ruban de soie rouge. Le ruban que tu as rendu à la Sorbe. L'eau l'a gardé. Elle l'a rapporté ici." },
      { if: { not: { has: "ruban=eau" } }, text: "Elle n'a pas de ruban. Elle passe la main dans ses cheveux, de temps en temps, comme pour vérifier qu'il n'y est toujours pas." },
      "« Tu es venu{e}, dit-elle sans lever les yeux de son bateau. Papa dit que tu es quelqu'un de gentil. Tu veux jouer ? Mon chien est parti chercher le bateau qui a coulé. Il revient toujours. Il s'appelle Bouton. »",
      { with: "pip", text: "Pip s'est arrêté net au-dessus de l'eau. Il regarde la petite fille, et sa lumière devient blanche, froide, comme celle d'une lune. « Ce n'est pas elle, dit-il. Il n'y a personne dedans. »" },
    ],
    choices: [
      { label: "« Margot n'a jamais eu de chien. »", hide: { not: { clue: "v_margot" } }, to: "VE_puits_margot_mensonge" },
      { label: "Appeler Barthélemy pour qu'il lui parle", hide: { not: { has: "V:bart_aide" } }, to: "VE_puits_margot_adieu" },
      { label: "T'asseoir à côté d'elle, et l'écouter", to: "VE_puits_margot_parle" },
      { label: "Passer sans lui répondre", fx: { flag: "V:margot_fait" }, back: "VE_puits" },
    ] },
  VE_puits_margot_mensonge: { act: "V", title: "Bouton", place: "VE_l_puits", ambiance: "eau",
    fx: { flag: ["V:margot_fait", "V:margot_demasquee"], ep: ["seance", 3500] },
    text: [
      "Tu le dis doucement, comme on rectifie l'erreur d'un enfant. Margot n'a jamais eu de chien. Barthélemy le lui a promis, pour ses dix ans. Elle n'a pas eu dix ans.",
      "La petite fille s'arrête de pousser son bateau. Elle lève la tête, et son visage reste un visage de petite fille, mais ses yeux ne bougent plus du tout. « Il me l'a dit, pourtant, dit-elle. Il m'a parlé du chien. Au bord du bief. Il pleurait, il m'a parlé du chien. » Sa voix descend, se fait plus grave, plus lente, une voix de femme. « Il a dit : tu aurais eu un chien. J'ai pris ce qu'il m'a donné. Je prends toujours ce qu'on me donne. »",
      "Puis il n'y a plus de petite fille. Il y a une forme de vase qui s'affaisse sur la marche, une robe bleue vide, un bateau de bois qui dérive. Et sur l'eau, pendant une seconde, le visage d'une femme, très belle, avec des cheveux d'algue, qui te regarde avec une sorte de respect. « Tu apprends, {hero}, dit-elle. C'est bien. J'aime qu'on apprenne. » L'eau se referme.",
      { if: { has: "ruban=eau" }, text: "Le ruban rouge flotte un moment là où était la petite fille. Tu le repêches. Il est sec, comme dans la niche sous le moulin. Tu le gardes." },
    ],
    choices: [{ back: "VE_puits" }] },
  VE_puits_margot_adieu: { act: "V", title: "Le père et l'eau", place: "VE_l_puits", ambiance: "eau",
    fx: { flag: ["V:margot_fait", "V:margot_adieu"], ep: ["seance", 3000], conf: { aubin: 5, coliane: 5 } },
    text: [
      "Barthélemy descend les dernières marches, lentement, en se tenant à la rampe, et il s'accroupit devant la petite fille, ses grosses mains sur les genoux. Elle lève les yeux vers lui. « Papa », dit-elle, avec la voix de Margot, exactement, la voix qu'il a entendue dans le bief tous les soirs depuis le printemps d'avant.",
      "« Non, dit Barthélemy. Non, ma belle. Tu n'es pas elle. » Il a les larmes qui coulent dans sa barbe et la voix ferme. « Ma Margot, elle avait peur de l'eau. Elle ne s'asseyait jamais les pieds dedans. Elle est tombée parce qu'elle se penchait pour voir les poissons, et elle n'avait jamais vu de poisson de sa vie, et je lui avais promis de lui en montrer un. » Il essuie son visage. « Tu ne savais pas ça. Je ne te l'avais jamais dit. Je le garde pour moi. »",
      "La petite fille le regarde longtemps. Puis, en silence, elle se défait, comme du sucre dans l'eau chaude, et il ne reste sur la marche qu'une robe bleue et un bateau de bois. Barthélemy ramasse le bateau. Il le met dans sa poche.",
      { if: { has: "ruban=pere" }, text: "Il dénoue le ruban de son poignet, celui que tu lui as rendu, et il le jette à l'eau, enfin. « Celui-là non plus, ce n'est pas elle, dit-il. C'est un ruban. »" },
    ],
    choices: [{ back: "VE_puits" }] },
  VE_puits_margot_parle: { act: "V", title: "Ce que raconte l'eau", place: "VE_l_puits", ambiance: "eau",
    fx: { flag: "V:margot_fait" },
    text: [
      "Tu t'assieds sur la marche, les pieds au sec. Elle te parle de son bateau, de son père, du moulin, du pain chaud le dimanche. Tout est juste. Tout est vrai. C'est la voix d'une enfant qui raconte sa vie, et tu as la gorge serrée, et tu sais en même temps que chaque mot a été pleuré par quelqu'un d'autre, au bord d'un bief, et qu'elle les a ramassés un à un comme on ramasse des pièces tombées.",
      "« Tu sais ce qu'il y a, en bas ? demande-t-elle. Un monsieur. Il a froid. Il a très froid depuis très longtemps. Moi, je veux qu'il ait chaud. Tout le monde a le droit d'avoir chaud. » Elle pousse son bateau. « Il faut juste ouvrir la porte. Tu as les clés, toi. Papa me l'a dit. »",
      { if: { relics: { min: 1 } }, text: "Elle regarde ta besace en le disant. Elle sait exactement ce qu'il y a dedans." },
      "Quand tu te lèves, elle ne te retient pas. Elle continue de jouer. Elle a tout son temps.",
    ],
    choices: [{ back: "VE_puits" }] },
  VE_puits_berthe: { act: "V", title: "La fenêtre de Berthe", place: "VE_l_puits",
    text: [
      "La fausse maison de Berthe est accrochée au roc juste au-dessus de l'eau, comme la vraie l'est au-dessus de la sienne, avec son toit de chaume affaissé et ses deux chèvres de bois peint devant la porte. La fenêtre est éclairée. Derrière la vitre, une vieille femme est assise dans un fauteuil, un tricot sur les genoux.",
      { if: { is: { berthe: "pendue" } }, text: "« Te voilà, toi, dit la voix de Berthe à travers la vitre. Tu étais sur la place, ce matin-là. Tu as vu Charron attacher la corde. Tu m'as regardée monter sur le tonneau. » Les aiguilles s'arrêtent. « J'avais vu le meunier au puits, tu sais. Trois nuits de suite. J'aurais pu te le dire, si tu étais venu{e} me le demander avant. » La vieille tourne la tête vers toi. Elle a autour du cou une marque rouge, large comme une corde." },
      { if: { is: { berthe: ["sauvee", "cachee"] } }, text: "« Te voilà, toi, dit la voix de Berthe à travers la vitre. Viens donc t'asseoir. Je t'ai gardé de la soupe. » C'est sa voix. C'est sa façon de dire *toi*, sèche et tendre. Les aiguilles cliquettent. « Tu ne m'as jamais aimée, au fond. Personne ne m'aime, à Brumefeuille. Tu m'as sauvée pour avoir raison, pas pour moi. »" },
      { if: { not: { is: { berthe: ["sauvee", "cachee", "pendue"] } } }, text: "« Te voilà, toi, dit la voix de Berthe à travers la vitre. Tu ne m'as jamais rendu visite, là-haut. Personne ne me rend visite. » Les aiguilles cliquettent. Tu ne sais pas quoi répondre à une vieille que tu n'as presque pas connue." },
    ],
    choices: [
      { label: "« Berthe est vivante. Tu ne peux pas avoir sa voix. »", hide: { not: { is: { berthe: ["sauvee", "cachee"] } } }, fx: { flag: "V:berthe_vivante", ep: ["seance", 2000] }, to: "VE_puits_berthe_fin" },
      { label: "Baisser les yeux, et l'écouter jusqu'au bout", hide: { not: { is: { berthe: "pendue" } } }, fx: { flag: "V:berthe_ecoutee", conf: { aubin: 5 } }, to: "VE_puits_berthe_fin" },
      { label: "Tourner le dos à la fenêtre", back: "VE_puits" },
    ] },
  VE_puits_berthe_fin: { act: "V", title: "La vitre", place: "VE_l_puits",
    text: [
      { if: { has: "V:berthe_vivante" }, text: "Tu le dis à voix haute, devant la vitre : Berthe est vivante. Elle est dans sa maison, au bord de son eau, avec ses chèvres, et elle tricote, et elle t'a fait dire par quelqu'un qu'elle ne remerciait jamais personne et qu'elle n'allait pas commencer pour toi. La Voix ne prend que le nom des morts qu'on pleure. Personne ne pleure Berthe. Elle n'en a pas besoin." },
      { if: { has: "V:berthe_vivante" }, text: "La vieille derrière la vitre se fige. Son visage coule, lentement, comme une chandelle qu'on approche du feu. Les aiguilles tombent. La lumière de la fenêtre s'éteint. Il ne reste qu'une façade de bois peint sur la roche nue, et derrière, rien." },
      { if: { has: "V:berthe_ecoutee" }, text: "Tu l'écoutes. Elle parle longtemps, de la place, de la corde, des enfants qui lui jetaient des pierres, de ses chèvres que personne n'a traites le lendemain. Tu ne te défends pas. À la fin, elle se tait, et elle te regarde, et tu ne sais pas si c'est Berthe ou la Voix, et tu comprends que ça n'a plus d'importance : ce qu'elle a dit est vrai." },
      { if: { has: "V:berthe_ecoutee" }, text: "La lumière de la fenêtre baisse, doucement, comme une lampe qu'on éteint pour dormir. Tu restes un moment devant la vitre noire. Puis tu descends." },
    ],
    choices: [{ back: "VE_puits" }] },

  // ------------------------------------------------------------------ the master, if the water took her at the ford
  VE_puits_maitre: { act: "V", title: "Dans l'eau jusqu'à la taille", place: "VE_l_puits", ambiance: "eau",
    text: [
      "Loin du palier, là où l'escalier s'enfonce dans l'eau, une silhouette est debout dans le noir, immergée jusqu'à la taille. Elle reste immobile. Elle regarde la paroi, comme on regarde par une fenêtre. Tu la reconnais au port de tête avant de reconnaître son visage. Tu la reconnaîtrais n'importe où.",
      { if: { has: "maitre:hauberte" }, text: "Hauberte de Sarn. Ses cheveux gris coupés court, sa balafre, ses épaules de chevalière. Elle n'a plus d'épée. L'eau lui en a fait une, de vase, qui pend à sa main droite et goutte sans fin." },
      { if: { has: "maitre:ortie" }, text: "Ortie. Son foulard, ses mains d'herboriste, couvertes de bagues de corne. Autour d'elle, l'eau noire fleurit : des nénuphars gris, qui s'ouvrent et se referment au rythme de sa respiration." },
      { if: { has: "maitre:maelle" }, text: "Maëlle Vautrin. Ses lunettes, la branche cassée tenue par un fil. Elle tient à la main un carnet trempé, et elle y écrit, avec le doigt, des lignes qui s'effacent à mesure." },
      "Elle tourne la tête vers toi. Un œil noir, entièrement, comme une goutte d'encre. L'autre à elle, gris, fatigué, qui te reconnaît. « Tu ne devrais pas être ici, dit-elle de sa voix à elle. Je t'avais dit de partir loin de l'eau. » Puis l'autre voix, celle de dessous, qui parle par la même bouche : « Mais tu es venu{e}. On vient toujours. »",
      { with: "coliane", text: "Coliane a sorti ses deux couteaux et ne bouge plus. Elle attend que tu décides. Elle n'a pas l'air de savoir ce qu'elle ferait à ta place." },
    ],
    choices: [
      { label: "La ramener à elle", big: true, if: SAUVER_MAITRE, why: "Il faudrait de l'eau claire, un prêtre loyal à tes côtés, ou savoir assez de la Voix pour lui arracher ce qu'elle tient.", to: "VE_puits_maitre_ramenee" },
      { label: "Te battre contre ce qu'elle est devenue", fight: { title: "Ta maîtresse dans l'eau", enemies: ["VE_maitre_eau"], terrain: "bati", spare: true,
        win: { fx: { ep: ["seance", 4000] }, to: "VE_puits_maitre_vaincue" }, calm: { fx: { ep: ["seance", 4000] }, to: "VE_puits_maitre_vaincue" },
        lose: { to: "VE_puits_maitre_adieu" }, flee: { label: "Remonter sur le palier", dom: "discretion", diff: -10, to: "VE_puits_maitre_adieu" } } },
      { label: "La laisser à l'eau, et lui dire adieu", to: "VE_puits_maitre_adieu" },
    ] },
  VE_puits_maitre_ramenee: { act: "V", title: "Hors de l'eau", place: "VE_l_puits",
    fx: { flag: ["V:maitre_fait", "V:maitre_ramenee"], set: { maitre: "sauve" }, ep: ["histoire", 5000], conf: { pip: 10, aubin: 10, coliane: 5 } },
    text: [
      "Tu descends dans l'eau. Elle est froide comme le métal en hiver, et elle s'enroule autour de tes jambes, curieuse, presque tendre. Tu marches jusqu'à elle. Elle ne recule pas. Elle te regarde venir avec son œil noir et son œil gris.",
      { if: { item: "eau_claire" }, text: "Tu débouches la fiole d'eau claire et tu la lui verses sur le visage, sur l'œil noir, sur la bouche, comme on baptise. Elle hurle. L'eau d'en bas hurle avec elle, dans tout le puits, et les fausses fenêtres tremblent." },
      { if: { all: [{ not: { item: "eau_claire" } }, { present: "aubin" }, { loyal: "aubin" }] }, text: "Frère Aubin est entré dans l'eau derrière toi. Il pose ses deux mains sur la tête de ta maîtresse, et il dit l'office des noyés, celui qu'il n'a pas dit pour ses frères la nuit où ils sont morts, en entier, sans s'arrêter, d'une voix qui ne tremble pas. L'eau d'en bas gronde. Il continue." },
      { if: { all: [{ not: { item: "eau_claire" } }, { not: { all: [{ present: "aubin" }, { loyal: "aubin" }] } }] }, text: "Tu lui parles de la Voix. Pas à elle : à la Voix, à travers elle. Tu lui dis ce qu'elle est, d'où elle vient, de quoi elle est faite, ce que la Vieille Sauge et les noyés et la pierre t'en ont appris. Tu lui dis qu'elle ne sait que ce qu'on lui donne. L'œil noir se plisse. Pour la première fois, la Voix a l'air de ne pas aimer ce qu'elle entend." },
      "Et l'eau la lâche. D'un coup, comme une main qu'on ouvre. Ta maîtresse tombe en avant, et tu la rattrapes, et elle ne pèse presque rien. Ses deux yeux sont gris. Elle tousse de l'eau noire, longtemps, sur ton épaule. Puis elle dit ton nom, avec sa voix, rien qu'avec sa voix.",
      { if: { item: "eau_claire" }, text: "La fiole est vide. Tu la jettes dans l'eau noire. Tu n'as pas un regret." },
      "Tu la remontes sur le palier. Elle ne peut pas descendre plus bas avec toi, elle le sait, tu le sais. « Je remonterai, dit-elle. Doucement. Une marche à la fois. Va. Va plus loin que moi. »",
    ],
    choices: [{ back: "VE_puits" }] },
  VE_puits_maitre_vaincue: { act: "V", title: "À genoux dans le noir", place: "VE_l_puits",
    text: [
      "Elle tombe à genoux dans l'eau, et l'eau monte jusqu'à son menton. L'arme de vase s'est défaite entre ses doigts. Elle te regarde, l'œil noir et l'œil gris, et elle attend, et tu ne sais pas laquelle des deux attend.",
      "« Fais-le, dit sa voix à elle. Pendant que c'est moi qui te le demande. » Puis l'autre voix, très douce : « Ou laisse-moi la garder. Je la soignerai. Je la garderai au chaud. »",
    ],
    choices: [
      { label: "Lui donner la paix", fx: { flag: "V:maitre_fait", set: { maitre: "mort" }, conf: { thavary: 5, pip: -5 } }, to: "VE_puits_maitre_mort" },
      { label: "Baisser ton arme, et la laisser partir", to: "VE_puits_maitre_adieu" },
    ] },
  VE_puits_maitre_mort: { act: "V", title: "La paix", place: "VE_l_puits",
    fx: { ep: ["histoire", 4000] },
    text: [
      "Tu le fais vite, et proprement, comme elle te l'a appris, à toi qui ne voulais pas apprendre ça. Elle ne se défend pas. Au dernier moment, l'œil noir se ferme, et il ne reste que l'œil gris, qui te regarde, et qui est content.",
      "L'eau la laisse. Elle ne la garde pas, comme elle garde les autres. Elle la rend : le corps remonte à la surface, léger, et flotte jusqu'à toi, et tu le tires sur la marche. Elle a l'air plus petite. Elle a l'air de dormir après une longue route.",
      { if: { has: "maitre:hauberte" }, text: "Tu lui croises les mains sur la poitrine. Tu n'as pas d'épée à y mettre. Tu y mets la tienne, un moment, puis tu la reprends : elle t'aurait dit que tu en aurais besoin plus bas." },
      { if: { has: "maitre:ortie" }, text: "Tu lui ôtes ses bagues de corne, une à une, et tu les glisses dans ta poche. Elle disait toujours qu'on n'enterre pas les choses qui servent." },
      { if: { has: "maitre:maelle" }, text: "Tu lui remets ses lunettes, la branche tenue par le fil. Tu prends le carnet trempé. Les pages sont blanches. Tu le gardes quand même." },
      { with: "thavary", text: "Thavary se tient derrière toi, l'épée basse. « Tu lui as rendu ce qu'elle t'avait demandé, dit-elle. C'est une dette payée. Il n'y en a pas beaucoup, des comme ça. »" },
    ],
    choices: [{ back: "VE_puits" }] },
  VE_puits_maitre_adieu: { act: "V", title: "L'eau la garde", place: "VE_l_puits",
    fx: { flag: ["V:maitre_fait", "V:maitre_laissee"] },
    text: [
      { outcome: "lose", text: "Tu es à terre, sur la dernière marche, à demi dans l'eau. Elle se tient au-dessus de toi, et elle pourrait, une seconde fois. Une seconde fois, le bras s'arrête." },
      { outcome: "flee", text: "Tu remontes sur le palier en glissant sur les planches mouillées. Elle ne te suit pas. Quand tu te retournes, elle est toujours là, dans l'eau, à te regarder." },
      "« Va-t'en, dit-elle de sa voix à elle. Ne reviens pas me chercher. Je suis bien, là. Je n'ai plus mal nulle part. C'est ça le pire, tu comprends ? Je n'ai plus mal nulle part. »",
      "Elle recule dans l'eau noire, un pas, deux pas, comme sur la rive de l'Isarde, et l'eau lui monte aux épaules, au menton, aux yeux. Tu la regardes disparaître une deuxième fois. Ce n'est pas plus facile.",
      { with: "pip", text: "Pip se pose sur ta main, là où elle serrait la tienne autrefois pour t'apprendre à tenir quelque chose. Il se tait. Il reste là jusqu'à ce que tu te relèves." },
    ],
    choices: [{ back: "VE_puits" }] },

  // ------------------------------------------------------------------ Grauk and his trolls
  VE_puits_grauk: { act: "V", title: "Le roi des trolls", place: "VE_l_puits",
    fx: { meet: "grauk", flag: "V:grauk_puits", ep: ["seance", 2500] },
    text: [
      "La paroi du puits gronde. Une fausse façade, celle de l'auberge du Chaudron, se fend du haut en bas, et s'effondre dans l'eau avec un bruit de grange qui tombe. Derrière, un trou dans le roc, grossièrement taillé, et dans le trou, une tête énorme, grise, verruqueuse, coiffée d'une couronne de fer tordue. « Ha, dit Grauk, roi des trolls. C'est bien ici. J'avais dit à Bourle que c'était ici. Bourle disait que non. »",
      "Il s'extrait du tunnel en grognant, suivi de six, huit, dix trolls, couverts de poussière de roche, des pics et des pelles sur l'épaule. Ils regardent le puits, les fausses maisons, l'eau noire, avec la méfiance tranquille de gens qui n'aiment pas l'eau et qui ne s'en cachent pas.",
      "« Ça chante sous mon château depuis que mon grand-père était petit, dit Grauk. Depuis que toi, tu es passé{e}, ça chante moins. Alors on a creusé, pour voir. On a suivi la fente de la pierre, vers le bas. Trois mois. » Il crache dans l'eau. « On s'est dit : là où ça chante, il faut des trolls. Les trolls, ça n'écoute pas les chansons. On est sourds comme des pots, la moitié. »",
      { if: { seen: "IIIG_merle_trolls" }, text: "Il te donne une claque dans le dos qui te coupe le souffle. « Le gué, c'était bien. On a mangé des chevaux. Ici, il n'y a pas de chevaux. Tant pis. »" },
      { with: "gloup", text: "Un troll s'accroupit devant Gloup, le renifle, puis le soulève par la peau du cou, si c'est un cou, pour le regarder de plus près. Gloup lui crache au visage. Le troll éclate de rire et le repose avec une délicatesse étonnante." },
    ],
    choices: [
      { label: "« Il y a une porte sous l'eau. Vous savez creuser ? »", fx: { flag: "V:grauk_porte" }, back: "VE_puits" },
      { label: "« Restez ici. Tenez le puits derrière moi. »", fx: { flag: "V:grauk_tient", fac: { bornes: 5 } }, back: "VE_puits" },
    ] },

  // ------------------------------------------------------------------ side quest: the drowned of the well
  VE_puits_noyes: { act: "V", title: "Ceux qui attendent", place: "VE_l_puits", ambiance: "eau",
    fx: { questSeen: "VE_q_noyes" },
    text: [
      "Sur les marches les plus basses, celles que l'eau recouvre à moitié, ils sont assis. Des dizaines. Des hommes, des femmes, des enfants, en vêtements de toutes les époques, trempés, gris, immobiles. Ils regardent l'eau. Ils ne te regardent pas. Ils attendent quelque chose, comme on attend un bac qui ne vient pas.",
      "Quand tu approches, l'un d'eux tourne la tête. Un vieil homme, en tablier de cuir de tanneur. « On nous a appelés, dit-il. Chacun par notre nom. Alors on est venus. Mais personne ne nous dit où aller, maintenant. » Il regarde ses mains. « On ne sait plus nos noms. Elle les a gardés. Elle garde tout. »",
      { if: { has: "passe:aide" }, text: "Parmi eux, une femme de Saint-Gilles. Tu l'as portée jusqu'au temple, un soir de pluie. Elle ne te reconnaît pas." },
      { with: "aubin", text: "Frère Aubin s'est figé sur la dernière marche sèche. Il cherche des visages parmi eux. Tu sais lesquels. Il ne les trouve pas : ses frères sont restés au lac, dans leur chapelle. Il en a l'air soulagé, et honteux de l'être." },
    ],
    choices: [
      { label: "Leur rendre leurs noms, ceux de la margelle", if: { has: "V:noms_lus" }, why: "Tu ne connais pas leurs noms. Il faudrait les avoir lus quelque part.", to: "VE_puits_noyes_noms" },
      { label: "« Laisse-moi dire l'office pour eux », dit Frère Aubin", who: "aubin", test: { dom: "magie", diff: -10, label: "L'office des noyés", help: [A_AUB, A_PIP] }, win: { fx: { conf: { aubin: 8 }, flag: "V:noyes_aubin" }, to: "VE_puits_noyes_noms" }, lose: { to: "VE_puits_noyes_combat" } },
      { label: "Leur ordonner de te laisser passer, avec la Marque", tag: "Marque +1", stain: true, hide: { mark: { max: 0 } }, fx: { mark: 1, set: { noyes_puits: "commandes" }, quest: "VE_q_noyes", flag: "V:noyes_fait", fear: { pip: 10, aubin: 10 } }, to: "VE_puits_noyes_fin" },
      { label: "Ce ne sont plus des gens. Te frayer un passage.", to: "VE_puits_noyes_combat" },
      { label: "Les laisser attendre", refuse: true, fx: { set: { noyes_puits: "laisses" }, flag: "V:noyes_fait" }, back: "VE_puits" },
    ] },
  VE_puits_noyes_noms: { act: "V", title: "Les noms rendus", place: "VE_l_puits", ambiance: "eau",
    fx: { set: { noyes_puits: "nommes" }, quest: "VE_q_noyes", flag: "V:noyes_fait", ep: ["seance", 4000], conf: { pip: 8, aubin: 5 }, fac: { brumefeuille: 5 } },
    text: [
      { if: { not: { has: "V:noyes_aubin" } }, text: "Tu remontes jusqu'à la margelle, et tu redescends avec les noms. Tu les dis un par un, à voix haute, en marchant le long des marches. *Jehan Loriot. La mère Gertrude. Les trois petits Fournier.* Tu ne sais pas qui est qui. Ça n'a pas d'importance. À chaque nom, quelqu'un, quelque part sur les marches, lève la tête." },
      { if: { has: "V:noyes_aubin" }, with: "aubin", text: "Frère Aubin dit l'office des noyés, debout dans l'eau jusqu'aux genoux, et à l'endroit où l'on nomme les morts, il s'arrête, et il attend. Et les morts disent leur nom eux-mêmes, un par un, d'une voix rouillée, comme on retrouve un mot qu'on avait sur le bout de la langue." },
      "Le vieux tanneur se lève le premier. Il a l'air surpris de pouvoir. Il monte une marche, puis une autre, puis il se retourne vers les autres, et il leur fait signe, le geste qu'on fait aux enfants pour les faire rentrer à la maison. Ils se lèvent. Ils montent. Pas vers toi : vers le haut du puits, vers l'escalier, vers la porte, et au-delà de la porte, la glace, et au-delà de la glace, le jour.",
      "La petite femme de Saint-Gilles passe la dernière. Elle s'arrête devant toi. Elle ne te reconnaît toujours pas. Elle te touche la joue, du bout des doigts, comme on touche un enfant qui dort, et elle passe.",
    ],
    choices: [{ back: "VE_puits" }] },
  VE_puits_noyes_combat: { act: "V", title: "Les marches noyées", place: "VE_l_puits", ambiance: "eau",
    combat: { title: "Les noyés du puits", enemies: [{ id: "VE_noye_puits", n: 3 }], terrain: "bati",
      win: { fx: { set: { noyes_puits: "combattus" }, quest: "VE_q_noyes", ep: ["seance", 3000] }, to: "VE_puits_noyes_fin" },
      lose: { fx: { set: { noyes_puits: "combattus" }, quest: "VE_q_noyes", pv: -6 }, to: "VE_puits_noyes_fin" },
      flee: { label: "Remonter sur le palier", dom: "discretion", diff: -10, to: "VE_puits" } },
    text: [
      "Ils se lèvent ensemble, tous, avec un bruit d'eau qui s'égoutte. Ils ne crient pas. Ils tendent les bras vers toi, lentement, comme on tend les bras vers quelqu'un qu'on n'a pas vu depuis longtemps, et l'eau monte avec eux, le long des marches.",
    ] },
  VE_puits_noyes_fin: { act: "V", title: "Les marches vides", place: "VE_l_puits",
    fx: { flag: "V:noyes_fait" },
    text: [
      { if: { is: { noyes_puits: "commandes" } }, text: "Tu lèves ta main tachée, et ils s'écartent. Tous, d'un même mouvement, comme des herbes sous le vent. Ils te laissent passer, la tête basse. Ils ne t'obéissent pas : ils obéissent à ce qui est dans ta main. Tu le sais. Tu sens leurs yeux dans ton dos tout le long des marches." },
      { outcome: "win", text: "Les derniers retombent dans l'eau, et l'eau se referme sur eux sans une ride. Les marches sont vides. Il ne reste sur le bois mouillé que des empreintes de pieds nus, qui sèchent lentement." },
      { outcome: "lose", text: "Ils t'ont roulé{e} dans l'eau, tenu{e}, retourné{e}, comme on secoue un sac. Puis, d'un coup, ils t'ont lâché{e}, et ils se sont rassis, et ils ont recommencé à attendre. Tu remontes sur le palier en crachant de l'eau noire. Ils ne te regardent plus." },
    ],
    choices: [{ back: "VE_puits" }] },

  // ------------------------------------------------------------------ the bottom of the well: the gate under the water
  VE_puits_fond: { act: "V", title: "La vanne", place: "VE_l_puits", ambiance: "eau",
    text: [
      "L'escalier de bois s'arrête à l'eau. Sous la surface noire, tu devines la suite : des marches de pierre qui continuent de descendre, et au bout, dans la paroi, une porte basse, fermée par une vanne de bois et de fer, comme celle d'un bief. L'eau la retient. Pour passer, il faudrait soit vider le puits, soit nager jusqu'à elle dans le noir, et l'ouvrir de l'intérieur.",
      "Et l'eau n'est pas vide. Tu le sais avant de voir la forme : une silhouette énorme, assise au fond, tassée sur elle-même, faite de vase et de farine mouillée, qui garde la vanne comme un chien garde une porte. Le gardien de vase, celui de la Source sous le moulin. Il a grandi.",
      { if: { has: "V:bart_aide" }, text: "Barthélemy est à côté de toi, et il regarde la vanne avec un œil de meunier. « Il y a un treuil, dit-il. Là, sous la troisième marche. Il faut juste que quelqu'un le tienne pendant que l'autre tire. »" },
      { if: { has: "V:grauk_porte" }, text: "Les trolls ont déjà commencé à sonder la paroi à coups de pic, depuis que tu as parlé de la porte à Grauk." },
      { if: { has: "V:grauk_puits" }, text: "Grauk s'est penché au-dessus de l'eau, le nez froncé. « Une porte, dit-il, ça se passe par-dessus, par-dessous ou par à côté. Par à côté, c'est le mieux. La roche est tendre, ici. »" },
    ],
    choices: [
      { label: "Laisser Barthélemy ouvrir la vanne", hide: { not: { has: "V:bart_aide" } }, fx: { set: { puits_voie: "vanne" } }, to: "VE_puits_fin" },
      { label: "Laisser les trolls percer la paroi à côté de la porte", hide: { not: { has: "V:grauk_puits" } }, fx: { set: { puits_voie: "trolls" } }, to: "VE_puits_fin" },
      { label: "Gloup plonge en silence, et file vers la vanne", who: "gloup", test: { dom: "discretion", diff: -10, label: "Passer sous le gardien", help: [A_GLO] }, win: { fx: { set: { puits_voie: "gloup" }, conf: { gloup: 10 } }, to: "VE_puits_fin" }, lose: { to: "VE_puits_fond_combat" } },
      { label: "Plonger, nager jusqu'à la vanne sans réveiller le gardien", test: { dom: "discretion", diff: -20, label: "Nager dans le noir", help: [A_PIP, A_COL, A_EAU] }, win: { fx: { set: { puits_voie: "nage" }, ep: ["seance", 2500] }, to: "VE_puits_fin" }, lose: { to: "VE_puits_fond_combat" } },
      { label: "Descendre dans l'eau et affronter le gardien", to: "VE_puits_fond_combat" },
      { back: "VE_puits" },
    ] },
  VE_puits_fond_combat: { act: "V", title: "Le gardien de la vanne", place: "VE_l_puits", ambiance: "eau",
    combat: { title: "Le gardien de la vanne", enemies: ["VE_gardien_puits", { id: "VE_noye_puits", n: 2 }], terrain: "bati",
      win: { fx: { set: { puits_voie: "combat" }, ep: ["seance", 5000] }, to: "VE_puits_fin" },
      lose: { fx: { set: { puits_voie: "emporte" }, pv: -10 }, to: "VE_puits_fin" } },
    text: [
      "Le gardien se lève. L'eau du puits se soulève avec lui, en une seule vague lente, et deux noyés sortent de ses flancs comme des branches d'un tronc. Il n'a pas de visage. Il a, à la place, une empreinte de main, une main d'enfant, enfoncée dans la vase.",
      { with: "pip", text: "Pip monte au-dessus de l'eau et brille de toutes ses forces. La lumière tombe sur le gardien, et le gardien recule, une seconde, comme un homme qui a reçu le soleil dans les yeux." },
    ] },
  VE_puits_fin: { act: "V", title: "La porte sous l'eau", place: "VE_l_puits",
    fx: { flag: "V:puits", ep: ["histoire", 5000], reveal: "VE_l_forge" },
    text: [
      { if: { is: { puits_voie: "vanne" } }, text: "Barthélemy plonge les bras dans l'eau noire jusqu'aux épaules, trouve le treuil, et le tourne, en ahanant, avec des gestes qu'il a faits dix mille fois. La vanne grince. L'eau du puits se met à baisser, avec un bruit de baignoire qu'on vide, et le gardien, au fond, se tasse, s'étale, se défait en une flaque sans forme. La porte basse apparaît, ruisselante, ouverte." },
      { if: { is: { puits_voie: "vanne" } }, text: "« Allez, dit le meunier. Moi, je remonte. J'ai un moulin. » Il te serre la main, une seule fois, fort. Sa main est blanche de farine. Elle ne l'a jamais été autant." },
      { if: { is: { puits_voie: "trolls" } }, text: "Les trolls attaquent la paroi à côté de la porte avec leurs pics, en chantant faux une chanson de carrier qui couvre toutes les autres voix du puits. La roche cède en une heure. Un trou rond, juste assez large pour Grauk, s'ouvre sur un boyau qui descend, sec, à côté de la porte noyée. Le gardien, au fond, n'a pas bougé : personne n'a touché à sa porte." },
      { if: { is: { puits_voie: "trolls" } }, text: "« Voilà, dit Grauk en s'essuyant le front. Par à côté. On reste ici. Si quelque chose remonte, on le renvoie en bas. Si c'est toi, on te donnera à manger. »" },
      { if: { is: { puits_voie: "gloup" } }, text: "Gloup plonge. Tu ne le vois plus. Le gardien ne bouge pas : pour lui, Gloup est de l'eau dans l'eau, de la vase dans la vase. Une longue attente. Puis la vanne grince, se soulève d'un pied, et l'eau du puits s'engouffre dessous avec un bruit de torrent, emportant le gardien qui se défait en tournoyant. Gloup reparaît à la surface, très fier, avec un poisson aveugle qu'il a trouvé en route." },
      { if: { is: { puits_voie: "nage" } }, text: "Tu nages dans le noir, une main sur la paroi, en comptant tes brasses. Le gardien est là, à trois toises, immense, assoupi. Tu passes. Tu trouves la vanne à tâtons, la barre de fer, le loquet. Tu tires. La vanne se soulève, et l'eau t'emporte avec elle par la porte basse, et tu te retrouves de l'autre côté, sur des marches sèches, à tousser, vivant{e}." },
      { if: { is: { puits_voie: "combat" } }, text: "Le gardien s'effondre dans un grand bruit de vase, et l'eau qui le portait s'effondre avec lui, dévale par la porte basse qu'il ne garde plus, et le puits se vide d'un coup, en tourbillonnant. Quand le niveau s'arrête, la porte est là, ouverte, ruisselante." },
      { if: { is: { puits_voie: "emporte" } }, text: "Le gardien te prend dans ses bras, et il t'écrase, et il t'entraîne vers le fond, et tu crois mourir. Puis la vanne cède sous votre poids à tous les deux, et l'eau vous emporte par la porte basse, et tu roules sur des marches de pierre dans un torrent noir. Quand tu t'arrêtes, tu es de l'autre côté, couvert{e} de bleus, crachant de l'eau, et le gardien n'est plus qu'une traînée de vase sur les marches." },
      "Derrière la porte, l'escalier continue de descendre. Il fait plus chaud. Une odeur monte, que tu reconnais aussi : le charbon, le fer rouge, la cendre.",
    ],
    choices: [{ label: "Descendre vers l'odeur de forge", big: true, travel: "VE_r_forge" }] },
});

Object.assign(P, {
  // ================================================================== floor 2: the forge (act II)
  VE_forge_arrivee: { act: "V", title: "La forge d'Hildre", place: "VE_l_forge",
    fx: { ep: ["seance", 2500] },
    text: [
      "La chaleur te prend au visage dès la dernière marche. Une salle immense, voûtée, noire de quatre siècles de suie, et au milieu, un foyer de forge large comme une aire de battage, où brûle un feu sans bois et sans charbon, un feu qui monte d'une fente dans le sol. Il est rouge sombre, presque brun, et il fait des ombres qui ne suivent pas tout à fait les choses.",
      "Autour du foyer, des enclumes. Des dizaines, en cercle, de toutes les tailles, et sur chacune, posé, un maillon de chaîne inachevé, gros comme un homme. Des marteaux pendent aux murs, des pinces, des tenailles, des soufflets de cuir crevés. C'est ici qu'on a forgé la chaîne du gouffre. Maillon par maillon, il y a quatre cents ans, sous la montagne, pour que personne ne voie ce qu'on enchaînait.",
      "Au fond de la salle, sur un socle de pierre noire, la plus grande enclume : celle d'Hildre. Et quelqu'un y travaille. Tu entends le marteau. Un coup, puis un autre, lent, régulier, comme un cœur qui bat.",
      { if: { clue: "r2_forge" }, text: "Tu as déjà vu une enclume comme celle-là, à la Forge-Mère de Ferrance. Celle-ci est sa sœur aînée." },
      { with: "charline", text: "Charline s'arrête sur la dernière marche. Le feu de la fente s'est penché vers elle, tout entier, comme un champ de blé sous le vent. Elle ne recule pas. Elle a les yeux pleins de larmes et elle ne sait pas pourquoi." },
    ],
    choices: [{ label: "Entrer dans la forge", big: true, to: "VE_forge" }] },
  VE_forge: { act: "V", title: "Le cercle des enclumes", place: "VE_l_forge", hub: true, backName: "le cercle des enclumes",
    text: [
      { first: true, text: "Tu avances entre les enclumes. Le sol est chaud sous tes bottes, et la cendre craque comme de la neige gelée. Le marteau, au fond, ne s'est pas arrêté. Les ombres des maillons inachevés tournent lentement sur les murs." },
      { again: true, text: "Le cercle des enclumes, la fente rouge au milieu, la chaleur. Les maillons de chaîne attendent sur leurs enclumes qu'on finisse de les forger." },
      { again: true, if: { has: "V:vendrel_fait" }, text: "Le marteau s'est tu. On n'entend plus que le feu." },
      { again: true, if: { has: "V:clou_rendu" }, text: "Ansgar s'est assis sur une enclume, près du feu, ses mains gantées sur les genoux. Il regarde la forge d'Hildre comme on regarde une église." },
    ],
    choices: [
      { label: "L'enclume d'Hildre", hide: { seen: "VE_forge_enclume" }, to: "VE_forge_enclume" },
      { label: "Tremper le Clou dans le feu d'Hildre", hide: { any: [{ not: { relic: "clou" } }, { has: "clou:trempe" }, { has: "V:clou_rendu" }] }, to: "VE_forge_trempe" },
      { label: "Les voix dans l'escalier des forgerons", hide: { any: [{ not: { given: "clou" } }, { seen: "VE_forge_ansgar" }] }, to: "VE_forge_ansgar" },
      { label: "Charline devant le feu", with: "charline", hide: { seen: "VE_forge_charline" }, to: "VE_forge_charline" },
      { label: "L'homme enchaîné aux soufflets", hide: { has: "V:secretaire_fait" }, to: "VE_forge_secretaire" },
      { label: "Celui qui frappe sur l'enclume", hide: { any: [{ has: "vendrel:demasque" }, { has: "V:vendrel_fait" }] }, to: "VE_forge_vendrel" },
      { label: "La forme aux gants blancs", hide: { any: [{ not: { has: "vendrel:demasque" } }, { has: "V:vendrel_fait" }] }, to: "VE_forge_ombre" },
      { label: "Descendre par l'escalier derrière l'enclume", big: true, if: { has: "V:vendrel_fait" }, why: "Quelqu'un se tient entre toi et l'escalier.", to: "VE_forge_fin" },
    ] },
  VE_forge_enclume: { act: "V", title: "L'enclume d'Hildre", place: "VE_l_forge",
    fx: { ep: ["perso", 1000] },
    text: [
      "L'enclume d'Hildre est faite d'une seule pierre noire, si lourde qu'elle s'est enfoncée d'un pied dans le sol depuis qu'on l'a posée. Elle porte six trous carrés, en ligne, de la taille d'un clou de charpente. Cinq sont vides, nets, les bords polis par l'usage. Le sixième est bouché : du plomb, coulé dedans, à ras, et sur le plomb quelqu'un a frappé au poinçon un petit signe que tu ne connais pas. Une main fermée.",
      "Sur le flanc de l'enclume, gravé profond, en lettres anciennes et carrées, un compte de forgeron : *Six clous pour six mains. Trois pour la porte. Trois pour la chaîne. Le sixième ne sera pas forgé. Il le tient de l'intérieur.* Et plus bas, d'une autre main, plus maladroite, comme gravé à la pointe d'un couteau par quelqu'un qui pleurait : *Pardonne-moi. H.*",
      { with: "charline", text: "Charline passe le doigt sur le *H*, et l'y laisse longtemps. « Elle savait, dit-elle tout bas. Ma grande aïeule. Elle a forgé la chaîne en sachant. »" },
    ],
    choices: [{ back: "VE_forge" }] },
  VE_forge_trempe: { act: "V", title: "La trempe", place: "VE_l_forge",
    text: [
      "Tu sors le Clou de Hildre de ta besace. Dans la forge de sa créatrice, il est chaud, presque brûlant, et il tire vers la fente du sol comme un chien tire vers sa maison. Tu sais ce qu'il faudrait faire, sans qu'on te l'ait appris : le plonger dans le feu d'Hildre, le temps qu'il rougisse, puis dans l'eau, d'un coup, pour qu'il retrouve sa dureté d'origine. Une trempe. La dernière.",
      "Mais le feu de la fente n'est pas un feu de charbon. Il faudra y tenir le Clou à mains nues, ou presque, et assez longtemps.",
    ],
    choices: [
      { label: "Le tenir toi-même dans le feu", test: { dom: "combat", diff: -10, label: "Tenir le Clou dans le feu d'Hildre", help: [{ if: { item: "VE_gant_ancien" }, v: 15 }] }, win: { fx: { flag: "clou:trempe", pv: -6, ep: ["seance", 2500] }, to: "VE_forge_trempe_fin" }, lose: { fx: { pv: -14, flag: "V:trempe_ratee" }, to: "VE_forge_trempe_fin" } },
      { label: "« Donne. Le feu m'obéit », dit Charline", who: "charline", test: { dom: "magie", diff: -10, label: "Commander le feu d'Hildre", help: [A_CHA] }, win: { fx: { flag: "clou:trempe", conf: { charline: 10 }, ep: ["seance", 2500] }, to: "VE_forge_trempe_fin" }, lose: { fx: { flag: "V:trempe_ratee", pv: -4 }, to: "VE_forge_trempe_fin" } },
      { label: "Ne pas y toucher", back: "VE_forge" },
    ] },
  VE_forge_trempe_fin: { act: "V", title: "Le Clou trempé", place: "VE_l_forge",
    text: [
      { if: { all: [{ has: "clou:trempe" }, { not: { present: "charline" } }] }, text: "Tu tiens le Clou dans la fente jusqu'à ce que ta peau cloque, et plus longtemps encore. Il devient rouge, puis orange, puis blanc. Tu le retires et tu le plonges dans un baquet d'eau de pierre, au pied de l'enclume. Le sifflement est énorme. La vapeur te brûle le visage. Quand elle se dissipe, le Clou est noir, mat, et quand tu le frappes contre l'enclume, il sonne comme une cloche." },
      { if: { all: [{ has: "clou:trempe" }, { present: "charline" }] }, with: "charline", text: "Charline prend le Clou de tes mains, et elle le plonge dans la fente, à mains nues, et le feu ne la brûle pas. Il lui lèche les poignets comme un chien. Elle le tient jusqu'à ce qu'il blanchisse, puis elle le trempe, d'un geste de forgeron qu'elle n'a jamais appris et qu'elle a dû voir faire mille fois, enfant, avant l'incendie. Elle te le rend, noir et sonnant. « Mon père serait content, dit-elle. Ou il me tuerait. Les deux, sans doute. »" },
      { if: { has: "V:trempe_ratee" }, text: "Tu le lâches. Le feu est trop fort, ou tes mains pas assez. Le Clou tombe dans la cendre au bord de la fente, rouge sombre, et tu le ramasses avec des tenailles, une fois refroidi. Il est comme avant. Ni mieux, ni pire. Tes mains, elles, s'en souviendront." },
    ],
    choices: [{ back: "VE_forge" }] },
  VE_forge_ansgar: { act: "V", title: "Le Clou rapporté", place: "VE_l_forge",
    fx: { relic: "clou", flag: ["V:clou_rendu", "clou:reforge"], meet: "ansgar", ep: ["histoire", 4000], fac: { ordre: 5 } },
    text: [
      "Des voix, dans un escalier latéral que tu n'avais pas remarqué, un escalier étroit qui monte vers l'ouest. Des pas lourds, une lanterne, une toux. Puis trois hommes en tablier de cuir, couverts de poussière de roche, qui débouchent dans la forge et s'arrêtent, saisis, à la vue du foyer. Le premier est vieux, la barbe blanche, les mains enfermées dans des gants de cuir épais. Ansgar Hildrand, maître de la Forge-Mère de Ferrance.",
      "« L'escalier des forgerons, dit-il en reprenant son souffle. De la tour d'Hildre jusqu'ici. Nos registres en parlaient. Personne ne l'avait pris depuis quatre cents ans. » Il regarde la forge, le feu, les maillons inachevés, longtemps. « Elle a travaillé ici. Notre mère à tous. »",
      "Puis il fait un signe à ses compagnons, et l'un d'eux défait un paquet de cuir, et il en sort le Clou de Hildre. Ce n'est plus tout à fait celui que tu as donné à la Forge. On l'a reforgé : la tête a été reprise, la tige redressée, et sur la tête, à côté du vieux poinçon d'Hildre, il y a un poinçon neuf, une petite flamme dans un cercle.",
      { if: { is: { charline_arc: ["forge", "pardon"] } }, text: "« C'est ma fille qui l'a chauffé, dit Ansgar. À la tour. Moi, je ne peux plus tenir le marteau. Mais je peux encore dire où frapper. » Il ne la regarde pas en le disant. Il n'a pas besoin." },
      "Il te tend le Clou de ses deux mains gantées, maladroitement, comme on tend un nouveau-né. « Tu nous l'as confié. La Forge le rend. On ne garde pas ce qui doit servir. »",
      { with: "charline", text: "Charline s'est approchée de son père, et elle se tient à côté de lui sans le toucher, à un doigt de son épaule. Ils regardent le feu d'Hildre ensemble. Au bout d'un moment, Ansgar lève sa main gantée et la pose sur la nuque de sa fille. Elle ferme les yeux." },
    ],
    choices: [{ back: "VE_forge" }] },
  VE_forge_charline: { act: "V", title: "Le feu qui se penche", place: "VE_l_forge", with: "charline",
    fx: { conf: { charline: 8 }, ep: ["seance", 1500] },
    text: [
      "Charline s'est assise en tailleur au bord de la fente, si près que la chaleur fait friser les mèches rousses qui dépassent de sa capuche. Le feu monte vers elle par vagues lentes, et redescend, et remonte. Elle lui parle à voix basse. Tu n'entends pas ce qu'elle dit.",
      { if: { is: { charline_arc: "brule" } }, text: "« J'ai brûlé l'Athénée, dit-elle sans se retourner. Tu le sais. Corbin et ses registres, ses pages arrachées, ses mensonges en cuir relié. J'ai cru que ça me ferait du bien. » Elle regarde ses mains. « Ça m'a fait du bien. C'est ça qui me fait peur. »" },
      { if: { is: { charline_arc: "pardon" } }, text: "« Mon père m'a pardonné, dit-elle sans se retourner. À la tour. Ou c'est moi qui lui ai pardonné de ne pas l'avoir fait plus tôt. Je ne sais plus dans quel sens ça va. » Elle rit un peu. « Le feu, lui, ne m'a jamais rien reproché. »" },
      { if: { is: { charline_arc: "forge" } }, text: "« Je vais reprendre la Forge-Mère, dit-elle sans se retourner. Si je remonte. Mon père l'a décidé à la tour, et pour une fois je n'ai pas discuté. » Elle sourit au feu. « Une Hildrand à la forge, avec des mains qui marchent. Ça faisait longtemps. »" },
      "« Il me dit qu'il est fatigué, ajoute-t-elle. Le feu. Qu'il brûle ici depuis quatre cents ans pour que les maillons restent chauds, au cas où il faudrait les reforger. Il attend qu'on lui dise qu'il peut s'arrêter. » Elle se tourne enfin vers toi. « Je crois qu'en bas, quelqu'un attend la même chose. »",
    ],
    choices: [{ back: "VE_forge" }] },

  // ------------------------------------------------------------------ side quest: the secretary with the white gloves
  VE_forge_secretaire: { act: "V", title: "L'homme aux soufflets", place: "VE_l_forge",
    fx: { questSeen: "VE_q_secretaire", meet: "VE_lucain" },
    text: [
      "Contre le mur du fond, à côté d'un soufflet de forge grand comme une barque, un homme est enchaîné par la cheville à un anneau scellé dans la pierre. Il actionne le soufflet. Il le fait depuis longtemps : ses mains sont en sang, ses bras tremblent, et le soufflet halète au même rythme que lui. Il porte des gants blancs. Ils ne le sont plus.",
      "« Lucain Lormier, dit-il quand tu t'approches, sans s'arrêter de pomper. Secrétaire du premier conseiller d'Aldaran. J'ai porté ses lettres à Fort-Gaudre, à Sainte-Orme, au manoir de Thavar. J'ai porté son or. » Il a un petit rire sec. « Il m'a amené ici pour que je tienne le feu. Il a dit que ce serait un honneur. Il a dit que je verrais naître un monde. »",
      { if: { has: "vendrel:demasque" }, text: "« Il est descendu par l'eau, après le gué. Il m'a fait venir par la même eau. Je ne sais pas comment je respire encore. Ce qui reste de lui passe ici, parfois. Il ne me reconnaît plus. Il dit seulement : *encore*. »" },
      "Il te regarde, enfin. « Je sais ce que j'ai fait. Je ne demande pas qu'on me pardonne. Je demande qu'on me laisse arrêter de pomper. »",
    ],
    choices: [
      { label: "Briser la chaîne", test: { dom: "combat", diff: -10, label: "Briser un anneau de forge", help: [A_THA, { if: { item: "pied_de_biche" }, v: 15 }, { if: { item: "VE_lame_durn" }, v: 5 }] }, win: { to: "VE_forge_secretaire_libre" }, lose: { fx: { pv: -4 }, to: "VE_forge_secretaire_libre" } },
      { label: "« Une serrure de cheville. Donne-moi un instant », dit Coliane", who: "coliane", test: { dom: "discretion", diff: 0, label: "Crocheter le fer", help: [A_COL] }, win: { fx: { conf: { coliane: 5 } }, to: "VE_forge_secretaire_libre" }, lose: { to: "VE_forge_secretaire_libre" } },
      { label: "Lui demander d'abord ce qu'il sait du conseiller", hide: { seen: "VE_forge_secretaire_sait" }, to: "VE_forge_secretaire_sait" },
      { label: "Le laisser à sa chaîne : il a porté l'or de cette guerre", fx: { set: { secretaire: "laisse" }, quest: "VE_q_secretaire", flag: "V:secretaire_fait", conf: { thavary: 3, pip: -5 } }, back: "VE_forge" },
    ] },
  VE_forge_secretaire_sait: { act: "V", title: "Ce que sait Lucain", place: "VE_l_forge",
    fx: { flag: "V:secretaire_parle" },
    text: [
      "Lucain pompe, et il parle, entre deux souffles. « Il veut la couronne. Pas pour lui : il n'a pas d'enfant. Pour son neveu, un garçon de douze ans qu'il a fait élever à Hautmont, et qui ne sait même pas qu'il existe, son oncle. Il veut une lignée. Il dit que les Aldar ont eu quatre cents ans, et que c'est assez. »",
      "« Elle lui a promis. Elle promet à tout le monde. Mais il y a une chose qu'il ne sait pas, et que moi je sais, parce que je lis les lettres avant de les cacheter. » Il s'arrête de pomper, un instant. Le soufflet retombe. « Le garçon est mort. À la Saint-Michel. Une fièvre grise, à Hautmont. On a écrit au conseiller. J'ai brûlé la lettre. J'avais peur de ce qu'il ferait. »",
      { if: { has: "vendrel:demasque" }, text: "Il reprend le soufflet. « Ça n'a plus d'importance, maintenant. Il n'y a plus personne pour l'entendre. »" },
      { if: { not: { has: "vendrel:demasque" } }, text: "Il reprend le soufflet. « Il ne le sait toujours pas. Il forge pour un mort. »" },
    ],
    choices: [{ back: "VE_forge_secretaire" }] },
  VE_forge_secretaire_libre: { act: "V", title: "La cheville libre", place: "VE_l_forge",
    fx: { set: { secretaire: "libre" }, quest: "VE_q_secretaire", flag: "V:secretaire_fait", conf: { pip: 5, aubin: 5 }, ep: ["seance", 2500], regard: { VE_lucain: "redevable" } },
    text: [
      { outcome: "win", text: "L'anneau cède. Lucain lâche le soufflet, et le soufflet retombe avec un long soupir de cuir, et ne se relève pas. Lucain regarde sa cheville, sa cheville libre, comme on regarde un objet perdu qu'on retrouve." },
      { outcome: "lose", text: "L'anneau résiste. Tu t'acharnes, tu te blesses, tu recommences. Il finit par céder, de travers, en t'arrachant un ongle. Lucain lâche le soufflet. Il se tait. Il regarde sa cheville libre." },
      "Il se relève en s'appuyant au mur. Il ne te remercie pas : il n'a pas l'air de savoir comment on fait. Il ôte ses gants, ses gants qui ne sont plus blancs, et il les jette dans la fente du feu, où ils flambent d'un coup. Ses mains, dessous, sont propres. Pas de tache.",
      "« Je vais remonter, dit-il. Je vais aller à Hautmont, et je vais dire à la princesse tout ce que j'ai porté, et pour qui, et combien. Elle me fera pendre, sans doute. » Il hausse les épaules. « Je l'aurai dit, au moins. Il y a des gens à qui ça fera du bien de savoir. »",
    ],
    choices: [{ back: "VE_forge" }] },

  // ------------------------------------------------------------------ Vendrel, if he was never unmasked
  VE_forge_vendrel: { act: "V", title: "Le premier conseiller", place: "VE_l_forge",
    fx: { meet: "vendrel" },
    text: [
      "Il frappe sur l'enclume d'Hildre, en tablier de cuir sur ses habits noirs de conseiller, et ses gants blancs sont posés, bien pliés, sur le bord de l'enclume, à l'abri des étincelles. Maître Vendrel. Tu le reconnais à sa façon de se tenir, droit, poli, attentif, même ici. Puis il se retourne, et tu ne le reconnais plus.",
      "La tache de son cou a tout pris. Elle lui monte jusqu'aux yeux, elle lui descend jusqu'aux mains, noire, luisante, mouvante, comme une peau de vase posée sur la sienne. Son bras droit, celui qui tient le marteau, n'est plus un bras : c'est une coulée noire qui a pris la forme d'un bras, avec trop de doigts. Sur l'enclume, rouge, à demi forgée, une clé. Une clé noire, épaisse, avec trois pannetons.",
      "« {hero}, dit-il de sa voix douce. Je vous attendais plus tôt. Vous avez fait un très long détour. » Il pose le marteau. « Vous avez gagné la guerre pour moi, vous le savez ? Aldaran ou Vel-Orin, cela ne faisait aucune différence. Il fallait seulement qu'on se batte assez longtemps pour que plus personne ne regarde vers la montagne. »",
      { if: { is: { couronne: "aldaran" } }, text: "« Sa Majesté vous a promis l'adoubement, je crois. Je lui ai conseillé d'attendre. On n'adoube pas quelqu'un qui pourrait encore servir à autre chose. »" },
      { if: { is: { couronne: "velorin" } }, text: "« La duchesse vous a payé{e}, je crois, en couronnes neuves. Les miennes. Elle ne l'a jamais compris. Elle compte trop bien pour comprendre d'où vient l'argent. »" },
    ],
    choices: [
      { label: "« Qu'est-ce que vous forgez ? »", to: "VE_forge_vendrel_offre" },
    ] },
  VE_forge_vendrel_offre: { act: "V", title: "La quatrième clé", place: "VE_l_forge",
    text: [
      "« Une clé, dit Vendrel. La seule qui manque. Les Cinq ont fait trois clés pour fermer. Personne n'a jamais pensé à en faire une pour ouvrir. » Il caresse la clé rouge du bout de ses doigts noirs, et elle ne le brûle pas. « Elle m'a dit comment. Il faut les trois clés pour la tremper. Une goutte de chacune. Et elle ouvrira la porte, et ce qu'il y a derrière se répandra, et ceux qui l'auront ouverte la tiendront en laisse. »",
      "« Je veux une couronne, {hero}. Je l'avoue. Je ne l'ai jamais caché qu'à ceux qui ne voulaient pas voir. Une couronne pour ma lignée, après quatre cents ans de rois qui ont bâti leur trône sur un homme enchaîné. Vous savez cela, maintenant, n'est-ce pas ? Que les Aldar sont des voleurs ? » Il tend sa main noire. « Prêtez-moi vos clés. Une goutte. Et je vous donnerai ce que vous voudrez. Une terre. Un titre. Votre maîtresse, rendue. Le village de votre enfance, tel qu'il était. »",
      { if: { has: "V:secretaire_parle" }, text: "Tu penses au garçon de douze ans, à Hautmont. À la lettre brûlée. Il forge pour un mort, et il ne le sait pas." },
      { with: "thavary", text: "Thavary a la main sur son épée et le visage blanc. Il lui a fait la même offre, un jour, contre l'Anneau. Il ne la regarde même pas." },
    ],
    choices: [
      { label: "Lui dire que son neveu est mort", hide: { not: { has: "V:secretaire_parle" } }, fx: { ep: ["histoire", 4000] }, to: "VE_forge_vendrel_parole" },
      { label: "Le convaincre qu'elle ne tiendra pas sa promesse", test: { dom: "social", diff: -20, label: "Ébranler le conseiller", help: [A_AUB, A_PIP, { if: { clue: "v_sauge" }, v: 10 }, { if: { clue: "v_margot" }, v: 5 }] }, win: { fx: { ep: ["histoire", 4000] }, to: "VE_forge_vendrel_parole" }, lose: { to: "VE_forge_vendrel_combat" } },
      { label: "« Il regarde tes clés. Moi, je regarde la sienne », dit Coliane", who: "coliane", test: { dom: "discretion", diff: -20, label: "Voler la clé sur l'enclume", help: [A_COL, A_PIP] }, win: { fx: { set: { vendrel_v: "depouille" }, conf: { coliane: 10 }, ep: ["histoire", 4000] }, to: "VE_forge_vendrel_fin" }, lose: { to: "VE_forge_vendrel_combat" } },
      { label: "Lui prêter une goutte de tes clés", tag: "Marque +1", stain: true, hide: { relics: { max: 0 } }, fx: { mark: 1, set: { vendrel_v: "pacte" }, flag: "V:pacte_vendrel", conf: { pip: -15, aubin: -15, coliane: -15, charline: -10, thavary: -10 }, fear: { pip: 15 } }, to: "VE_forge_vendrel_fin" },
      { label: "Refuser, et lever ton arme", to: "VE_forge_vendrel_combat" },
    ] },
  VE_forge_vendrel_parole: { act: "V", title: "Ce qui tient", place: "VE_l_forge",
    fx: { set: { vendrel_v: "brise" } },
    text: [
      { if: { has: "V:secretaire_parle" }, text: "Tu le lui dis. Le garçon. La fièvre grise, à la Saint-Michel. La lettre que Lucain a brûlée. Vendrel t'écoute avec une politesse parfaite, sans t'interrompre, comme il écoutait le roi. Quand tu as fini, il ne dit rien. Il regarde la clé rouge sur l'enclume. Puis il demande, très bas, à l'eau qui suinte au pied de l'enclume : « C'est vrai ? »" },
      { if: { not: { has: "V:secretaire_parle" } }, text: "Tu lui dis ce que tu sais d'elle. Qu'elle ne ment presque jamais : elle choisit ce qu'elle dit. Qu'elle ne sait que ce qu'on lui donne. Qu'elle a promis à Barthélemy sa fille, et que sa fille ne savait même pas le nom de son chien. Vendrel t'écoute, et son sourire tient, tient encore, puis il se tourne vers l'eau qui suinte au pied de l'enclume, et il demande, très bas : « Et à moi ? Qu'est-ce que tu m'as promis, exactement ? »" },
      "L'eau se tait. Puis elle répond, avec une douceur infinie, une voix de femme qui console un enfant : « Je t'ai promis une couronne, mon ami. Je n'ai jamais dit sur quelle tête. »",
      "Vendrel reste immobile un long moment. Puis il éclate de rire, un rire bref, presque gai, le rire d'un homme qui vient de comprendre qu'il a perdu une partie d'échecs à cause d'un coup qu'il aurait dû voir dès le début. « Bien joué, dit-il. Bien joué. » La vase de son visage se met à couler, lentement, comme de la cire. Il ne se débat pas. Il s'assied sur le socle de l'enclume, il remet ses gants blancs, avec soin, doigt par doigt. Et il se défait.",
      "Il ne reste de lui qu'un tablier de cuir, des habits noirs vides, une paire de gants blancs posés bien à plat sur la pierre. Et la clé rouge, sur l'enclume, qui refroidit et se fend en deux.",
    ],
    choices: [{ label: "Laisser la clé refroidir", fx: { flag: "V:vendrel_fait", ep: ["seance", 3000] }, back: "VE_forge" }] },
  VE_forge_vendrel_combat: { act: "V", title: "Le conseiller de vase", place: "VE_l_forge",
    combat: { title: "Maître Vendrel", enemies: ["VE_vendrel", { id: "VE_forgeron_cendre", n: 2 }], terrain: "bati",
      win: { fx: { ep: ["histoire", 5000] }, to: "VE_forge_vendrel_vaincu" },
      lose: { fx: { set: { vendrel_v: "vainqueur" }, pv: -10 }, to: "VE_forge_vendrel_fin" } },
    text: [
      "Vendrel soupire, comme on soupire devant un élève décevant, et il lève son bras noir. Autour de vous, deux silhouettes se détachent des enclumes : des forgerons de cendre, nés du feu de la fente, avec des marteaux de suie. Ils travaillaient pour lui. Ils travaillent encore.",
      "« Je n'aime pas ça, dit Vendrel. Je n'ai jamais aimé ça. Mais on fait ce qui tient. »",
    ] },
  VE_forge_vendrel_vaincu: { act: "V", title: "Le conseiller à terre", place: "VE_l_forge",
    text: [
      "Il tombe contre l'enclume d'Hildre, et la clé rouge glisse et tombe avec lui, et se brise sur le sol. Le bras noir se détache de son épaule comme une manche trop large et s'écoule dans la cendre. Ce qui reste de Vendrel est un homme maigre, très pâle, aux yeux cernés, qui respire mal et qui te regarde avec curiosité.",
      "« Vous allez me tuer, dit-il. C'est raisonnable. À votre place, je le ferais. » Il tousse. « Ou vous allez me laisser remonter, et je retournerai à Hautmont, et je trouverai un autre moyen. Je trouve toujours un autre moyen. Vous le savez. »",
    ],
    choices: [
      { label: "Finir ce que la guerre a commencé", fx: { set: { vendrel_v: "mort" }, conf: { thavary: 5, coliane: 5, pip: -5 } }, to: "VE_forge_vendrel_fin" },
      { label: "Le laisser à la forge, enchaîné à la place de Lucain", hide: { not: { is: { secretaire: "libre" } } }, fx: { set: { vendrel_v: "enchaine" }, conf: { coliane: 5, aubin: 5 } }, to: "VE_forge_vendrel_fin" },
      { label: "Le laisser remonter seul, sans arme et sans tache", fx: { set: { vendrel_v: "epargne" }, conf: { pip: 5, aubin: 5 }, fear: { thavary: 5 } }, to: "VE_forge_vendrel_fin" },
    ] },
  VE_forge_vendrel_fin: { act: "V", title: "La forge se tait", place: "VE_l_forge",
    fx: { flag: "V:vendrel_fait", ep: ["seance", 3000] },
    text: [
      { if: { is: { vendrel_v: "mort" } }, text: "Tu le fais. Il ne ferme pas les yeux. Il te regarde jusqu'au bout avec cette curiosité polie, comme s'il voulait savoir comment tu t'y prendrais. Puis la forge est silencieuse, et le feu de la fente baisse d'un coup, comme soulagé." },
      { if: { is: { vendrel_v: "enchaine" } }, text: "Tu refermes l'anneau de cheville sur lui, celui que Lucain a porté. Il ne proteste pas. Il regarde le soufflet géant, à côté de lui, et il a un petit sourire. « Ironique, dit-il. Très bien. Très juste. » Quand tu t'éloignes, il ne pompe pas. Il attend. Il attend toujours quelque chose." },
      { if: { is: { vendrel_v: "epargne" } }, text: "Tu lui montres l'escalier qui remonte, du menton. Il se relève, lentement, il remet ses gants blancs, et il s'en va, sans se retourner, d'un pas d'homme qui va à un conseil. Tu ne sais pas s'il arrivera en haut. Tu ne sais pas ce qu'il fera s'il y arrive." },
      { if: { is: { vendrel_v: "depouille" } }, with: "coliane", text: "Coliane passe derrière l'enclume pendant qu'il parle, et quand il tend la main vers la clé, la clé n'y est plus. Elle est dans la main de Coliane, qui la jette dans la fente du feu. La clé hurle en fondant. Vendrel la regarde fondre, et la vase de son visage coule avec elle, et l'eau, au pied de l'enclume, dit doucement : « Tu n'as plus rien à me donner, mon ami. » Il se défait en silence. Il ne reste que des gants blancs dans la cendre." },
      { if: { is: { vendrel_v: "pacte" } }, text: "Tu poses tes clés sur l'enclume, une à une, et il fait tomber sur chacune une goutte de sa clé rouge, et chacune grésille, et chacune noircit, un peu, à un endroit. Il te les rend avec une inclinaison de tête. « Merci, dit-il. Nous nous reverrons plus bas. Tous. » Il prend sa clé et s'en va vers l'escalier du fond, et tu le laisses passer devant toi. Ta paume est brûlante. Elle aime ce que tu viens de faire." },
      { if: { is: { vendrel_v: "vainqueur" } }, text: "Tu es à terre, contre une enclume, et il est au-dessus de toi, et il ne te tue pas. « Ce n'est pas mon rôle, dit-il. Elle vous veut en vie. » Il reprend sa clé, encore rouge, et il descend l'escalier du fond, sans hâte, en sifflotant un air de cour. Il sera en bas avant toi." },
      { if: { is: { vendrel_v: "brise" } }, text: "Les gants blancs sont toujours là, posés à plat sur le socle. Tu ne les touches pas." },
      { with: "pip", text: "Pip va se poser sur l'enclume d'Hildre, sur le sixième trou, celui qui est bouché de plomb. Il y reste un moment, la lumière basse. Puis il revient." },
    ],
    choices: [{ back: "VE_forge" }] },

  // ------------------------------------------------------------------ Vendrel's shadow, if he was unmasked at the ford
  VE_forge_ombre: { act: "V", title: "Les gants blancs", place: "VE_l_forge",
    text: [
      "Devant l'enclume d'Hildre, il y a une forme. Elle frappe sur l'enclume avec un marteau de vase, et le marteau ne fait aucun bruit, et c'est le son du marteau que tu entendais, et il ne vient de nulle part. La forme est noire, ruisselante, à peu près humaine, vêtue d'un col montant qui ne tient à rien. Seules ses mains sont nettes : deux gants blancs, impeccables, qui flottent au bout de bras de vase.",
      "Elle se retourne. Il n'y a pas de visage. Il y a, à la place, une surface d'eau noire où passent des reflets : la colline des Six, une tente bleue, une carte dépliée, l'île du gué. « Nous nous reverrons, dit-elle avec la voix de Vendrel, polie, posée. Plus bas. Elle m'a promis que nous nous reverrions tous. » Puis, un peu plus tard, la même phrase. Exactement la même.",
      "C'est tout ce qui reste de lui : ce qu'il a dit en dernier, avant d'entrer dans l'Isarde. L'eau l'a gardé, comme elle garde tout, et elle l'a mis là, devant l'escalier, comme on pose un vieux manteau sur une chaise pour faire croire qu'il y a quelqu'un.",
      { if: { is: { maitre: "sauve" } }, text: "Ta maîtresse, sur sa civière, au gué, a dit devant les deux couronnes qui il servait. C'est ce qui l'a perdu. Il n'en sait plus rien. Il ne sait plus rien." },
    ],
    choices: [
      { label: "« Ça, c'est de l'eau. L'eau, ça s'évapore », dit Charline", who: "charline", test: { dom: "magie", diff: -10, label: "Brûler l'ombre", help: [A_CHA] }, win: { fx: { conf: { charline: 10 }, set: { vendrel_v: "ombre_brulee" } }, to: "VE_forge_ombre_fin" }, lose: { to: "VE_forge_ombre_combat" } },
      { label: "« Je vais regarder dedans », dit Pip", who: "pip", test: { dom: "magie", diff: -10, label: "La lumière dans l'eau noire", help: [A_PIP] }, win: { fx: { conf: { pip: 10 }, set: { vendrel_v: "ombre_eclairee" } }, to: "VE_forge_ombre_fin" }, lose: { to: "VE_forge_ombre_combat" } },
      { label: "Lui répondre ce qui s'est passé au gué", test: { dom: "savoir", diff: -10, label: "Dire la fin à ce qui ne la sait pas", help: [{ if: { is: { couronne: "paix" } }, v: 10 }] }, win: { fx: { set: { vendrel_v: "ombre_dite" }, ep: ["seance", 2000] }, to: "VE_forge_ombre_fin" }, lose: { to: "VE_forge_ombre_combat" } },
      { label: "Frapper", to: "VE_forge_ombre_combat" },
    ] },
  VE_forge_ombre_combat: { act: "V", title: "L'ombre du conseiller", place: "VE_l_forge",
    combat: { title: "L'ombre du conseiller", enemies: ["VE_ombre_vendrel", { id: "VE_forgeron_cendre", n: 2 }], terrain: "bati",
      win: { fx: { set: { vendrel_v: "ombre_vaincue" }, ep: ["seance", 4000] }, to: "VE_forge_ombre_fin" },
      lose: { fx: { set: { vendrel_v: "ombre_vaincue" }, pv: -10 }, to: "VE_forge_ombre_fin" } },
    text: [
      "Les gants blancs se lèvent, ensemble, avec une élégance de maître de cérémonie, et deux forgerons de cendre se détachent des enclumes pour venir se placer à côté de l'ombre, leurs marteaux de suie sur l'épaule. « Nous nous reverrons, dit l'ombre. Plus bas. »",
    ] },
  VE_forge_ombre_fin: { act: "V", title: "Deux gants dans la cendre", place: "VE_l_forge",
    fx: { flag: "V:vendrel_fait", ep: ["seance", 3000] },
    text: [
      { if: { is: { vendrel_v: "ombre_brulee" } }, with: "charline", text: "Charline tend les deux mains, et le feu de la fente se lève derrière l'ombre comme un rideau qu'on tire, et l'enveloppe. L'ombre ne crie pas. Elle siffle, comme une bûche mouillée, et elle s'évapore en une colonne de vapeur noire qui monte jusqu'à la voûte et s'y étale. Il ne reste que les gants, qui tombent dans la cendre, roussis." },
      { if: { is: { vendrel_v: "ombre_eclairee" } }, with: "pip", text: "Pip entre dans l'eau noire du visage comme on plonge dans une mare. Pendant un moment, on voit sa lumière à travers la vase, toute petite, qui cherche. Puis la forme se fige, et se fend, comme de la glace au dégel, et Pip en ressort, trempé, frissonnant. « Il n'y avait personne, dit-il. Juste des phrases. Je les ai éteintes. »" },
      { if: { is: { vendrel_v: "ombre_dite" } }, text: "Tu lui dis : nous ne nous reverrons pas. Le gué, l'île, la princesse qui défait le col, la tache qui remue devant les deux couronnes. Les gants blancs qui tournent dans un remous. Tu lui racontes la fin de son histoire, puisqu'il ne la connaît pas. L'ombre t'écoute. Puis elle repose son marteau sur l'enclume, très doucement, et elle s'affaisse, comme quelqu'un qui s'assied enfin après une longue journée. Il ne reste qu'une flaque, et deux gants." },
      { outcome: "win", text: "L'ombre se défait sous tes coups en éclaboussant les enclumes. Les forgerons de cendre s'écroulent en tas gris. Les gants blancs tombent les derniers, l'un après l'autre, comme des feuilles." },
      { outcome: "lose", text: "L'ombre te jette contre une enclume, et tu restes là, sonné{e}, la bouche pleine de cendre. Puis elle se détourne, simplement, et descend l'escalier du fond, en répétant sa phrase. Elle ne te cherchait pas. Elle allait en bas. Tu la retrouveras peut-être." },
      "Tu ramasses les gants, ou ce qu'il en reste. La raison t'échappe. Tu les poses sur l'enclume d'Hildre, à plat, bien rangés, comme il les rangeait.",
    ],
    choices: [{ back: "VE_forge" }] },

  VE_forge_fin: { act: "V", title: "L'escalier derrière l'enclume", place: "VE_l_forge",
    fx: { flag: "V:forge", ep: ["histoire", 5000], reveal: "VE_l_chapelle" },
    text: [
      "Derrière l'enclume d'Hildre, dans le mur, une porte basse, sans battant, et un escalier qui descend. Le feu de la fente éclaire les premières marches, puis plus rien. Une odeur monte, différente encore : la cire froide, l'encens éventé, l'eau dormante d'un lac.",
      { if: { relic: "clou" }, text: "Le Clou, dans ta besace, est chaud. Pas brûlant : chaud, comme une main qui tient la tienne." },
      { if: { has: "clou:reforge" }, text: "Derrière toi, Ansgar et ses compagnons restent devant le foyer. « On va éteindre, dit le vieux maître. Doucement. On a le temps. Il a assez brûlé. »" },
      { if: { all: [{ has: "clou:reforge" }, { present: "charline" }] }, with: "charline", text: "Charline se retourne une dernière fois vers son père, sur la première marche. Il lui fait un signe de la tête. Elle descend." },
      { if: { is: { secretaire: "libre" } }, text: "Lucain Lormier est déjà parti vers le haut, par où tu es venu{e}, une lanterne à la main, nu-tête, sans gants." },
      "Tu descends. Très loin, en bas, tu entends quelque chose que tu n'aurais jamais cru entendre sous une montagne : des voix qui chantent un office.",
    ],
    choices: [{ label: "Descendre vers le chant", big: true, travel: "VE_r_chapelle" }] },
});

Object.assign(P, {
  // ================================================================== floor 3: the chapel (act II)
  VE_chap_arrivee: { act: "V", title: "Le moutier sous la montagne", place: "VE_l_chapelle",
    fx: { ep: ["seance", 2500] },
    text: [
      "L'escalier s'arrête au bord d'un lac. Un lac sous la montagne, noir, plat, si vaste que ta lumière s'y perd, et au milieu, à demi noyée, une chapelle. Un clocher carré, une nef de pierre grise, des fenêtres en ogive dont l'eau atteint le haut. Saint-Ivo. Pas celle du lac de Morteau : la première, celle qu'Ivo le Veilleur a bâtie ici, sous la Fenne, avant qu'on bâtisse l'autre en haut pour s'en souvenir.",
      "Une chaussée de pierre mène du bord jusqu'au porche, à fleur d'eau, glissante d'algues. Au-delà de la chapelle, de l'autre côté du lac, tu devines la suite de l'escalier, qui remonte de l'eau et s'enfonce dans la roche. Pour y aller, il faut traverser la nef.",
      "Et dans la nef, on chante. Des voix d'hommes, graves, à l'unisson, un office de nuit qui monte sous les voûtes noyées et revient sur l'eau en écho. Ils chantent le même verset, encore et encore. Et chaque fois, au même mot, ils s'arrêtent net, et le silence dure, et ils reprennent du début.",
      { with: "aubin", text: "Frère Aubin s'est arrêté sur la dernière marche. Il ne bouge plus. Il écoute. Il connaît ces voix. Pas celles-là, peut-être, mais le chant, le verset, l'endroit où l'on respire. Il a les lèvres qui bougent toutes seules." },
    ],
    choices: [{ label: "Avancer sur la chaussée", big: true, to: "VE_chap" }] },
  VE_chap: { act: "V", title: "La chaussée du lac", place: "VE_l_chapelle", hub: true, backName: "la chaussée du lac", ambiance: "temple",
    text: [
      { first: true, text: "La chaussée est étroite, et l'eau noire la lèche des deux côtés, sans bruit. Le chant de la nef s'arrête au mot, reprend, s'arrête. Sur le porche, au-dessus de la porte, une cloche est sculptée dans la pierre, sans battant, et sous la cloche une niche vide." },
      { again: true, text: "La chaussée, l'eau noire, le porche de Saint-Ivo. Le chant, dans la nef, qui reprend toujours au début." },
      { again: true, if: { has: "V:verset_fini" }, text: "La nef s'est tue. Le silence a quelque chose de reposé, comme une maison après le départ des invités." },
      { if: { has: "thavary:trahit" }, text: "Sur la chaussée, des traces de bottes mouillées qui s'en vont vers l'autre rive. Elles sèchent lentement." },
    ],
    choices: [
      { label: "La niche sous la cloche de pierre", hide: { seen: "VE_chap_cloche" }, to: "VE_chap_cloche" },
      { label: "Écouter le chant, sous le porche", hide: { has: "V:verset_fait" }, to: "VE_chap_moines" },
      { label: "Frère Aubin, à genoux sur la chaussée", with: "aubin", hide: { seen: "VE_chap_aubin" }, to: "VE_chap_aubin" },
      { label: "Traverser la nef noyée", big: true, to: [{ if: { all: [{ present: "thavary" }, { not: { seen: "VE_chap_thavary" } }] }, to: "VE_chap_thavary" }, { to: "VE_chap_traversee" }] },
    ] },
  VE_chap_cloche: { act: "V", title: "La niche vide", place: "VE_l_chapelle",
    text: [
      "La niche est taillée pour une cloche, une seule, de la taille d'un seau. Le fond est une dalle de pierre grise, usée en rond, polie par le bord d'une cloche qu'on y a posée et reprise des milliers de fois. Sur le rebord, gravé : *Je veille. Qui veille avec moi ?*",
      { if: { relic: "cloche" }, text: "La Cloche d'Ivo, dans ton linge, vibre si fort que tu la sens jusque dans tes os. Elle connaît cette dalle. Elle y a dormi longtemps avant qu'on la monte à Morteau." },
      { if: { given: "cloche" }, text: "Tu n'as pas la Cloche. Tu l'as confiée à Brann, à la commanderie, et elle est quelque part entre Hautecombe et ici. La niche est vide, et elle a l'air d'attendre." },
      { if: { all: [{ not: { relic: "cloche" } }, { not: { given: "cloche" } }] }, text: "Tu n'as pas la Cloche. Tu l'as perdue, ou tu ne l'as jamais eue. La niche est vide." },
      { with: "aubin", if: { given: "cloche" }, text: "« Brann la rapportera, dit Aubin. Il l'a dit. Brann tient ce qu'il dit, c'est même tout ce qu'il sait faire. » Il n'a pas l'air tout à fait sûr de lui." },
    ],
    choices: [
      { label: "Poser la Cloche d'Ivo sur la dalle", hide: { not: { relic: "cloche" } }, fx: { flag: "V:cloche_sonnee", ep: ["histoire", 3500], conf: { aubin: 10 } }, to: "VE_chap_cloche_sonne" },
      { back: "VE_chap" },
    ] },
  VE_chap_cloche_sonne: { act: "V", title: "La Cloche d'Ivo", place: "VE_l_chapelle",
    text: [
      "Tu poses la Cloche sur la dalle. Elle sonne. Pas un tintement : une note, une seule, si basse et si longue qu'elle semble ne pas venir de la cloche mais de la montagne entière. L'eau du lac frissonne d'un bord à l'autre en cercles parfaits. Les voûtes de la nef résonnent. Le chant s'arrête.",
      "Et ne reprend pas. Dans le silence, la note continue, longtemps, longtemps, et tu sens, très loin en bas, quelque chose qui l'entend. Un battement, puis un autre, plus fort qu'à la porte. Comme un dormeur qu'on appelle par son nom.",
      "Quand la note s'éteint enfin, tu reprends la Cloche. Elle est tiède. Sur la dalle, là où elle était posée, l'eau a dessiné un rond parfait, qui ne sèche pas.",
      { with: "aubin", text: "Frère Aubin pleure sans bruit, les yeux ouverts. « Ils l'ont entendue, dit-il. Ils l'attendaient depuis un an. Ils pensaient que plus personne ne viendrait la sonner. »" },
    ],
    choices: [{ back: "VE_chap" }] },

  // ------------------------------------------------------------------ side quest: the last verse
  VE_chap_moines: { act: "V", title: "Le verset", place: "VE_l_chapelle", ambiance: "temple",
    fx: { questSeen: "VE_q_verset", meet: "iic_anthelme" },
    text: [
      "Sous le porche, la porte de la nef est entrouverte, et l'eau monte jusqu'à mi-hauteur. Dans la nef, sur les bancs noyés, des moines sont assis, l'eau jusqu'à la poitrine, les capuches rabattues, et ils chantent. Ils sont une vingtaine. Au premier rang, debout, un vieillard aux yeux blancs bat la mesure d'une main décharnée. Le prieur Anthelme.",
      "Tu entends le verset, enfin, en entier, ou presque : *Seigneur, garde celui qui veille dans le noir, donne-lui le pain et le sel, donne-lui la force de tenir.* Et ils s'arrêtent. Au mot *tenir*. Le prieur lève la main, la laisse retomber. Ils reprennent du début.",
      "Le prieur tourne vers toi ses yeux blancs. « Il manque la fin, dit-il. Nous l'avons perdue dans l'eau, cette nuit-là. Personne ne s'en souvient. Nous ne pouvons pas finir l'office tant que le verset n'est pas fini. Et nous ne pouvons pas partir tant que l'office n'est pas fini. » Il penche la tête. « A-t-il encore froid, en bas ? »",
      { if: { is: { ninon: "sauvee" } }, text: "Un des moines, au dernier rang, tourne la tête vers toi, et tu crois qu'il sourit. Il est jeune. Il a la même fossette que la petite Ninon du ponton de Morteau. Tu ne demandes pas." },
    ],
    choices: [
      { label: "« Je la connais, la fin. Je la chantais avant », dit Frère Aubin", who: "aubin", fx: { set: { verset: "aubin" }, conf: { aubin: 10 } }, to: "VE_chap_verset" },
      { label: "Pip s'approche de la porte, et se met à fredonner", who: "pip", fx: { set: { verset: "pip" }, conf: { pip: 5 } }, to: "VE_chap_verset" },
      { label: "Chercher la fin du verset dans le psautier du porche", test: { dom: "savoir", diff: -10, label: "Lire un psautier noyé", help: [A_CHA, { if: { has: "passe:cercle" }, v: 10 }, { if: { has: "maitre:maelle" }, v: 5 }] }, win: { fx: { set: { verset: "lu" } }, to: "VE_chap_verset" }, lose: { to: "VE_chap_moines_rate" } },
      { label: "Leur dire que tu ne sais pas", refuse: true, fx: { set: { verset: "laisse" }, flag: "V:verset_fait" }, back: "VE_chap" },
    ] },
  VE_chap_moines_rate: { act: "V", title: "Le psautier", place: "VE_l_chapelle",
    text: [
      "Le psautier est posé sur un lutrin, sous le porche, au-dessus de l'eau. Les pages sont collées entre elles, gonflées, l'encre a bavé. Tu tournes avec précaution. Tu trouves le verset. La fin a été emportée : une tache d'eau en forme de main, exactement à l'endroit des derniers mots.",
      "Le prieur attend, les yeux blancs tournés vers toi. Tu refermes le livre. Tu essaieras autrement, ou tu ne pourras rien pour eux.",
    ],
    choices: [{ back: "VE_chap" }] },
  VE_chap_verset: { act: "V", title: "La fin du verset", place: "VE_l_chapelle", ambiance: "temple",
    fx: { flag: ["V:verset_fini", "V:verset_fait"], quest: "VE_q_verset", ep: ["seance", 4000] },
    text: [
      { if: { is: { verset: "aubin" } }, with: "aubin", text: "Frère Aubin entre dans l'eau jusqu'à la taille, sa coule flottant autour de lui, et il se place au dernier rang, à côté d'un moine dont la capuche cache le visage. Il attend que le chant revienne au début. Et quand ils arrivent à *tenir*, et qu'ils s'arrêtent, il continue seul, d'une voix qui se casse au premier mot et qui tient au second : *jusqu'à ce qu'on vienne le relever.*" },
      { if: { is: { verset: "pip" } }, with: "pip", text: "Pip se pose sur le bord de la porte, et il fredonne un air que tu ne lui as jamais entendu. Pas de paroles : un air, lent, que les moines reconnaissent, parce que le prieur s'arrête de battre la mesure. Quand ils arrivent à *tenir*, Pip continue l'air, et les moines, un à un, retrouvent les mots qui vont dessus : *jusqu'à ce qu'on vienne le relever.* Pip s'arrête, surpris. « Je la connais, celle-là, dit-il tout bas. Quelqu'un me la chantait. Je ne sais pas qui. »" },
      { if: { is: { verset: "lu" } }, text: "Sous la tache d'eau, en penchant la page vers ta lumière, tu lis les lettres qui ont imprégné la page suivante, à l'envers. Tu les déchiffres une à une, et quand le chant revient au mot *tenir*, tu les dis, à voix haute, mal, sans musique : *jusqu'à ce qu'on vienne le relever.*" },
      "Le silence qui suit est différent de tous les autres. Puis le prieur Anthelme reprend le verset du début, et cette fois tous le chantent jusqu'au bout. *Donne-lui la force de tenir jusqu'à ce qu'on vienne le relever.* Et ils chantent l'amen, et l'amen dure longtemps, et quand il finit, les bancs sont vides.",
      "Il ne reste dans la nef que l'eau, et des capuches de laine qui flottent, et sur le lutrin du prieur, posé à plat, un chapelet de buis noir. Tu le prends. Tu as l'impression qu'il t'est destiné.",
    ],
    choices: [{ label: "Prendre le chapelet du prieur", fx: { item: "VE_chapelet" }, back: "VE_chap" }] },
  VE_chap_aubin: { act: "V", title: "Le dernier frère", place: "VE_l_chapelle", with: "aubin",
    fx: { conf: { aubin: 8 }, ep: ["seance", 1500] },
    text: [
      "Frère Aubin s'est agenouillé au bord de la chaussée, face à la chapelle, les mains jointes sur le genou. Il ne prie pas. Il regarde. Tu t'accroupis à côté de lui. Il parle sans tourner la tête.",
      "« La nuit où le lac a monté, à Morteau, j'étais à la taverne, dit-il. Tu le sais. Tout le monde le sait. Ce que je n'ai jamais dit, c'est que j'ai entendu la cloche sonner. De la taverne. Elle sonnait pour appeler les frères au chœur, à cause de l'eau. Et j'ai fini mon verre. »",
      { if: { is: { ida: ["dit", "elle"] } }, text: "« J'ai un fils, dit-il. Il s'appelle Ivo. Il a quelques mois, et il ne sait pas encore qu'il a un père. » Il a un petit rire mouillé. « Ida dit qu'il crie comme un chantre. Je voudrais remonter l'entendre. »" },
      { if: { is: { aubin_arc: "pretre" } }, text: "« À la tour, j'ai décidé de rester prêtre. Pas parce que je le mérite. Parce que quelqu'un doit dire les offices pour ceux d'en bas, et que je suis le seul qui reste à savoir les paroles. »" },
      { if: { is: { aubin_arc: "quitte" } }, text: "« À la tour, j'ai ôté l'habit. Je le porte encore, tu vois, parce que je n'ai rien d'autre. Mais ce n'est plus qu'une robe. C'est plus léger. Ça ne devrait pas l'être. »" },
      { if: { is: { aubin_arc: "offrande" } }, text: "« À la tour, j'ai compris ce que je dois à mes frères. Une nuit. Une nuit entière à veiller, au lieu d'une nuit à boire. » Il te regarde enfin. « Il y a quelqu'un en bas qui veille depuis quatre cents ans. Je me disais que je pourrais prendre une nuit à sa place. Ou plus. »" },
    ],
    choices: [
      { label: "Lui dire que la cloche ne sonnait pas pour lui seul", fx: { conf: { aubin: 5 } }, back: "VE_chap" },
      { label: "Ne rien dire, et rester à côté de lui", fx: { conf: { aubin: 3 }, fear: { aubin: -5 } }, back: "VE_chap" },
    ] },

  // ------------------------------------------------------------------ Thavary on the causeway (BIBLE 3)
  VE_chap_thavary: { act: "V", title: "La voix dans le lac", place: "VE_l_chapelle", with: "thavary",
    text: [
      "Au milieu de la chaussée, Thavary s'arrête. Elle regarde l'eau à sa droite. Tu regardes aussi. Dans l'eau noire, il y a un reflet qui n'est pas le sien : une grande salle de manoir, restaurée, des tapisseries aux murs, un feu dans la cheminée, et au bout d'une table chargée, une vieille femme qui sourit. Ermesinde. Et derrière elle, par les fenêtres, les prés de l'Anse et la forêt de Brécy, qui sont à nouveau à Thavar.",
      "« Dame de Thavar », dit l'eau, avec la voix de Vendrel, polie, posée. Puis avec une autre voix, celle d'une femme, plus douce, plus vieille : « Tu as tenu ta part assez longtemps, ma fille. Les Thavar ont porté la honte quatre cents ans. Il suffit d'un geste pour que ce soit fini. Il suffit de le lui prendre et de venir. »",
      { if: { relic: "anneau" }, text: "Thavary regarde ta main. L'Anneau. Elle ne le regarde pas comme un bijou : elle le regarde comme on regarde une porte." },
      { if: { is: { thavary_arc: "vengeance" } }, text: "À la tour, devant la statue de Thavar, elle a juré de faire payer ceux qui ont menti. Tu vois le serment remuer derrière ses yeux, et l'eau qui le regarde remuer, et qui sourit." },
    ],
    choices: [
      { label: "Attendre ce qu'elle va faire", big: true, to: [
        { if: TRAHIT, to: "VE_chap_trahison" },
        { if: HESITE, to: "VE_chap_thavary_hesite" },
        { to: "VE_chap_thavary_fidele" },
      ] },
    ] },
  VE_chap_thavary_fidele: { act: "V", title: "Une dette payée", place: "VE_l_chapelle", with: "thavary",
    fx: { conf: { thavary: 10 }, flag: "V:thavary_fidele", ep: ["seance", 3000] },
    text: [
      "Thavary s'accroupit au bord de la chaussée, et elle regarde le reflet de sa grand-mère, longtemps, avec une tendresse que tu ne lui as jamais vue. Puis elle plonge la main dans l'eau, en plein dans le visage d'Ermesinde, et elle le brouille, comme on efface un dessin sur une vitre embuée.",
      { if: { has: "thavary:aveu" }, text: "« J'ai déjà dit non, dit-elle à l'eau. Une fois à Vendrel, au fond de moi, sans oser. Une fois devant {hero}, à voix haute, une nuit, à Merle. Je ne vais pas le répéter à une flaque. » Elle se relève, s'essuie la main sur sa cuisse." },
      { if: { not: { has: "thavary:aveu" } }, text: "« Ma grand-mère ne m'a jamais appelée ma fille, dit-elle à l'eau. Elle m'appelle Thavary, ou petite sotte. Tu ne la connais pas. Tu ne connais que ce qu'on te donne, et je ne t'ai rien donné. » Elle se relève, s'essuie la main sur sa cuisse." },
      "Elle te rejoint sans un mot de plus, et elle passe devant toi sur la chaussée, l'épée au clair, comme si de rien n'était. Mais en passant, elle t'effleure l'épaule de la sienne. C'est tout. C'est beaucoup.",
    ],
    choices: [{ label: "Continuer vers la nef", to: "VE_chap_traversee" }] },
  VE_chap_thavary_hesite: { act: "V", title: "Le pas qu'elle ne fait pas", place: "VE_l_chapelle", with: "thavary",
    fx: { flag: ["thavary:hesite", "V:thavary_fidele"], conf: { thavary: 15 }, ep: ["histoire", 4000] },
    text: [
      "Thavary fait un pas vers l'eau. Puis un autre. Elle est au bord de la chaussée, les bottes dans l'algue, et elle regarde la grande salle de Thavar comme on regarde une maison dont on a rêvé toute sa vie. Tu restes immobile. Tu as compris, d'un coup, tout ce qu'elle ne t'a pas dit à Merle, la nuit où elle s'est tue.",
      "Elle se retourne vers toi. Elle a les yeux secs et la mâchoire serrée. « Vendrel m'a promis les terres, dit-elle très vite. Contre l'Anneau. À Hautmont, avant la guerre. J'ai dit ni oui ni non. Je l'ai gardé pour moi, comme une pièce d'or dans une poche trouée, pour le cas où. Je ne te l'ai pas dit. Je ne l'ai dit à personne. » Elle respire. « Voilà. C'est dit. »",
      "Elle se tourne vers l'eau une dernière fois. « Garde tes prés, dit-elle. Une maison qu'on rachète avec ça, ce n'est plus une maison. C'est une dette. Et les Thavar en ont assez. »",
      "Puis elle revient sur la chaussée, à côté de toi, et elle reste là, l'épaule contre la tienne, le temps que ses mains cessent de trembler.",
    ],
    choices: [{ label: "Continuer vers la nef", to: "VE_chap_traversee" }] },
  VE_chap_trahison: { act: "V", title: "Le geste", place: "VE_l_chapelle", with: "thavary",
    text: [
      "Thavary regarde le reflet longtemps. Puis elle se tourne vers toi, et elle a le visage calme d'une décision prise depuis longtemps, depuis Hautmont peut-être, ou depuis Merle, la nuit où elle n'a rien dit.",
      { if: { relic: "anneau" }, text: "« Donne-moi l'Anneau, dit-elle. Il est à ma maison. Il a toujours été à ma maison. Tu le sais. » Sa main est posée sur la garde de son épée. Elle ne la tire pas. Pas encore." },
      { if: { not: { relic: "anneau" } }, text: "« Je n'ai rien à te prendre, dit-elle. Tu n'as pas l'Anneau. Tant mieux. Ça m'évite de choisir comment. » Elle recule d'un pas sur la chaussée, vers l'autre rive." },
      "« Ma grand-mère a quatre-vingt-trois ans, dit-elle. Elle a vendu ses bagues une à une pour payer le pain. Elle va mourir dans une maison où il pleut dans les chambres. Toi, tu vas descendre et faire quelque chose de grand, et peut-être que le monde sera sauvé, et le toit de Thavar continuera de fuir. » Elle sourit, presque. « Je ne suis pas une héroïne, {hero}. Je suis la dernière d'une maison. »",
    ],
    choices: [
      { label: "Lui tendre l'Anneau", hide: { not: { relic: "anneau" } }, fx: { relicLose: "anneau" }, to: "VE_chap_trahison_fuite" },
      { label: "Lui dire qu'elle se trompe de dette", hide: { not: { relic: "anneau" } }, test: { dom: "social", diff: -20, label: "Retenir Thavary", help: [A_PIP, A_AUB, { if: { clue: "m_testament" }, v: 10 }] }, win: { fx: { ep: ["seance", 3000], flag: "V:thavary_convaincue" }, to: "VE_chap_trahison_garde" }, lose: { to: "VE_chap_trahison_combat" } },
      { label: "Refuser, et tirer ton arme", hide: { not: { relic: "anneau" } }, to: "VE_chap_trahison_combat" },
      { label: "La laisser partir", hide: { relic: "anneau" }, to: "VE_chap_trahison_depart" },
      { label: "Lui barrer la chaussée", hide: { relic: "anneau" }, to: "VE_chap_trahison_combat" },
    ] },
  VE_chap_trahison_combat: { act: "V", title: "L'épée de Thavar", place: "VE_l_chapelle",
    combat: { title: "Thavary de Thavar", enemies: ["VE_thavary"], terrain: "bati",
      win: { fx: { ep: ["histoire", 4000] }, to: "VE_chap_trahison_garde" },
      lose: { to: [{ if: { relic: "anneau" }, to: "VE_chap_trahison_prise" }, { to: "VE_chap_trahison_depart" }] } },
    text: [
      "Elle tire l'épée de Thavar, celle qui a quatre cents ans comme le mensonge, et elle se met en garde, à la manière ancienne, la lame haute. Elle te salue d'abord. Elle le fait toujours.",
      "« Je suis désolée, dit-elle. Je le pense. Mais ça ne change rien à ce que je vais faire. »",
    ] },
  VE_chap_trahison_prise: { act: "V", title: "La main tendue", place: "VE_l_chapelle",
    text: [
      "Tu es à genoux sur la chaussée, l'épée de Thavar sous le menton. Elle te tend la main, la paume ouverte. Elle attend. Elle ne frappera pas. Tu le sais. Elle le sait. Mais elle peut attendre très longtemps.",
    ],
    choices: [{ label: "Lui donner l'Anneau", fx: { relicLose: "anneau" }, to: "VE_chap_trahison_fuite" }] },
  VE_chap_trahison_fuite: { act: "V", title: "Les bottes mouillées", place: "VE_l_chapelle",
    fx: { flag: ["thavary:trahit", "vole:anneau", "V:thavary_anneau"], leave: "thavary", conf: { coliane: -5 }, ep: ["seance", 2000] },
    text: [
      "Elle le prend. Elle le passe à son doigt, le pouce, parce qu'il est trop grand pour les autres. L'Anneau de Thavar reprend sa place sur une main de Thavar, et pendant une seconde, il brille, d'une lumière grise et sale, et Thavary ferme les yeux comme quelqu'un qui reçoit un coup.",
      "« Merci », dit-elle. Elle ne se moque pas. Puis elle part sur la chaussée, vers l'autre rive, vers l'escalier qui descend, à grands pas, sans courir. L'eau, de chaque côté, s'écarte pour la laisser passer.",
      { with: "coliane", text: "Coliane a un couteau dans la main, prêt à partir. Elle regarde Thavary s'éloigner, et elle le baisse. « Elle t'a salué{e} avant de se battre, dit-elle. Je n'arrive pas à lancer un couteau dans le dos de quelqu'un qui salue. C'est idiot. »" },
      { with: "pip", text: "Pip se tait. Il regarde partir la chevalière, et sa lumière s'est faite si petite qu'on ne la voit presque plus." },
    ],
    choices: [{ label: "Reprendre ton souffle sur la chaussée", back: "VE_chap" }] },
  VE_chap_trahison_garde: { act: "V", title: "Ce qu'elle laisse", place: "VE_l_chapelle",
    fx: { flag: ["thavary:trahit", "V:thavary_sans_anneau"], leave: "thavary" },
    text: [
      { outcome: "win", if: { not: { has: "V:thavary_convaincue" } }, text: "L'épée de Thavar vole et tombe sur la chaussée, à tes pieds. Thavary reste debout, désarmée, une main sur l'épaule, là où tu l'as touchée. Elle regarde l'épée. Elle ne la ramasse pas." },
      { outcome: "win", if: { not: { has: "V:thavary_convaincue" } }, text: "« Garde-la, dit-elle. Garde l'Anneau. Je ne vais pas me battre à mains nues pour une bague. Mais je ne remonte pas non plus. » Elle recule, vers l'autre rive. « Il m'a promis les terres. Il y a peut-être un autre moyen de les avoir, plus bas. Je vais voir. »" },
      { if: { has: "V:thavary_convaincue" }, text: "Elle t'écoute. Tu lui parles du testament de Thavar, de la honte qu'il a laissée à ses héritiers et qu'ils ont portée, de ce qu'elle porterait de plus si elle prenait l'Anneau de cette façon. Elle t'écoute jusqu'au bout, la main sur la garde. Puis elle la retire. « Garde-le, dit-elle. Tu as raison. Je ne le volerai pas. Mais je ne peux pas descendre avec toi non plus. Il m'a promis les terres. Je vais voir s'il les a encore, plus bas. »" },
      "Elle s'en va sur la chaussée, à grands pas, sans courir, vers l'escalier de l'autre rive. Tu la regardes disparaître dans la roche. L'eau, de chaque côté, s'écarte pour la laisser passer.",
    ],
    choices: [{ label: "Reprendre ton souffle sur la chaussée", back: "VE_chap" }] },
  VE_chap_trahison_depart: { act: "V", title: "Les bottes mouillées", place: "VE_l_chapelle",
    fx: { flag: "thavary:trahit", leave: "thavary" },
    text: [
      { outcome: "lose", text: "Tu es à terre, sur les pierres glissantes, l'épaule en sang. Elle remet son épée au fourreau. Elle ne t'aide pas à te relever. Elle ne t'achève pas non plus." },
      "« Ne me suis pas », dit-elle. Et elle part sur la chaussée, à grands pas, sans courir, vers l'autre rive et l'escalier qui descend. L'eau, de chaque côté, s'écarte pour la laisser passer.",
      { if: { given: "anneau" }, text: "Tu penses à Ermesinde, à qui tu as rendu l'Anneau. À ce que Thavary va trouver, plus bas, si quelqu'un remonte de Thavar avec lui. Tu ne sais pas si tu dois avoir peur pour la vieille dame ou pour sa petite-fille." },
      { with: "pip", text: "Pip regarde partir la chevalière, et sa lumière s'est faite si petite qu'on ne la voit presque plus." },
    ],
    choices: [{ label: "Reprendre ton souffle sur la chaussée", back: "VE_chap" }] },

  // ------------------------------------------------------------------ the crossing of the drowned nave
  VE_chap_traversee: { act: "V", title: "La nef noyée", place: "VE_l_chapelle", ambiance: "temple",
    text: [
      "La nef de Saint-Ivo est pleine d'eau jusqu'aux chapiteaux. On ne peut pas la traverser à pied : il faut nager, ou longer les murs sur l'étroite corniche des fenêtres, à fleur d'eau, jusqu'au chœur, où une porte s'ouvre sur l'autre rive.",
      { if: { not: { has: "V:verset_fini" } }, text: "Et les moines sont là. Ceux qui chantaient sur les bancs se sont levés, et ils se sont tournés vers toi, l'eau jusqu'à la poitrine, les capuches rabattues sur des visages que tu ne vois pas. Ils ne chantent plus. Ils barrent la nef, épaule contre épaule, comme on barre une porte." },
      { if: { has: "V:verset_fini" }, text: "La nef est vide. Les capuches de laine flottent sur l'eau, et la porte du chœur, au fond, est ouverte. Il n'y a plus personne pour garder quoi que ce soit." },
    ],
    choices: [
      { label: "Traverser à la nage", hide: { not: { has: "V:verset_fini" } }, fx: { set: { chapelle_voie: "verset" } }, to: "VE_chap_fin" },
      { label: "Lever la Cloche d'Ivo au-dessus de l'eau", hide: { any: [{ has: "V:verset_fini" }, { not: { has: "V:cloche_sonnee" } }] }, fx: { set: { chapelle_voie: "cloche" } }, to: "VE_chap_fin" },
      { label: "« Laisse-moi leur parler. Ce sont mes frères », dit Frère Aubin", who: "aubin", hide: { has: "V:verset_fini" }, test: { dom: "social", diff: -10, label: "Parler aux moines noyés", help: [A_AUB, { if: { item: "VE_chapelet" }, v: 10 }] }, win: { fx: { set: { chapelle_voie: "aubin" }, conf: { aubin: 10 } }, to: "VE_chap_fin" }, lose: { to: "VE_chap_combat" } },
      { label: "Longer la corniche des fenêtres, en silence", hide: { has: "V:verset_fini" }, test: { dom: "discretion", diff: -20, label: "La corniche de Saint-Ivo", help: [A_COL, A_GLO, A_PIP] }, win: { fx: { set: { chapelle_voie: "corniche" }, ep: ["seance", 2500] }, to: "VE_chap_fin" }, lose: { to: "VE_chap_combat" } },
      { label: "Les forcer à te laisser passer", hide: { has: "V:verset_fini" }, to: "VE_chap_combat" },
      { back: "VE_chap" },
    ] },
  VE_chap_combat: { act: "V", title: "Les moines de Saint-Ivo", place: "VE_l_chapelle", ambiance: "temple",
    combat: { title: "Les moines noyés", enemies: [{ id: "VE_moine_noye", n: 3 }], terrain: "bati", spare: true,
      win: { fx: { set: { chapelle_voie: "combat" }, ep: ["seance", 4000] }, to: "VE_chap_fin" },
      calm: { fx: { set: { chapelle_voie: "apaises" }, ep: ["seance", 4000] }, to: "VE_chap_fin" },
      lose: { fx: { set: { chapelle_voie: "emporte" }, pv: -10 }, to: "VE_chap_fin" } },
    text: [
      "Ils avancent dans l'eau, lentement, sans bruit, et ils tendent les mains vers toi. Ce ne sont pas des mains qui frappent. Ce sont des mains qui retiennent, qui tirent vers le bas, qui veulent qu'on reste. L'eau monte avec eux.",
    ] },
  VE_chap_fin: { act: "V", title: "L'autre rive", place: "VE_l_chapelle",
    fx: { flag: "V:chapelle", ep: ["histoire", 5000], reveal: "VE_l_fort" },
    text: [
      { if: { is: { chapelle_voie: "verset" } }, text: "Tu nages dans la nef vide, entre les capuches qui flottent. L'eau est froide, mais elle ne te retient pas. Elle n'a plus personne à retenir." },
      { if: { is: { chapelle_voie: "cloche" } }, text: "Tu lèves la Cloche d'Ivo au-dessus de ta tête, en avançant dans l'eau, et sans qu'on la touche, elle sonne encore, plus doucement. Les moines s'écartent. Ils inclinent la tête, l'un après l'autre, comme on s'incline devant le Saint-Sacrement qu'on porte en procession. Tu passes entre eux. Ils se referment derrière toi, et reprennent leur verset." },
      { if: { is: { chapelle_voie: "aubin" } }, with: "aubin", text: "Frère Aubin entre dans l'eau devant toi, et il parle aux moines comme on parle à des frères, à voix basse, en les appelant par leur nom de religion. Il leur dit qu'il est en retard d'un an. Il leur demande pardon. Les moines l'écoutent, immobiles. Puis le premier s'écarte, et les autres, et Aubin passe au milieu d'eux en touchant les épaules, une à une, comme on salue au réfectoire." },
      { if: { is: { chapelle_voie: "corniche" } }, text: "Tu longes la corniche des fenêtres, le dos contre la pierre, les talons dans le vide. Les moines regardent le milieu de la nef, là où l'on nage. Ils ne regardent pas les murs. Personne, jamais, ne regarde les murs." },
      { if: { is: { chapelle_voie: "combat" } }, text: "Le dernier moine coule sans résistance, comme on s'endort. Les autres flottent déjà, les capuches gonflées d'eau. Tu traverses la nef en les écartant. Ils sont légers. Ils ont toujours été légers." },
      { if: { is: { chapelle_voie: "apaises" } }, text: "Ta voix, ou ton sort, ou ta chanson les atteint au milieu de la nef. Ils baissent les mains. Ils restent debout dans l'eau, la tête inclinée, et ils te laissent passer, et quand tu es passé{e}, l'un d'eux reprend le verset, tout bas, et s'arrête au même mot." },
      { if: { is: { chapelle_voie: "emporte" } }, text: "Ils te tirent sous l'eau, et tu crois que c'est fini. Puis ils te lâchent, d'un coup, et le courant de la nef t'emporte jusqu'au chœur, et tu t'agrippes à la porte, et tu te hisses de l'autre côté, sur les marches, en vomissant de l'eau noire." },
      "Derrière le chœur, l'escalier remonte de l'eau et s'enfonce dans la roche. Plus haut sur les marches, l'air sent la pierre sèche, la poussière, et autre chose, que tu as appris à reconnaître sur l'Isarde : l'huile des armes, le cuir des baudriers. Des hommes en armes attendent, plus bas.",
    ],
    choices: [{ label: "Descendre vers l'odeur des armes", big: true, travel: "VE_r_fort" }] },
});

Object.assign(P, {
  // ================================================================== floor 4: the fort (act III)
  VE_fort_arrivee: { act: "V", title: "Le fort des Six", place: "VE_l_fort",
    fx: { ep: ["seance", 2500] },
    text: [
      "L'escalier débouche dans une salle si haute que la voûte se perd dans le noir, et au fond de la salle, il y a un fort. Un vrai fort, bâti sous la montagne : un mur de pierres taillées, des créneaux, deux tours carrées, une porte à herse. Le poste de garde des Six. C'est ici qu'Aldar et Orine montaient la garde, à tour de rôle, quand il fallait encore garder quelque chose. Leurs blasons sont sculptés au-dessus de la porte, la tour et le croissant, côte à côte, rongés par le salpêtre.",
      "Le fort est occupé. Des lanternes aux créneaux, des feux de camp dans la cour, des silhouettes en armes qui vont et viennent sur le chemin de ronde. Des gants noirs. Les épées du Cercle. Ils sont une trentaine, peut-être plus. Ils ont barricadé la porte de l'intérieur avec des tonneaux et des madriers, et ils ont planté devant, dans le sol de la salle, une bannière bleue au cercle brisé.",
      "Une sentinelle te voit, et crie un nom. Pas le tien : un nom de chef. Sur le chemin de ronde, au-dessus de la herse, une femme s'avance et pose les mains sur le créneau. Des gants noirs. Une cicatrice. Un chignon gris serré. Veyra de Hautcastel.",
      { if: { is: { embuscade: "perdue" } }, text: "La dernière fois que tu l'as vue, à la Gorge-Blanche, tu étais à terre, et elle t'enjambait pour prendre ce qu'elle était venue chercher." },
      { if: { is: { embuscade: "gagnee" } }, text: "La dernière fois que tu l'as vue, à la Gorge-Blanche, elle reculait dans le torrent, l'épaule ouverte, en te regardant comme on regarde quelqu'un qu'on reverra." },
      { if: { is: { embuscade: "parlee" } }, text: "La dernière fois que tu l'as vue, à la Gorge-Blanche, vous parliez. Elle t'avait dit ce qu'elle savait. Elle attendait que tu comprennes." },
    ],
    choices: [{ label: "Approcher du fort", big: true, to: "VE_fort" }] },
  VE_fort: { act: "V", title: "Devant la herse", place: "VE_l_fort", hub: true, backName: "la salle devant le fort",
    text: [
      { first: true, text: "Tu t'arrêtes à portée de voix, hors de portée d'arbalète. Personne ne tire. Veyra te regarde du haut du mur, longtemps. Puis elle dit, d'une voix qui porte sans qu'elle ait à la forcer : « On t'attendait. Prends ton temps. On a tout le temps, ici. »" },
      { again: true, text: "La salle devant le fort, les feux de camp derrière les créneaux, les gants noirs sur le chemin de ronde. La herse est toujours baissée." },
      { again: true, if: { has: "V:brann_fort" }, text: "Brann et ses frères ont établi un camp contre le mur de la salle, en face du fort, à vingt pas de la bannière du Cercle. Deux ordres qui se regardent par-dessus un fossé de quatre cents ans." },
      { again: true, if: { has: "V:couronnes_fort" }, text: "Les soldats des couronnes ont dressé leurs pavois au pied de l'escalier. Ils regardent le fort comme on regarde un siège qu'on ne voudrait pas faire." },
    ],
    choices: [
      { label: "Parler à Veyra, au pied de la herse", hide: { has: "V:veyra_fait" }, to: "VE_fort_veyra" },
      { label: "Des pas lourds dans l'escalier : des gants gris", hide: { any: [{ seen: "VE_fort_brann" }, { not: { any: [{ given: "cloche" }, { is: { jeton: ["ordre", "deux"] } }] } }] }, to: "VE_fort_brann" },
      { label: "Un vieil homme qui descend avec une lanterne", hide: { any: [{ seen: "VE_fort_onfroi" }, { not: { given: "anneau" } }] }, to: "VE_fort_onfroi" },
      { label: "Des soldats sous deux bannières", hide: { any: [{ seen: "VE_fort_couronnes" }, { not: { is: { couronne: ["aldaran", "velorin", "paix"] } } }] }, to: "VE_fort_couronnes" },
      { label: "Le garçon qui monte la garde au coin du mur", hide: { has: "V:page_fait" }, to: "VE_fort_page" },
      { label: "Un homme du Cercle qui te regarde depuis la poterne", hide: { any: [{ seen: "VE_fort_josse" }, { not: { is: { josse: ["soigne", "menace", "reconnu"] } } }, { is: { coliane_arc: "vengeance" } }] }, to: "VE_fort_josse" },
      { label: "Thavary, sur le chemin de ronde", hide: { any: [{ not: { has: "thavary:trahit" } }, { has: "V:thavary_fort" }, { all: [{ given: "anneau" }, { not: { seen: "VE_fort_onfroi" } }] }] }, to: "VE_fort_thavary" },
      { label: "Lire la lettre de Thavar", hide: { any: [{ not: { item: "VE_lettre_thavar" } }, { seen: "VE_fort_lettre" }] }, to: "VE_fort_lettre" },
      { label: "Franchir le fort et descendre", big: true, if: { has: "V:veyra_fait" }, why: "La herse est baissée, et Veyra tient le fort.", to: "VE_fort_fin" },
    ] },

  // ------------------------------------------------------------------ Veyra
  VE_fort_veyra: { act: "V", title: "Veyra de Hautcastel", place: "VE_l_fort",
    fx: { meet: "veyra", flag: "veyra:vue" },
    text: [
      "Veyra descend du mur par une échelle et sort par la poterne, seule, sans arme à la main. Elle s'arrête à trois pas de toi. De près, elle a l'air plus vieille que dans ton souvenir, et plus fatiguée, et ses yeux sont très clairs. « Tu sais ce qu'il y a en bas, dit-elle. Tu as eu le temps de l'apprendre, depuis la Gorge-Blanche. Un homme. Un guérisseur. Le plus jeune des Six. Cloué à une porte par ses amis pour qu'il ne la lâche pas. »",
      "« L'Ordre le garde depuis quatre cents ans, et il le sait. Edrin le sait. Brann le sait. J'ai porté le gant gris vingt ans avant de l'apprendre, et le jour où je l'ai appris, je l'ai jeté dans la Sorbe. » Elle lève une main gantée de noir. « Le Cercle m'a donné une épée et des gens. Je vais descendre. Je vais casser ce qui le tient. Et je vais le ramener à la lumière, et je vais lui rendre son nom, et le monde regardera enfin en face ce qu'il a fait. »",
      "« Pour ça, il me faut les clés. Ce qui ferme peut ouvrir. » Elle regarde ta besace. « Donne-les-moi, ou viens avec moi. Je ne te demande rien d'autre. »",
      { if: { clue: "r3_veyra" }, text: "Elle a vendu des renseignements aux deux couronnes, sur l'Isarde, pour faire durer la guerre. Elle croyait affaiblir l'Ordre. Elle n'a jamais compris de qui venait l'or. Tu le vois dans ses yeux : elle ne le comprend toujours pas." },
      { if: { seen: "VE_fort_brann" }, text: "Elle jette un coup d'œil, une seule fois, vers le camp de Brann, contre le mur. « Le sénéchal, dit-elle. Il a mis le temps. »" },
    ],
    choices: [
      { label: "Lui apporter toute la vérité, et ses preuves", big: true, if: VEYRA_PREUVE, why: "Il te faudrait savoir qui était vraiment Malvoran, et ce qu'est la Voix, et pouvoir le prouver.", to: "VE_fort_veyra_preuve" },
      { label: "Lui dire ce que tu as compris de la Voix", hide: VEYRA_PREUVE, test: { dom: "social", diff: -30, label: "Faire douter Veyra", help: [{ if: { item: "lettre_maitre" }, v: 10 }, { if: { clues: "M", min: 3 }, v: 5 }, { if: { clues: "V", min: 2 }, v: 10 }, A_AUB, A_PIP] }, win: { fx: { ep: ["histoire", 4000] }, to: "VE_fort_veyra_doute" }, lose: { to: "VE_fort_veyra_combat" } },
      { label: "Lui proposer un duel, à l'ancienne, devant les siens", fight: { title: "Veyra de Hautcastel", enemies: ["VE_veyra"], terrain: "bati",
        win: { fx: { ep: ["histoire", 6000] }, to: "VE_fort_veyra_vaincue" }, lose: { to: "VE_fort_veyra_passe" } } },
      { label: "« Elle parle. Pendant qu'elle parle, je passe », dit Coliane", who: "coliane", test: { dom: "discretion", diff: -20, label: "Passer le fort de nuit", help: [A_COL, A_PIP, A_GLO] }, win: { fx: { set: { veyra: "contournee" }, flag: "V:veyra_fait", conf: { coliane: 10 }, ep: ["histoire", 4000] }, to: "VE_fort_contourne" }, lose: { to: "VE_fort_veyra_combat" } },
      { label: "Lui donner tes clés", tag: "Marque +1", stain: true, hide: { relics: { max: 0 } }, fx: { mark: 1, set: { veyra: "cles" }, flag: ["V:veyra_fait", "V:cles_veyra"], conf: { pip: -15, aubin: -10 } }, to: "VE_fort_veyra_cles" },
      { label: "Prendre le fort par la force", to: "VE_fort_veyra_combat" },
      { back: "VE_fort" },
    ] },
  VE_fort_veyra_preuve: { act: "V", title: "La preuve", place: "VE_l_fort",
    fx: { flag: ["veyra:ralliee", "V:veyra_fait"], set: { veyra: "ralliee" }, regard: { veyra: "allie" }, fac: { cercle: 10, ordre: 5 }, ep: ["histoire", 7000], conf: { pip: 10, aubin: 10, charline: 5 } },
    text: [
      "Tu lui dis tout. Pas ce que tu crois : ce que tu sais. Les six mains, la sixième intacte sous le moulin, le nom gratté. La comptine. La chronique de l'an trois, *Malvoran le Guérisseur*. Le tombeau, la niche murée, *il a tenu la porte*. Ce qu'a dit Edrin à Hautecombe, de sa voix d'aveugle : *nous avons eu peur qu'il lâche*. Elle t'écoute sans bouger. Elle sait tout cela. Elle hoche la tête à chaque fois.",
      "Puis tu lui parles de la Voix. De la femme dans l'eau. De ce qu'elle est : non pas lui, mais ce qu'il serait devenu s'il avait cédé, sa rancune debout, née de quatre cents ans de noir. De ce qu'elle veut : que le Sceau casse, et que la souillure, qui est son corps à elle, se répande. Tu lui dis que casser n'est pas délivrer. Tu lui dis qu'elle a été menée par la main depuis le jour où elle a jeté son gant dans la Sorbe.",
      { if: { item: "lettre_maitre" }, text: "Tu lui tends la lettre de ta maîtresse. Elle la lit deux fois, debout, à la lueur d'un feu de camp. À la seconde lecture, ses mains tremblent." },
      "Veyra reste longtemps en silence. Puis elle ôte ses gants noirs, l'un après l'autre, et elle regarde ses mains, et elle a un rire bref, terrible. « Tous les rêves, dit-elle. Toutes les nuits. Une femme dans l'eau qui me disait : *libère-le, toi seule le comprends*. Je croyais que c'était lui qui m'appelait. » Elle jette les gants par terre. « Elle s'est servie de lui. Elle s'est servie de moi. Elle s'est servie de sa propre douleur pour lui mettre une épée dans le dos. »",
      "Elle se tourne vers le fort, et elle crie un ordre, et la herse se lève. « On descend avec toi, dit-elle. Pas pour casser. Pour tenir la porte de ce côté-ci, le temps que tu fasses ce que tu as à faire. Après, tu me diras ce que je dois à cet homme. Je le paierai. »",
    ],
    choices: [{ back: "VE_fort" }] },
  VE_fort_veyra_doute: { act: "V", title: "Le doute", place: "VE_l_fort",
    fx: { flag: "V:veyra_fait", set: { veyra: "doute" }, regard: { veyra: "curieux" } },
    text: [
      "Tu ne lui apportes pas de preuve. Tu lui apportes ce que tu as vu : Barthélemy et sa fille qui ne savait pas le nom de son chien, Vendrel qui a forgé une couronne pour un mort, l'eau qui promet à chacun ce qu'il veut entendre. Tu lui demandes ce qu'elle a entendu, elle, dans l'eau.",
      "Veyra prend son temps. Elle regarde le sol, longtemps. « Des rêves, dit-elle enfin. Une femme dans l'eau qui me dit que moi seule je le comprends. » Elle relève la tête. « Ça ne prouve rien. Tout le monde rêve. »",
      "Mais elle fait un signe vers le mur, et la herse se lève, à moitié, juste assez pour passer courbé. « Passe, dit-elle. Je ne descends pas avec toi. Je ne te barre pas la route non plus. Je vais rester ici et réfléchir. Si tu remontes, tu me diras qui avait raison. »",
    ],
    choices: [{ back: "VE_fort" }] },
  VE_fort_veyra_combat: { act: "V", title: "L'assaut du fort", place: "VE_l_fort",
    combat: { title: "Veyra et ses épées", enemies: ["VE_veyra", { id: "VE_epee_noire", n: 2 }], terrain: "bati",
      win: { fx: { ep: ["histoire", 6000] }, to: "VE_fort_veyra_vaincue" }, lose: { to: "VE_fort_veyra_passe" } },
    text: [
      "Veyra recule d'un pas, et tire son épée, une longue lame grise à la garde simple, l'épée d'un frère de l'Ordre. Deux de ses gants noirs sortent de la poterne et viennent se placer à ses côtés, en silence. Ils ont fait ça toute leur vie.",
      { if: { has: "V:couronnes_fort" }, text: "Derrière toi, les soldats des couronnes lèvent leurs pavois et avancent vers la porte du fort, pour occuper les autres. Personne ne viendra aider Veyra de ce côté-là." },
      { if: { has: "V:brann_fort" }, text: "Brann et ses frères se sont levés. Ils ne s'avancent pas : ils attendent, la main sur la garde, comme des témoins à un duel." },
    ] },
  VE_fort_veyra_vaincue: { act: "V", title: "Veyra à terre", place: "VE_l_fort",
    fx: { flag: "V:veyra_fait" },
    text: [
      "Veyra tombe à genoux, l'épée grise plantée dans le sol à côté d'elle, une main sur la blessure. Les gants noirs, sur le mur, ont baissé leurs arbalètes. Ils attendent. Elle lève les yeux vers toi, et il n'y a pas de peur dedans. Seulement une colère fatiguée, et quelque chose comme du soulagement.",
      "« Tu vas descendre, dit-elle. Avec les clés. Et tu vas refermer la porte sur lui, encore, comme les autres. » Elle crache du sang. « Fais-le, alors. Mais regarde-le en face, au moins. Eux, ils ne l'ont jamais fait. »",
    ],
    choices: [
      { label: "Lui dire, maintenant, ce qu'est la Voix", hide: { not: VEYRA_PREUVE }, fx: { flag: "veyra:ralliee", set: { veyra: "ralliee" }, regard: { veyra: "allie" }, ep: ["histoire", 4000] }, to: "VE_fort_veyra_ralliee_tard" },
      { label: "L'épargner, et lui laisser son fort", fx: { set: { veyra: "epargnee" }, regard: { veyra: "redevable" }, conf: { pip: 5, aubin: 5 } }, back: "VE_fort" },
      { label: "En finir", fx: { set: { veyra: "morte" }, conf: { pip: -10, aubin: -5, thavary: 5 }, fac: { cercle: -15 } }, to: "VE_fort_veyra_morte" },
    ] },
  VE_fort_veyra_ralliee_tard: { act: "V", title: "Après le combat", place: "VE_l_fort",
    text: [
      "Tu t'agenouilles devant elle, et tu lui dis tout, comme on panse une plaie, vite et sans ménagement. Les six mains, le nom gratté, la niche murée, Edrin. La femme dans l'eau, ce qu'elle est, ce qu'elle veut. Veyra écoute, à genoux, la main sur sa blessure. Elle ne t'interrompt pas une seule fois.",
      "Quand tu as fini, elle ferme les yeux. « J'aurais dû te laisser parler avant », dit-elle. Elle tend la main vers toi, et tu l'aides à se relever. Elle se tient debout avec peine. « Mes gens tiendront la porte de ce côté. Moi, je ne vais pas loin, comme ça. Mais je tiendrai aussi. C'est la seule chose que je sais faire. »",
    ],
    choices: [{ back: "VE_fort" }] },
  VE_fort_veyra_morte: { act: "V", title: "La bannière tombée", place: "VE_l_fort",
    text: [
      "Tu le fais. Elle te regarde jusqu'au bout. Sur le mur, un des gants noirs crie quelque chose, un nom, son nom à elle, peut-être son vrai nom, celui d'avant l'Ordre. Puis ils se taisent tous.",
      "Ils ouvrent la herse eux-mêmes. Ils sortent un par un, ôtent leurs gants noirs, les jettent au pied de la bannière bleue, et s'en vont par l'escalier qui remonte, sans un regard pour toi. Ils ne te combattront pas. Ils n'ont plus de raison de le faire. Ils n'en ont plus aucune.",
      { with: "pip", text: "Pip se pose sur l'épée grise plantée dans le sol, et il y reste. Quand tu l'appelles, il met longtemps à revenir." },
    ],
    choices: [{ back: "VE_fort" }] },
  VE_fort_veyra_passe: { act: "V", title: "Elle passe devant", place: "VE_l_fort",
    fx: { flag: "V:veyra_fait", set: { veyra: "devant" }, pv: -6 },
    text: [
      "Tu es à terre, devant la herse, l'épée de Veyra posée à plat sur ton épaule, comme pour un adoubement. Elle ne coupe pas. « Tu es têtu{e}, dit-elle. C'est bien. Il en faudra, en bas. »",
      "Elle ne prend rien. Elle te regarde, la tête penchée, puis elle se retourne vers le fort et fait un geste. Ses gens sortent, en ordre, les lanternes à la main, et ils prennent l'escalier du fond, celui qui descend. Elle passe la dernière. « Je pars devant, dit-elle. Je n'ai pas besoin de tes clés pour arriver à la porte. J'en aurai besoin pour l'ouvrir. On se retrouvera là-bas. »",
      "La herse reste levée derrière elle. Le fort est vide.",
    ],
    choices: [{ back: "VE_fort" }] },
  VE_fort_veyra_cles: { act: "V", title: "Les clés données", place: "VE_l_fort",
    text: [
      "Tu ouvres ta besace. Veyra ne tend pas la main. Elle attend que tu les lui poses dans les paumes, l'une après l'autre, et elle les regarde avec une sorte de crainte, comme on regarde un enfant qu'on vous confie. Puis elle les rend. « Non, dit-elle. Garde-les jusqu'à la porte. Je veux que tu voies. Je veux que tu sois là quand je les tournerai. »",
      "La herse se lève. Les gants noirs s'écartent pour te laisser passer, et ils inclinent la tête, comme devant un des leurs. Ta paume te brûle. Elle aime ce que tu viens de promettre.",
    ],
    choices: [{ back: "VE_fort" }] },
  VE_fort_contourne: { act: "V", title: "Par le chemin de ronde", place: "VE_l_fort",
    with: "coliane",
    text: [
      "Pendant que Veyra parle, Coliane recule d'un pas, puis d'un autre, et disparaît dans l'ombre du mur. Tu continues de répondre, de poser des questions, de faire durer. Veyra s'en rend compte trop tard, quand un sifflet bref monte de l'autre côté du fort, du côté de l'escalier qui descend.",
      "« Ta voleuse, dit Veyra, sans colère. Elle a pris la poterne du fond. » Elle te regarde, et il y a presque de l'admiration dans ses yeux. « Va. Je ne vais pas lancer trente épées derrière toi pour une affaire de poterne. On se reverra en bas, de toute façon. »",
    ],
    choices: [{ back: "VE_fort" }] },

  // ------------------------------------------------------------------ the returns: Brann, Onfroi, the crowns, Josse
  VE_fort_brann: { act: "V", title: "Le sénéchal", place: "VE_l_fort",
    fx: { meet: "brann", flag: "V:brann_fort", fac: { ordre: 10 }, ep: ["seance", 3000] },
    text: [
      "Ils descendent l'escalier derrière toi, une dizaine, en cottes de mailles, le gant gris à la main gauche, des lanternes au bout de piques. Devant, plus grand que les autres, la barbe grise, la balafre, les mains de bûcheron : Brann, sénéchal de l'Ordre de la Main. Il a l'air d'avoir marché trois jours sans dormir. C'est probablement le cas.",
      "« Edrin m'a envoyé, dit-il. Il a dit : *la dernière fois, nous ne sommes pas venus. Cette fois, va.* » Il regarde le fort, la bannière du Cercle, Veyra sur le mur. Il ne dit rien sur elle. Il la connaît depuis trente ans.",
      { if: { given: "cloche" }, text: "Il fait un signe, et un frère s'avance avec un coffret de chêne, et Brann l'ouvre lui-même. Dedans, sur un linge blanc, la Cloche d'Ivo. Elle a été polie, et sur sa robe de bronze, on a gravé à neuf, en lettres fines, la prière des veilleurs, et au-dessous, une main ouverte. « Bénie à Hautecombe, dit Brann. Par Edrin lui-même, qui ne voit plus rien et qui a trouvé la cloche à tâtons. Tu nous l'as confiée. L'Ordre la rend. » Il te la tend. « Avec ses excuses. C'est la première fois que l'Ordre s'excuse en quatre cents ans. Je ne sais pas si on fait ça bien. »" },
      { if: { not: { given: "cloche" } }, text: "« On n'a rien à te rendre, dit-il. Tu as gardé ce que tu as trouvé. Peut-être que tu as eu raison. On vient seulement tenir ce que tu ne pourras pas tenir seul{e}. »" },
      { if: { has: "R:revele" }, text: "Il te regarde, et tu vois qu'il sait que tu sais. Il ne baisse pas les yeux. « Oui, dit-il, avant que tu aies rien demandé. Je savais. Edrin savait. On a choisi de se taire, pour la paix. J'en répondrai, quand ce sera fini. Pas maintenant. »" },
      { if: { has: "passe:ordre" }, text: "Il remarque ta main, le geste que tu fais sans y penser, la paume à plat. Il te le rend. « Tu as porté le gris, dit-il. Je ne sais plus ce qu'on est, toi et moi. Mais on est encore quelque chose. »" },
    ],
    choices: [
      { label: "Reprendre la Cloche d'Ivo", hide: { not: { given: "cloche" } }, fx: { relic: "cloche", flag: ["cloche:benie", "V:cloche_rendue"], ep: ["histoire", 3000] }, back: "VE_fort" },
      { label: "« Tenez la salle. Il pourrait remonter quelque chose. »", hide: { given: "cloche" }, back: "VE_fort" },
    ] },
  VE_fort_onfroi: { act: "V", title: "L'intendant de Thavar", place: "VE_l_fort",
    fx: { meet: "VE_onfroi" },
    text: [
      "Un vieil homme descend l'escalier, seul, une lanterne à la main, un bâton de marche dans l'autre, un sac de toile en bandoulière. Il s'arrête souvent pour souffler. Il porte un pourpoint élimé aux couleurs fanées de Thavar, et il a ciré ses bottes pour descendre sous la montagne. Onfroi, l'intendant du manoir. Il a soixante-dix ans et n'a pas été payé depuis deux.",
      { if: { is: { gages: ["payes", "thavary", "argent"] } }, text: "« On a été payés, dit-il en arrivant, avant même de saluer. Je voulais que vous le sachiez. On a été payés, et c'est à cause de vous. Alors quand Madame a dit qu'il fallait quelqu'un pour descendre, j'ai levé la main. »" },
      { if: { not: { has: "thavary:trahit" } }, text: "Il ouvre son sac et en sort un coffret de cuir, et dans le coffret, l'Anneau de Thavar, et une lettre pliée, scellée de cire grise. « Madame vous le rend, dit-il. Elle dit que les Thavar l'ont gardé assez longtemps pour savoir ce qu'il pèse, et que c'est à vous de le porter, maintenant, jusqu'en bas. Elle a trouvé la lettre dans le coffre de la crypte, sous le testament, en le rangeant. Elle dit que vous devez la lire. Elle dit qu'elle l'a lue, elle, et qu'elle a pleuré, et qu'elle ne pleure jamais. »" },
      { if: { has: "thavary:trahit" }, text: "Il ouvre son sac. Le coffret de cuir est là. Il est vide. Onfroi le regarde comme s'il ne comprenait pas. « Demoiselle Thavary, dit-il. Elle était là, sur le mur, quand je suis arrivé. Elle est descendue. Elle m'a demandé le coffret, et je le lui ai donné. C'est sa maison. C'est son anneau. » Il sort la lettre, seule, scellée de cire grise. « Elle n'a pas voulu la lettre. Elle a dit qu'elle savait déjà ce qu'il y avait dedans. »" },
    ],
    choices: [
      { label: "Prendre l'Anneau et la lettre", hide: { has: "thavary:trahit" }, fx: { relic: "anneau", item: "VE_lettre_thavar", flag: ["anneau:lettre", "V:anneau_rendu"], ep: ["histoire", 3000], regard: { VE_onfroi: "allie" } }, back: "VE_fort" },
      { label: "Prendre la lettre", hide: { not: { has: "thavary:trahit" } }, fx: { item: "VE_lettre_thavar", flag: ["anneau:lettre", "V:onfroi_vole", "vole:anneau"] }, back: "VE_fort" },
    ] },
  VE_fort_lettre: { act: "V", title: "La lettre de Thavar", place: "VE_l_fort",
    fx: { flag: "V:lettre_thavar_lue", ep: ["seance", 1500] },
    text: [
      "Tu brises la cire grise. Le papier est si vieux qu'il se fend aux plis. L'écriture est grande, appliquée, l'écriture d'un homme de guerre qui n'avait pas l'habitude d'écrire, et qui s'y est repris à plusieurs fois.",
      "*À celui qui n'a plus de nom, de Thavar qui en a trop. Je t'écris parce que je n'ai pas le courage de descendre te le dire. Nous avons décidé ce soir. Les trois clés. La chaîne. Le nom effacé. J'ai voté avec les autres. J'ai eu peur comme les autres. Je garde l'Anneau, et je le donnerai à mes fils, et à leurs fils, pour qu'ils sachent ce que je n'ose pas leur dire. Si un jour quelqu'un descend avec cette lettre, c'est que l'un de mes enfants a été plus brave que moi. Pardonne-nous. Non. Ne nous pardonne pas. Tiens seulement. Je tiens ma part, à ma manière, qui est petite. Thavar.*",
      { if: { has: "thavary:trahit" }, text: "Tu penses à Thavary, quelque part en bas, avec l'Anneau à son pouce. Elle savait ce qu'il y avait dans cette lettre. Elle l'a refusée quand même." },
      { with: "thavary", text: "Thavary lit par-dessus ton épaule. Elle se tait. À la fin, elle prend la lettre, la replie très soigneusement, et te la rend. Elle a le menton qui tremble et elle le tient droit quand même." },
    ],
    choices: [{ back: "VE_fort" }] },
  VE_fort_couronnes: { act: "V", title: "Les couronnes descendent", place: "VE_l_fort",
    fx: { flag: "V:couronnes_fort", ep: ["seance", 2500] },
    text: [
      "Des pas, dans l'escalier. Beaucoup de pas, ordonnés, qui marchent au même rythme. Puis des pavois, des piques, des lanternes, et des tabards que tu reconnais.",
      { if: { is: { couronne: "paix" } }, text: "Des piquiers d'Aldaran, le tabard bleu à la tour d'argent. Des arbalétriers de Vel-Orin, le pourpre au croissant d'or. Ensemble, en une seule colonne, qui ne sait pas très bien comment marcher ensemble. À leur tête, un homme aimable en manteau gris, qui te salue d'un sourire comme s'il te croisait au marché. Morn, le maître-espion d'Orsini. « La princesse et la duchesse vous envoient leurs compliments, dit-il, et soixante hommes, à se partager. Elles se sont disputé l'honneur de payer leur solde. La duchesse a gagné. Elle gagne toujours. »" },
      { if: { is: { couronne: "aldaran" } }, text: "Des piquiers d'Aldaran, le tabard bleu à la tour d'argent, une quarantaine, menés par un vieux soldat au nez cassé deux fois. Hugues de Vaux, le connétable. « Le roi est mort, dit-il, à la Saint-André. La princesse règne. Elle m'a dit : *va voir ce qu'il y a sous la montagne, et ne laisse personne nous le cacher encore une fois.* » Il regarde le fort. « Alors me voilà. »" },
      { if: { is: { couronne: "velorin" } }, text: "Des arbalétriers de Vel-Orin, le pourpre au croissant d'or, une quarantaine, et à leur tête un homme aimable en manteau gris. Morn, le maître-espion d'Orsini. « La duchesse fait ses comptes, dit-il, et elle n'aime pas les colonnes qu'elle ne comprend pas. Celle-ci, notamment. » Il montre la montagne, du menton. « Elle m'a envoyé voir. Avec quarante hommes, parce qu'elle a compté qu'il en faudrait quarante. »" },
      { if: { has: "merle:sauve" }, text: "Parmi les soldats, un batelier de Merle, en sabots, avec une gaffe au lieu d'une pique. Il s'est engagé pour venir. « Vous avez sauvé le village, dit-il quand il te voit. On s'est dit qu'il fallait que quelqu'un de chez nous soit là. »" },
      "Ils dressent leurs pavois au pied de l'escalier. Ils ne prendront pas le fort pour toi. Mais ils empêcheront qu'on le reprenne derrière toi.",
    ],
    choices: [{ back: "VE_fort" }] },
  VE_fort_josse: { act: "V", title: "Josse Ferlan", place: "VE_l_fort",
    fx: { meet: "josse", flag: "V:josse_vu" },
    text: [
      "Il est assis sur le seuil de la poterne, un gant noir à la main, l'autre main nue. Josse Ferlan. Plus maigre qu'au fossé de Morteau, plus vieux qu'au camp des réfugiés. Il regarde ses bottes. Il ne se lève pas quand tu approches.",
      { if: { is: { josse: "soigne" } }, text: "« Tu m'as soigné, dans le fossé, dit-il. Je ne t'ai jamais remercié{e}. Je ne savais pas comment on remercie quelqu'un pour une chose pareille, quand on a fait ce que j'ai fait. »" },
      { if: { is: { josse: "menace" } }, text: "« Tu m'as mis un couteau sous la gorge, dans le fossé, dit-il. Tu avais raison. Je l'ai pensé tous les jours depuis. »" },
      { if: { is: { josse: "reconnu" } }, text: "« Elle m'a reconnu, dans le fossé, dit-il, sans dire qui. Je croyais qu'elle allait me tuer. J'aurais préféré. »" },
      { with: "coliane", text: "Coliane s'est arrêtée à trois pas. Elle le regarde. Il ne la regarde pas. Ses couteaux sont à sa ceinture, et ses mains en sont loin." },
      { with: "coliane", if: { is: { coliane_arc: "pitie" } }, text: "« Lève-toi, Josse », dit-elle. Pas méchamment. Il se lève. « Tu n'as rien à faire avec ces gens-là. Remonte. Va à Hautgrès. Il n'y a plus personne, là-bas. Plante quelque chose. Ce sera toujours ça. »" },
      { with: "coliane", if: { is: { coliane_arc: "justice" } }, text: "« Brann est là, dit-elle. Contre le mur. Va le trouver. Dis-lui ce que tu as fait à Hautgrès, tout, devant ses frères. Après, ce sera à eux de décider. Pas à moi. » Il hoche la tête. Il le fera. Tu le sais." },
      "Il jette son gant noir dans la poussière. « Je ne me battrai pas, dit-il. Pas pour elle. Je me suis assez battu pour des promesses. » Il se lève, et il s'en va vers l'escalier qui remonte, sans armes, les mains dans les poches.",
    ],
    choices: [{ back: "VE_fort" }] },

  // ------------------------------------------------------------------ side quest: Veyra's squire
  VE_fort_page: { act: "V", title: "Le page", place: "VE_l_fort",
    fx: { questSeen: "VE_q_page", meet: "VE_galien" },
    text: [
      "Au coin du mur du fort, là où la lumière des feux n'arrive plus, un garçon monte la garde, seul, avec une arbalète trop grande pour lui. Quinze ans, peut-être. Des gants noirs qui lui tombent sur les doigts. Il te voit, et il lève l'arbalète, et ses mains tremblent si fort que le carreau saute de la rainure et tombe par terre. Il le ramasse, rouge jusqu'aux oreilles.",
      "« Galien, dit-il, quand tu lui demandes son nom. Page de Dame Veyra. Je porte son épée quand elle ne la porte pas. » Il regarde la herse, puis toi, puis l'escalier qui remonte. « Elle dit qu'on va délivrer un homme qu'on a enchaîné. Que c'est la chose la plus juste qu'on puisse faire. » Il avale sa salive. « Je la crois. Mais j'ai peur. Je n'ai jamais eu aussi peur. Ma mère tient une boutique de chandelles à Ferrance. Elle ne sait pas où je suis. »",
    ],
    choices: [
      { label: "Lui donner de quoi remonter, et un mot pour sa mère", if: { gold: { min: 10 } }, why: "Tu n'as pas dix sous à lui donner pour la route.", fx: { gold: -10, set: { page: "renvoye" }, quest: "VE_q_page", flag: "V:page_fait", conf: { pip: 5, aubin: 5 }, regard: { VE_galien: "redevable" }, ep: ["seance", 2500] }, to: "VE_fort_page_fin" },
      { label: "Lui dire que la peur n'est pas une raison de partir", fx: { set: { page: "reste" }, quest: "VE_q_page", flag: "V:page_fait", conf: { thavary: 3 } }, to: "VE_fort_page_fin" },
      { label: "Lui confier le gant gris de l'ossuaire, à rapporter à la commanderie", hide: { not: { item: "VE_gant_ancien" } }, fx: { drop: "VE_gant_ancien", set: { page: "messager" }, quest: "VE_q_page", flag: "V:page_fait", fac: { ordre: 5 }, ep: ["seance", 2500] }, to: "VE_fort_page_fin" },
      { label: "Le laisser à sa garde", refuse: true, fx: { set: { page: "laisse" }, flag: "V:page_fait" }, back: "VE_fort" },
    ] },
  VE_fort_page_fin: { act: "V", title: "L'escalier qui remonte", place: "VE_l_fort",
    text: [
      { if: { is: { page: "renvoye" } }, text: "Galien prend les pièces, le mot, et il te regarde comme on regarde quelqu'un qui vient de vous ouvrir une porte qu'on croyait murée. Il pose l'arbalète contre le mur, avec soin, comme une chose qu'on rend. Puis il s'en va vers l'escalier, en courant presque, en se retournant deux fois. Dame Veyra ne le voit pas partir. Ou elle le voit, et elle ne dit rien." },
      { if: { is: { page: "messager" } }, text: "Galien prend le gant gris, le gant d'un frère mort depuis deux cents ans, dur comme du bois. Il le tient à deux mains. « À la commanderie du Val, dit-il. Au sénéchal, ou à quelqu'un. Pour qu'ils sachent qu'en bas, il y en a des centaines. » Il le glisse sous son pourpoint. Il a un but, maintenant. Il s'en va vers l'escalier sans courir, et ça change tout." },
      { if: { is: { page: "reste" } }, text: "Galien t'écoute. Il redresse les épaules, il raffermit sa prise sur l'arbalète, et il hoche la tête, deux fois, comme un garçon à qui l'on vient de dire qu'il est un homme. Il reste à son coin de mur. Tu le regardes en t'éloignant. Il tremble toujours. Il reste quand même." },
    ],
    choices: [{ back: "VE_fort" }] },

  // ------------------------------------------------------------------ Thavary at the fort, if she left at the chapel
  VE_fort_thavary: { act: "V", title: "Sur le chemin de ronde", place: "VE_l_fort",
    fx: { flag: "V:thavary_fort" },
    text: [
      "Elle est sur le mur, avec les gants noirs, mais à l'écart, seule, l'épée de Thavar en travers des genoux. Elle descend quand elle te voit, par l'échelle, et elle sort par la poterne, et elle s'arrête devant toi. Elle n'a pas l'air d'une traîtresse. Elle a l'air de quelqu'un qui n'a pas dormi.",
      { if: { has: "V:thavary_sans_anneau" }, text: "Elle n'a pas l'Anneau. Elle a regardé ta main, en arrivant, puis ailleurs." },
      { if: { any: [{ has: "V:thavary_anneau" }, { has: "V:onfroi_vole" }] }, text: "L'Anneau de Thavar est à son pouce. Elle le fait tourner sans arrêt, du bout de l'index, comme on tourne une pensée." },
      "« Vendrel n'est pas là, dit-elle. Il n'est pas en bas non plus, je crois. Il n'y a que Veyra, et ses gens, et l'eau. L'eau me dit que c'est encore plus bas. Que tout est toujours encore plus bas. » Elle a un rire court. « J'ai fait tout ce chemin pour une promesse, et la promesse n'a pas d'adresse. »",
    ],
    choices: [
      { label: "« Rends-le. Et remonte chez toi. »", hide: { not: { any: [{ has: "V:thavary_anneau" }, { has: "V:onfroi_vole" }] } }, test: { dom: "social", diff: -20, label: "Convaincre Thavary", help: [{ if: { item: "VE_lettre_thavar" }, v: 15 }, A_PIP, A_AUB] }, win: { fx: { relic: "anneau", set: { thavary_v: "rendu" }, unflag: "vole:anneau", ep: ["histoire", 4000] }, to: "VE_fort_thavary_fin" }, lose: { fx: { set: { thavary_v: "garde" } }, to: "VE_fort_thavary_fin" } },
      { label: "Lui reprendre l'Anneau par l'épée", hide: { not: { any: [{ has: "V:thavary_anneau" }, { has: "V:onfroi_vole" }] } }, fight: { title: "Thavary de Thavar", enemies: ["VE_thavary"], terrain: "bati",
        win: { fx: { relic: "anneau", set: { thavary_v: "vaincue" }, unflag: "vole:anneau", ep: ["histoire", 4000] }, to: "VE_fort_thavary_fin" }, lose: { fx: { set: { thavary_v: "garde" } }, to: "VE_fort_thavary_fin" } } },
      { label: "« Remonte. Ta grand-mère t'attend. »", hide: { any: [{ has: "V:thavary_anneau" }, { has: "V:onfroi_vole" }] }, fx: { set: { thavary_v: "remonte" } }, to: "VE_fort_thavary_fin" },
      { label: "La laisser où elle est", fx: { set: { thavary_v: "laissee" } }, back: "VE_fort" },
    ] },
  VE_fort_thavary_fin: { act: "V", title: "Thavary", place: "VE_l_fort",
    text: [
      { if: { is: { thavary_v: "rendu" } }, text: "Elle t'écoute. Puis elle ôte l'Anneau de son pouce, lentement, et le pose dans ta main, et referme tes doigts dessus avec les siens. « Il est plus lourd sur une main qui l'a volé, dit-elle. Je ne savais pas. Personne ne me l'avait dit. » Elle s'en va vers l'escalier qui remonte. Elle ne se retourne pas. Elle marche droit." },
      { if: { is: { thavary_v: "vaincue" } }, text: "Elle tombe à genoux. L'Anneau roule sur la pierre, et tu le ramasses. Elle ne le regarde pas. Elle regarde l'épée de Thavar, par terre, à côté d'elle. « Quatre cents ans, dit-elle. Et la dernière qui la porte s'en sert pour ça. » Elle la ramasse, la remet au fourreau, et s'en va vers l'escalier qui remonte, en boitant." },
      { if: { is: { thavary_v: "garde" } }, text: "Elle secoue la tête. Elle garde l'Anneau. « Je ne sais pas encore ce que je vais en faire, dit-elle. Mais c'est moi qui vais décider. Pour une fois, c'est moi. » Elle remonte sur le mur, et elle se rassoit à l'écart, l'épée en travers des genoux. Tu la retrouveras peut-être plus bas. Ou jamais." },
      { if: { is: { thavary_v: "remonte" } }, text: "« Ma grand-mère », répète-t-elle. Elle reste un long moment immobile. Puis elle hoche la tête, une fois, et elle s'en va vers l'escalier qui remonte, sans un mot de plus. Au pied des marches, elle s'arrête, et elle te salue de l'épée, à la manière ancienne. Puis elle monte." },
    ],
    choices: [{ back: "VE_fort" }] },

  VE_fort_fin: { act: "V", title: "La porte du fond", place: "VE_l_fort",
    fx: { flag: "V:fort", ep: ["histoire", 5000], reveal: "VE_l_glacier" },
    text: [
      "Tu traverses le fort. La cour, les feux, les râteliers, la chapelle minuscule où Aldar et Orine priaient chacun de son côté, sur deux prie-Dieu tournés dos à dos. Au fond, une deuxième herse, levée, et un escalier qui descend.",
      { if: { is: { veyra: "ralliee" } }, text: "Veyra et ses gens descendent avec toi les premières marches, puis ils s'arrêtent, et ils se rangent sur les côtés, les épées tirées, pour tenir l'escalier. « On est là, dit-elle. Quoi qu'il remonte. »" },
      { if: { is: { veyra: ["epargnee", "doute"] } }, text: "Veyra te regarde passer du haut du mur. Elle ne te salue pas. Elle ne te barre pas la route." },
      { if: { is: { veyra: "devant" } }, text: "Dans la poussière des marches, des traces de bottes, des dizaines, toutes fraîches. Veyra est devant toi. Tu ne sais pas de combien." },
      { if: { has: "V:brann_fort" }, text: "Brann et ses frères prennent position dans la cour du fort, derrière toi. « On tient, dit le sénéchal. Ce coup-ci, on tient. »" },
      { with: "thavary", if: { has: "thavary:hesite" }, text: "Thavary descend à côté de toi, l'épaule contre la tienne. Depuis le lac, elle n'a plus rien à cacher, et elle marche plus légère." },
      "Le froid te prend dès la première marche. Pas le froid de la pierre : le froid de la glace, sec, mordant, qui monte d'en bas et qui sent la neige. Tu es sous le glacier, maintenant, tout au fond. Et quelque part en bas, très loin, tu entends quelque chose respirer.",
    ],
    choices: [{ label: "Descendre dans le froid", big: true, travel: "VE_r_glacier" }] },
});

Object.assign(P, {
  // ================================================================== floor 5: the glacier (act IV)
  VE_glacier_arrivee: { act: "V", title: "Le ventre de la glace", place: "VE_l_glacier",
    fx: { ep: ["seance", 2500] },
    text: [
      "L'escalier finit dans la glace. Une caverne immense, toute bleue, éclairée de l'intérieur par une lumière qui vient d'en haut, à travers des centaines de toises de glacier, une lumière d'aube qui n'a pas changé depuis quatre siècles. Des colonnes de glace montent jusqu'à la voûte. Des cascades gelées pendent des parois. Le sol est un miroir où tu marches sur ton propre reflet.",
      "Et partout, prise dans la glace, la souillure. Des coulées noires figées dans le bleu, des veines, des racines, des mains tendues vers le haut, toutes arrêtées net, comme si l'hiver les avait surprises en train de grimper. Le froid de la Fenne est la dernière chose qui la retienne, ici. Tu le comprends en voyant une coulée qui a réussi à passer, plus loin, entre deux colonnes : la glace autour d'elle est grise, malade, et elle goutte.",
      "Au fond de la caverne, une pente de glace descend vers un noir parfait. Pas une ombre : un noir. La porte. La vraie. Et devant la porte, quelque chose d'immense, couché, qui respire.",
      { if: { is: { dragon: "purifie" } }, text: "Une tête se lève, blanche, longue comme une barque, aux yeux d'un bleu pâle. Ardhal. Il est passé par la glace, comme il l'avait dit. Il t'attendait." },
      { if: { is: { dragon: "lie" } }, text: "Une tête se lève, blanche, veinée de noir, aux yeux noirs. Ardhal. Il est passé par la glace parce que tu le lui as ordonné. Ta paume se réchauffe en le voyant. La sienne aussi, sans doute, s'il en a une." },
      { if: { not: { is: { dragon: ["purifie", "lie"] } } }, text: "Ce n'est pas un vivant. Ce sont des os. Un squelette immense, couché en rond devant la porte, à demi pris dans la glace, et sur les os, une mousse noire qui palpite. Ardhal. Ou ce que l'eau en a fait." },
    ],
    choices: [{ label: "Descendre dans la caverne", big: true, to: "VE_glacier" }] },
  VE_glacier: { act: "V", title: "La caverne bleue", place: "VE_l_glacier", hub: true, backName: "la caverne bleue",
    text: [
      { first: true, text: "Tu avances sur la glace, prudemment, et chaque pas résonne longtemps dans la caverne. Le froid te mord les doigts à travers les gants. Ta respiration fait de petits nuages qui montent et gèlent en tombant. Tu es au bout de la Descente. Il ne reste que la pente, et la porte." },
      { again: true, text: "La caverne bleue, les coulées noires dans la glace, la lumière d'aube immobile. Au fond, la pente, et le noir." },
      { again: true, if: { has: "V:dragon_fait" }, text: "Devant la porte, la place est libre, maintenant." },
    ],
    choices: [
      { label: "Aller vers Ardhal", hide: { any: [{ not: { is: { dragon: "purifie" } } }, { has: "V:dragon_fait" }] }, to: "VE_glacier_ardhal" },
      { label: "Aller vers le dragon que tu tiens", hide: { any: [{ not: { is: { dragon: "lie" } } }, { has: "V:dragon_fait" }] }, to: "VE_glacier_lie" },
      { label: "Aller vers les os couchés devant la porte", hide: { any: [{ is: { dragon: ["purifie", "lie"] } }, { has: "V:dragon_fait" }] }, to: "VE_glacier_os" },
      { label: "Les silhouettes prises dans la glace", hide: { has: "V:pelerins_fait" }, to: "VE_glacier_pelerins" },
      { label: "Pip, qui regarde la porte", with: "pip", hide: { seen: "VE_glacier_pip" }, to: "VE_glacier_pip" },
      { label: "Gloup, au bord d'une coulée noire", with: "gloup", hide: { seen: "VE_glacier_gloup" }, to: "VE_glacier_gloup" },
      { label: "Coliane, qui a sorti son galet", with: "coliane", hide: { seen: "VE_glacier_coliane" }, to: "VE_glacier_coliane" },
      { label: "Descendre la pente de glace jusqu'à la porte", big: true, if: { has: "V:dragon_fait" }, why: "Le dragon est couché en travers de la pente.", to: "VE_glacier_fin" },
    ] },

  // ------------------------------------------------------------------ Ardhal, as act IV left him
  VE_glacier_ardhal: { act: "V", title: "Ardhal", place: "VE_l_glacier",
    fx: { meet: "ardhal" },
    text: [
      "Ardhal déplie son cou, lentement, et pose sa tête sur la glace devant toi, si près que son souffle te réchauffe le visage. Il est blanc, entièrement, les écailles lisses et propres comme de la neige fraîche. Le noir qui le rongeait, au glacier, a disparu. Il sent la pierre froide et le ciel.",
      "« Te voilà au bout, dit-il, et sa voix est un grondement qui fait trembler la glace sous tes pieds. Il y a quatre cents ans, j'étais là-haut, couché sur la glace, quand ils ont fermé la porte sur lui. Ils m'ont demandé de garder la montagne. Je l'ai gardée. Je savais ce qu'il y avait dessous. » Il ferme à demi les yeux. « C'est la chose dont j'ai le plus honte, de toute ma longue vie. Avoir su, et gardé. »",
      "« Mon souffle est à toi, et le feu blanc qui dort dessous. Ce que tu choisiras, en bas, il le fera. Brûler, si tu dois brûler. Réchauffer, si tu dois réchauffer. Je ne choisirai pas pour toi. J'ai assez choisi en me taisant. »",
    ],
    choices: [
      { label: "« Qu'est-ce que tu as vu, ce jour-là ? »", hide: { seen: "VE_glacier_ardhal_parle" }, to: "VE_glacier_ardhal_parle" },
      { label: "Accepter son feu", big: true, fx: { flag: ["V:dragon_fait", "V:ardhal_feu", "ardhal:allie"], ep: ["histoire", 5000], conf: { pip: 5, gloup: 5 } }, back: "VE_glacier" },
    ] },
  VE_glacier_ardhal_parle: { act: "V", title: "Ce qu'a vu Ardhal", place: "VE_l_glacier",
    fx: { ep: ["seance", 1500] },
    text: [
      "« Le matin où il est descendu, dit Ardhal, les cinq autres l'ont accompagné jusqu'au bord de la glace, avec des lampes, en chantant pour se donner du courage. Lui portait une lumière dans ses mains, une toute petite lumière, et il riait. La veille, il avait encore soigné tout le monde, jusqu'aux ampoules. Il avait des mains fines, toujours propres. »",
      "« La Brèche était ouverte, là, derrière la porte. Il fallait quelqu'un de l'autre côté pour la tenir. Ils l'avaient compris pendant la nuit, sur l'éperon. Il y avait eu un long silence. Puis le plus jeune avait dit : *moi.* Comme ça. Comme on se propose pour aller chercher de l'eau. » Le dragon souffle, et la glace se couvre de buée. « Les autres ont pleuré. Puis ils ont eu peur. Puis ils ont fait les clés. »",
      { with: "pip", text: "Pip s'est posé sur le museau du dragon, entre ses yeux pâles. Il ne bouge plus. Il écoute avec toute sa lumière." },
    ],
    choices: [{ back: "VE_glacier_ardhal" }] },
  VE_glacier_lie: { act: "V", title: "Le dragon tenu", place: "VE_l_glacier",
    fx: { meet: "ardhal" },
    text: [
      "Ardhal est couché devant la pente, la tête basse. Les veines noires de son cuir n'ont pas disparu : elles ont gelé, figées en plaques sur le blanc, et elles battent, toutes, au même rythme que ta paume. Il lève vers toi ses yeux noirs, et dans ce noir, tu vois ton propre reflet, petit, très net.",
      "« Tu m'as fait venir, dit-il. Je suis venu. Je ne pouvais pas faire autrement. » Sa voix est égale, sans colère, la voix d'un très vieux serviteur. « En bas, si tu me le dis, je brûlerai. Si tu me le dis, je tiendrai la porte ouverte. Je ferai ce que dit ta main. » Il ferme les yeux. « Je te demande une chose, une seule, avant. Lâche-moi. Laisse-moi remonter au glacier mourir comme un dragon, et pas comme un chien. »",
    ],
    choices: [
      { label: "Le garder sous ta main, jusqu'au bout", tag: "Marque +1", stain: true, fx: { mark: 1, flag: ["V:dragon_fait", "V:ardhal_feu", "V:ardhal_tenu"], set: { ardhal_v: "tenu" }, conf: { pip: -10, aubin: -10 }, fear: { pip: 10, gloup: 10 }, ep: ["histoire", 5000] }, to: "VE_glacier_lie_fin" },
      { label: "Ouvrir ta main, et le laisser partir", fx: { flag: ["V:dragon_fait", "V:ardhal_libere"], set: { ardhal_v: "libere" }, conf: { pip: 10, aubin: 10, coliane: 5 }, ep: ["histoire", 5000] }, to: "VE_glacier_lie_fin" },
    ] },
  VE_glacier_lie_fin: { act: "V", title: "La main ouverte ou fermée", place: "VE_l_glacier",
    text: [
      { if: { has: "V:ardhal_tenu" }, text: "Tu fermes la main. Il le sent. Un long frisson le parcourt, des naseaux à la queue, et les plaques noires de son cuir battent plus fort, toutes ensemble, au rythme de ton pouls. Il se tait. Il se lève, et il se range sur le côté de la pente, la tête basse, comme une bête de somme qui attend qu'on la charge. Ta paume est brûlante. Elle n'a jamais été aussi heureuse." },
      { if: { has: "V:ardhal_libere" }, text: "Tu ouvres la main. C'est plus difficile que tu ne l'aurais cru : quelque chose dans ta paume s'accroche, refuse, tire, et tu dois écarter les doigts un par un, comme on desserre le poing d'un mort. Puis c'est fait. Les plaques noires sur le cuir du dragon pâlissent, un peu, pas toutes." },
      { if: { has: "V:ardhal_libere" }, text: "Ardhal se lève. Il te regarde longtemps, de ses yeux noirs où quelque chose de pâle est revenu. « Je ne te dois rien, dit-il. Mais je m'en souviendrai. » Puis il s'enfonce dans la glace, comme dans de l'eau, et la glace se referme derrière lui, et tu entends longtemps, très loin, au-dessus, le bruit de ses ailes contre la voûte du glacier, qui remonte vers le jour." },
    ],
    choices: [{ back: "VE_glacier" }] },
  VE_glacier_os: { act: "V", title: "Les os du dragon", place: "VE_l_glacier",
    text: [
      "Tu t'approches des os. Ils sont énormes, blancs sous la mousse noire, et le crâne est posé sur la glace, de profil, l'orbite vide tournée vers toi. Tu pourrais entrer dedans debout.",
      { if: { is: { dragon: "tue" } }, text: "Tu l'as tué, au glacier. Tu as vu la vie quitter ces yeux-là. Quelqu'un a descendu ses os ici, sous la glace, et les a couchés devant la porte, avec soin, comme on couche un chien de garde mort devant la maison de son maître. Personne ne pourrait faire ça. L'eau, si." },
      "Puis la mousse noire palpite, et les os bougent. Une vertèbre, puis une autre, puis la queue qui se soulève et racle la glace. Le crâne se redresse, lentement, et dans l'orbite vide, une lueur grise s'allume, comme une flamme de chandelle au fond d'un puits. La Voix n'a pas laissé perdre un si bon gardien.",
      { with: "aubin", text: "Frère Aubin a levé la main pour bénir, et il hésite. « Ce n'est plus lui, dit-il. C'est ce qu'on a mis dedans. » Il n'abaisse pas la main pour autant." },
    ],
    choices: [
      { label: "« Laisse-moi rendre ses os au repos », dit Frère Aubin", who: "aubin", test: { dom: "magie", diff: -20, label: "Bénir les os d'Ardhal", help: [A_AUB, { if: { item: "VE_chapelet" }, v: 10 }, A_EAU] }, win: { fx: { set: { os_ardhal: "benis" }, conf: { aubin: 10 }, ep: ["histoire", 5000] }, to: "VE_glacier_os_fin" }, lose: { to: "VE_glacier_os_combat" } },
      { label: "« Les os, ça ne brûle pas. La mousse, si », dit Charline", who: "charline", test: { dom: "magie", diff: -20, label: "Brûler la mousse noire", help: [A_CHA] }, win: { fx: { set: { os_ardhal: "brules" }, conf: { charline: 10 }, ep: ["histoire", 5000] }, to: "VE_glacier_os_fin" }, lose: { to: "VE_glacier_os_combat" } },
      { label: "Te glisser le long de la paroi jusqu'à la pente", test: { dom: "discretion", diff: -30, label: "Passer le gardien d'os", help: [A_PIP, A_COL, A_GLO] }, win: { fx: { set: { os_ardhal: "contournes" }, ep: ["histoire", 4000] }, to: "VE_glacier_os_fin" }, lose: { to: "VE_glacier_os_combat" } },
      { label: "Affronter ce qui reste d'Ardhal", to: "VE_glacier_os_combat" },
    ] },
  VE_glacier_os_combat: { act: "V", title: "Le gardien d'os", place: "VE_l_glacier",
    combat: { title: "Les os d'Ardhal", enemies: ["VE_os_ardhal", { id: "VE_vase_gelee", n: 2 }], terrain: "galerie",
      win: { fx: { set: { os_ardhal: "brises" }, ep: ["histoire", 6000] }, to: "VE_glacier_os_fin" },
      lose: { fx: { set: { os_ardhal: "debout" }, pv: -12 }, to: "VE_glacier_os_fin" } },
    text: [
      "Le squelette se lève tout entier, dans un fracas de glace brisée, et déploie des ailes qui ne sont plus que des baleines d'os tendues de mousse noire. Il n'a plus de poumons. Il a encore son froid, qui sort de sa gueule ouverte et qui gèle tout ce qu'il touche. Deux coulées de vase se détachent des parois, à demi gelées, et rampent vers toi.",
    ] },
  VE_glacier_os_fin: { act: "V", title: "Ce qui reste du dragon", place: "VE_l_glacier",
    fx: { flag: "V:dragon_fait" },
    text: [
      { if: { is: { os_ardhal: "benis" } }, with: "aubin", text: "Frère Aubin marche jusqu'au crâne, et il pose les deux mains sur l'os, entre les orbites, et il dit les paroles qu'on dit pour les bêtes de ferme qu'on a aimées, et qu'aucun prêtre n'est censé dire. La lueur grise vacille. La mousse noire se détache des os comme une peau morte et glisse sur la glace en fumant. Les os se couchent, un à un, avec un bruit de bois sec. Ils ne se relèveront plus." },
      { if: { is: { os_ardhal: "brules" } }, with: "charline", text: "Charline lève les mains, et une flamme blanche court sur les os, de la queue au crâne, sans les toucher, seulement la mousse. La mousse hurle. Elle se tord, se recroqueville, tombe en cendre noire sur la glace. Les os retombent, propres, blancs, inertes. Charline baisse les mains. Elle a du givre dans les cils." },
      { if: { is: { os_ardhal: "contournes" } }, text: "Tu longes la paroi, à quelques pas de la gueule ouverte, en retenant ton souffle. La lueur grise suit ta lumière, un moment, puis la perd. Tu es au bord de la pente. Derrière toi, les os se recouchent lentement, et attendent le suivant." },
      { if: { is: { os_ardhal: "brises" } }, text: "Le crâne éclate sous ton dernier coup, et la lueur grise s'éteint dedans comme une chandelle soufflée. Les os s'effondrent, s'éparpillent sur la glace, et la mousse noire fond en flaques qui gèlent aussitôt. Au milieu des côtes, il y a quelque chose qui brille : une pierre ronde, bleue, grosse comme une tête d'enfant, tiède. Le cœur du dragon. Il bat encore, une fois, très lentement." },
      { if: { is: { os_ardhal: "debout" } }, text: "Il te jette contre une colonne, et la glace se fend derrière ton dos. Puis il se détourne, et il va se recoucher devant la porte, et il s'immobilise. Il n'a pas reçu l'ordre de tuer. Seulement celui de garder. Il te faut une heure pour te relever, et pour trouver le moyen de passer, le long de la paroi, pendant qu'il garde le milieu de la pente." },
    ],
    choices: [
      { label: "Prendre le cœur du dragon", hide: { not: { is: { os_ardhal: "brises" } } }, fx: { item: "VE_coeur_ardhal", flag: "V:coeur_ardhal" }, back: "VE_glacier" },
      { label: "Laisser les os en paix", hide: { is: { os_ardhal: "brises" } }, back: "VE_glacier" },
      { label: "Laisser le cœur battre dans les os", hide: { not: { is: { os_ardhal: "brises" } } }, back: "VE_glacier" },
    ] },

  // ------------------------------------------------------------------ side quest: the frozen pilgrims
  VE_glacier_pelerins: { act: "V", title: "Les pèlerins gelés", place: "VE_l_glacier",
    fx: { questSeen: "VE_q_pelerins" },
    text: [
      "Dans une colonne de glace plus claire que les autres, il y a des gens. Sept, debout, côte à côte, les mains jointes ou tendues, figés en plein pas. Des capes brunes, des bourdons, des médailles d'étain sur la poitrine, frappées d'une main ouverte. Des pèlerins de la Main. Ils sont descendus prier devant la porte, il y a cinquante ans ou cent, et le froid les a pris là, ensemble, sans qu'ils aient le temps de se retourner.",
      "Sur la glace, au pied de la colonne, quelqu'un a gravé avec la pointe d'un bourdon : *Nous sommes venus dire que nous savions. Nous n'avons pas pu remonter le dire aux autres.*",
      { if: { clue: "r1_pelerins" }, text: "Tu repenses aux pèlerins qui contournaient Brumefeuille, au bord de la route, cet automne, en baissant la voix. Ceux-là n'ont pas contourné." },
      "Les médailles brillent sous la glace, à un pouce de la surface. Avec du temps, et de la chaleur, on pourrait les détacher. Quelqu'un, là-haut, attend peut-être encore de savoir où sont partis les siens.",
    ],
    choices: [
      { label: "Fondre la glace pour reprendre leurs médailles", test: { dom: "nature", diff: -10, label: "Travailler la glace sans la briser", help: [A_CHA, A_GLO, { if: { item: "VE_lame_durn" }, v: 5 }] }, win: { fx: { set: { pelerins: "medailles" }, item: "VE_medailles", quest: "VE_q_pelerins", flag: "V:pelerins_fait", fac: { ordre: 5, brumefeuille: 3 }, ep: ["seance", 3000] }, to: "VE_glacier_pelerins_fin" }, lose: { fx: { set: { pelerins: "brises" }, quest: "VE_q_pelerins", flag: "V:pelerins_fait", pv: -4 }, to: "VE_glacier_pelerins_fin" } },
      { label: "Lire leurs noms sur les médailles, à travers la glace, et les retenir", fx: { set: { pelerins: "noms" }, quest: "VE_q_pelerins", flag: "V:pelerins_fait", ep: ["seance", 2000] }, to: "VE_glacier_pelerins_fin" },
      { label: "Les laisser dans leur glace", refuse: true, fx: { set: { pelerins: "laisses" }, flag: "V:pelerins_fait" }, back: "VE_glacier" },
    ] },
  VE_glacier_pelerins_fin: { act: "V", title: "Sept noms", place: "VE_l_glacier",
    text: [
      { if: { is: { pelerins: "medailles" } }, text: "Tu travailles la glace longtemps, avec ta lame, avec ton souffle, avec tes mains dans tes gants. Les médailles viennent une à une, froides à brûler, chacune au bout d'un lacet de cuir durci. Au dos de chacune, un nom gravé à la pointe, et un village. Sorbe. Ferrance. Morteau. Hautgrès. Tu les ranges dans ta besace. Elles tintent ensemble à chaque pas." },
      { if: { is: { pelerins: "brises" } }, text: "La glace éclate sous tes coups, d'un bloc, et la colonne se fend du haut en bas. Les médailles tombent avec des éclats de glace, et avec elles, un bras, une main. Tu restes un moment immobile. Puis tu ramasses ce que tu peux. Les noms, au dos, sont rayés. Tu en déchiffres trois. Tu les retiens." },
      { if: { is: { pelerins: "noms" } }, text: "Tu colles ta lanterne contre la glace, et tu lis, un par un, les noms gravés au dos des médailles, à l'envers, à travers un pouce de bleu. Sept noms, sept villages. Tu les dis à voix haute, pour les apprendre. La caverne les répète après toi, longtemps." },
      { with: "pip", text: "Pip passe devant chaque visage, lentement, et s'arrête un moment devant chacun, comme on s'arrête devant une tombe. Il se tait. Il n'a jamais été aussi sérieux." },
    ],
    choices: [{ back: "VE_glacier" }] },

  // ------------------------------------------------------------------ the companions at the last door
  VE_glacier_pip: { act: "V", title: "La lumière et la porte", place: "VE_l_glacier", with: "pip",
    fx: { conf: { pip: 10 }, flag: "V:pip_souvenir", ep: ["seance", 2000] },
    text: [
      "Pip flotte au bord de la pente, immobile, et regarde le noir au fond. Sa lumière a changé depuis la porte de bronze. Elle est plus chaude, plus dorée, et elle palpite, lentement, au rythme de ce battement que tu as senti sous ta paume, en haut, contre le bronze.",
      "« Je me souviens d'une chose, dit-il sans se retourner. Une seule. Il y avait du noir partout, et il faisait très froid, et quelqu'un m'a tenu dans ses mains, longtemps, très longtemps. Il me chantait le verset. Celui des moines. *Jusqu'à ce qu'on vienne le relever.* » Il se tait. « Il le chantait pour lui. Pas pour moi. Mais moi, je l'écoutais. »",
      "« Et puis un jour, il m'a lâché. Il a ouvert les doigts et il m'a laissé partir, vers le haut, par la fente. Je crois qu'il voulait que quelqu'un sache qu'il était encore là. » Pip se retourne enfin. « Je crois que c'était moi, le message. Et que c'est toi qui l'as reçu. »",
      { if: { mark: { min: 3 } }, text: "Il regarde ta main, la tache, longtemps. « Il aurait eu peur de toi, dit-il doucement. Je n'ai pas peur. Mais lui, il aurait eu peur. »" },
    ],
    choices: [{ back: "VE_glacier" }] },
  VE_glacier_gloup: { act: "V", title: "Gloup et la vase", place: "VE_l_glacier", with: "gloup",
    fx: { conf: { gloup: 10 }, ep: ["seance", 1500] },
    text: [
      "Gloup s'est arrêté devant une coulée noire, figée dans la glace, qui a la forme d'une main tendue vers le haut. Il la regarde. Il a la même couleur qu'elle, ou presque. Il pose contre la glace ce qui lui sert de visage, et il reste là, longtemps, sans bouger.",
      { if: { is: { gloup_arc: "propre" } }, text: "Depuis la tour, il est presque clair. On voit à travers lui, par moments, comme à travers de l'eau de pluie. La coulée noire, de l'autre côté de la glace, ne le reconnaît pas. Il recule, rassuré ou triste, tu ne sais pas." },
      { if: { is: { gloup_arc: "lui" } }, text: "Depuis la tour, il a décidé d'être ce qu'il est. Il regarde la coulée noire comme on regarde un cousin qui a mal tourné. Puis il fait un bruit, un seul, qui ressemble à un reniflement de mépris, et il revient vers toi." },
      { if: { not: { is: { gloup_arc: ["propre", "lui"] } } }, text: "Il reste collé à la glace si longtemps que tu finis par t'inquiéter, et tu l'appelles. Il revient vers toi, lentement. Il laisse sur la glace, là où il était posé, une empreinte ronde, claire, propre." },
      "Il roule jusqu'à tes bottes, et il s'y colle, avec ce petit bruit content qu'il fait toujours, et il ne bouge plus. Tu comprends qu'il a choisi de quel côté de la glace il était.",
    ],
    choices: [{ back: "VE_glacier" }] },
  VE_glacier_coliane: { act: "V", title: "Le galet de Hautgrès", place: "VE_l_glacier", with: "coliane",
    fx: { conf: { coliane: 10 }, flag: "V:galet_coliane", ep: ["seance", 1500] },
    text: [
      "Coliane est assise sur un bloc de glace, le galet percé dans la paume, celui de son frère, du gué devant chez eux. Elle le fait rouler entre ses doigts. « Je voulais le jeter dans l'eau d'en bas, dit-elle. Pour qu'il y ait quelque chose de propre dedans. »",
      { if: { is: { coliane_arc: "vengeance" } }, text: "« Je n'ai plus rien de propre, depuis le camp, dit-elle. J'ai fait ce que j'avais dit. Josse ne livrera plus personne. » Elle serre le galet. « Mon frère n'aurait pas voulu. Je l'ai fait quand même. Alors je le garde. Je n'ai pas le droit de le jeter. »" },
      { if: { is: { coliane_arc: ["pitie", "justice"] } }, text: "« Josse est remonté, dit-elle. Vivant. Je l'ai laissé partir. Je ne sais pas si c'était bien. » Elle regarde le galet. « Mon frère l'aurait laissé partir. Il était comme ça. Ça l'a tué, d'ailleurs. »" },
      { if: { has: "V:josse_vu" }, text: "« Je l'ai revu, au fort, ajoute-t-elle. Il a jeté son gant. Je ne sais pas ce que ça vaut, un gant jeté. Plus que rien. »" },
      "Elle se lève, elle va jusqu'au bord de la pente, et elle regarde le noir au fond, longtemps. Puis elle remet le galet dans sa chemise, contre sa peau. « Pas encore, dit-elle. Quand on sera en bas. Quand je verrai l'eau. »",
    ],
    choices: [{ back: "VE_glacier" }] },

  // ------------------------------------------------------------------ the end of the Descent (to lot V2)
  VE_glacier_fin: { act: "V", title: "Au bord de la pente", place: "VE_l_glacier",
    fx: { flag: "V:glacier", ep: ["histoire", 6000] },
    text: [
      { if: { all: [{ has: "V:puits" }, { has: "V:forge" }, { has: "V:chapelle" }, { has: "V:fort" }] }, text: "Tu t'arrêtes en haut de la pente. Tu te retournes, une fois. La caverne bleue, les colonnes, la lumière d'aube figée. Derrière, l'escalier, et derrière l'escalier, le fort, la chapelle, la forge, le puits, la porte de bronze, la glace, le jour. Tu as tout traversé. Tu as tout revu. Tout ce que tu as fait t'attendait sur le chemin, et tu l'as regardé en face, chaque fois.", else: "Tu t'arrêtes en haut de la pente. Tu te retournes, une fois. La caverne bleue, les colonnes, la lumière d'aube figée, et derrière, tout le chemin." },
      { if: { has: "V:main_posee" }, text: "Là-haut, sur la porte de bronze, la buée de ta main a fini par s'effacer. Tu sens encore la tiédeur du métal au creux de ta paume." },
      { if: { has: "V:main_escalier" }, text: "Quelque part dans l'escalier des mains, parmi des milliers d'autres, il y a la tienne, à plat sur la pierre, tournée vers le bas." },
      { if: { has: "V:maitre_ramenee" }, text: "Là-haut, quelque part dans l'escalier du puits, ta maîtresse remonte, une marche à la fois, en se tenant à la rampe." },
      { if: { has: "V:maitre_laissee" }, text: "Là-haut, au fond du puits, dans l'eau noire, quelqu'un qui t'a appris à tenir une arme n'a plus mal nulle part." },
      { if: { any: [{ has: "V:margot_demasquee" }, { has: "V:margot_adieu" }] }, text: "Là-haut, sur une marche du puits, il y a une robe bleue vide, et plus personne pour pousser un bateau de bois." },
      { if: { has: "V:grauk_tient" }, text: "Là-haut, au puits, des trolls ronflent sur des passerelles de bois et jettent des cailloux dans l'eau noire. Si quelque chose remonte, ils le renverront en bas." },
      { if: { has: "V:clou_rendu" }, text: "Là-haut, à la forge, un vieil homme aux mains brûlées éteint doucement un feu qui brûlait depuis quatre cents ans." },
      { if: { has: "V:verset_fini" }, text: "Là-haut, au lac, une nef noyée est vide et silencieuse, et l'office est fini." },
      { if: { has: "veyra:ralliee" }, text: "Là-haut, au fort, Veyra et ses gants noirs tiennent l'escalier, l'épée tirée, et ne laisseront rien passer, ni dans un sens, ni dans l'autre." },
      { if: { has: "V:brann_fort" }, text: "Là-haut, dans la cour du fort, Brann et ses frères tiennent, pour la première fois depuis deux cents ans." },
      { if: { has: "V:cles_veyra" }, text: "En bas, Veyra t'attend pour tourner les clés. Tu le lui as promis." },
      { if: { has: "V:pacte_vendrel" }, text: "En bas, Vendrel t'attend, avec sa clé rouge et la goutte que tu lui as donnée." },
      { if: { has: "ardhal:allie" }, text: "Derrière toi, Ardhal se lève, déplie ses ailes blanches sous la voûte de glace, et vient se poster en haut de la pente. Il a gardé cette porte quatre cents ans, d'en haut. Cette fois, il regarde ce qu'il y a en bas." },
      { if: { all: [{ has: "V:ardhal_feu" }, { not: { has: "ardhal:allie" } }] }, text: "Derrière toi, Ardhal se range en haut de la pente, la tête basse, et attend ce que dira ta main." },
      { if: { has: "V:coeur_ardhal" }, text: "Dans ta besace, le cœur du dragon bat, une fois, très lentement, contre ta hanche." },
      { if: { relics: { min: 3 } }, text: "Dans ta besace, les trois clés. Le Clou, la Cloche, l'Anneau. Elles se sont rapprochées l'une de l'autre au fond du sac, toutes seules, et elles chantent, très bas, une note à trois voix que tu sens dans ta poitrine." },
      { if: { relics: { min: 1, max: 2 } }, text: "Dans ta besace, ce qui te reste des clés. Elles se cherchent, au fond du sac, et ne se trouvent pas toutes." },
      { if: { all: [{ has: "cloche:benie" }, { relic: "cloche" }] }, text: "La Cloche d'Ivo porte sur sa robe la prière des veilleurs, gravée à neuf à Hautecombe, et une main ouverte." },
      { if: { all: [{ has: "anneau:lettre" }, { relic: "anneau" }] }, text: "L'Anneau de Thavar est à ton doigt, et la lettre de son premier porteur est pliée contre ta poitrine." },
      { if: { all: [{ has: "V:lettre_thavar_lue" }, { not: { relic: "anneau" } }] }, text: "Tu as dans ta poche la lettre de Thavar, sans l'Anneau qui allait avec. *Tiens seulement.*" },
      { if: { relics: { max: 0 } }, text: "Tu n'as aucune des trois clés. Tu descends les mains vides. Peut-être que c'est mieux. Peut-être pas." },
      { if: { mark: { min: 4 } }, text: "Ta main gauche est noire jusqu'au coude. Elle ne te fait plus mal. Elle a chaud, et elle a faim, et elle tire vers la porte comme un chien vers sa gamelle." },
      { if: { has: "V:source_lavee" }, text: "Ta paume garde la brûlure de la source, rose et tendre, là où l'eau claire a mordu la tache." },
      { if: { mark: { max: 1 } }, text: "Ta paume est presque propre. Le froid n'y mord pas plus qu'ailleurs. Rien en toi ne tire vers le bas, sauf toi." },
      { with: "any", text: "Ceux qui sont encore avec toi se rapprochent, sans qu'on le leur demande. Tous se taisent. Il n'y a plus rien à se dire qu'on ne se soit dit en route." },
      { with: "pip", if: { has: "V:pip_souvenir" }, text: "Pip se pose sur ta main, au creux de la paume, et il y tient tout entier. Il chantonne, très bas, l'air du verset." },
      { with: "coliane", if: { has: "V:galet_coliane" }, text: "Coliane a sorti le galet de Hautgrès de sa chemise. Elle le tient serré dans son poing, prête." },
      { with: "thavary", if: { has: "V:thavary_fidele" }, text: "Thavary tire l'épée de Thavar et passe devant, sur la pente, la première, comme une aînée." },
      { without: "any", text: "Tu es seul{e}. Tu descends seul{e}. C'est peut-être comme ça qu'il est descendu, lui aussi, la première fois." },
      "Au bas de la pente, le noir s'ouvre. Ce n'est pas une porte. C'est une absence de tout, une eau qui ne reflète rien, et au fond de cette eau, très loin, une forme immense, assise, la tête penchée, une main tendue vers le haut, paume ouverte. Et entre la forme et toi, debout sur l'eau, une femme faite de vase, aux cheveux d'algue, qui sourit, et qui dit ton nom.",
    ],
    choices: [{ label: "Descendre la pente", big: true, if: { has: "V:glacier" }, why: "Tu n'es pas encore au bout de la caverne.", to: "VF_seuil" }] },

  // ------------------------------------------------------------------ discussions on the way down (banter)
  VE_b_pip_gloup: { act: "V", title: "Deux choses nées en bas", with: ["pip", "gloup"],
    text: [
      "Pendant la halte, Pip et Gloup se sont retrouvés côte à côte, à l'écart, sur une marche. Gloup s'est fait tout petit. Pip brille à peine. Ils regardent tous les deux vers le bas de l'escalier.",
      "« Toi aussi, tu viens de là ? » demande Pip. Gloup fait un bruit, un seul, mouillé. Pip réfléchit. « Moi, je suis sorti par en haut. Toi, par en bas. On n'est pas sortis du même côté. » Gloup fait un autre bruit. « Oui, dit Pip. C'est vrai. On est sortis quand même. C'est ça qui compte. »",
      "Ils restent là jusqu'à ce que tu les appelles. Quand tu reprends la descente, Pip s'est posé sur Gloup, et Gloup le porte, très lentement, comme on porte une lanterne.",
    ],
    choices: [{ label: "Les laisser descendre ensemble", fx: { conf: { pip: 5, gloup: 5 } }, to: RET }] },
  VE_b_coliane_aubin: { act: "V", title: "Les mauvaises nuits", with: ["coliane", "aubin"],
    text: [
      "À la halte, Coliane s'assied à côté de Frère Aubin, ce qu'elle ne fait jamais. Elle lui tend sa gourde. Il boit. « Tu étais à la taverne, dit-elle, la nuit où tes frères sont morts. » Il hoche la tête. « Moi, j'étais à trois lieues de Hautgrès, la nuit où l'écluse s'est ouverte. Je cueillais des mûres. J'avais quatorze ans. »",
      "Aubin se tait. Elle reprend sa gourde. « Je me demandais, dit-elle, si à ton âge on arrête de se dire qu'on aurait pu être là. » Aubin réfléchit longtemps. « Non, dit-il. Mais on arrête de croire que ça aurait changé quelque chose. Et c'est pire, d'abord. Et puis c'est mieux. »",
      "Coliane hoche la tête. Elle ne le remercie pas. Elle reste assise à côté de lui jusqu'au départ.",
    ],
    choices: [{ label: "Reprendre la descente", fx: { conf: { coliane: 3, aubin: 3 } }, to: RET }] },
  VE_b_charline_thavary: { act: "V", title: "Les héritières", with: ["charline", "thavary"],
    text: [
      "Charline et Thavary marchent côte à côte dans l'escalier, depuis une heure, en silence. Puis Charline dit, sans tourner la tête : « Ma grande aïeule a forgé la chaîne. » Thavary répond, sans tourner la tête non plus : « Mon grand aïeul a voté pour qu'on la mette. »",
      "Elles marchent encore un moment. « Ça fait de nous quoi ? » demande Charline. « Des gens qui descendent la retirer, dit Thavary. Si on peut. » Charline a un petit rire. « Tu crois qu'on peut se racheter pour les autres ? » Thavary hausse les épaules. « Non. Mais on peut payer leurs dettes. Ce n'est pas pareil. C'est mieux. Ça se compte. »",
    ],
    choices: [{ label: "Les suivre dans l'escalier", fx: { conf: { charline: 3, thavary: 3 } }, to: RET }] },
});

